INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('casimedicos-eaf9ff7cb9e1', '11672fc919d6335ddea32c00830c7d6c91b1bbd4', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Un hombre de 60 años de edad con colitis ulcerosa extensa de 15 años de evolución y en remisión clínica los últimos 3 años, acude a nuestra consulta para informarse sobre el riesgo de cáncer colorrectal y sobre la posibilidad de participar en programas de prevención.', 'Es correcto informarle de que:', '[{"position": 1, "text": "La colitis ulcerosa solo se asocia a un incremento en el riesgo de cáncer colorrectal en fumadores."}, {"position": 2, "text": "En su caso, dado que está en remisión de larga duración, se considera adecuado el cribado aconsejado a la población general."}, {"position": 3, "text": "En casos como el suyo se considera adecuado someterse a colonoscopias periódicas con toma de múltiples biopsias escalonadas a lo largo de todo el colon."}, {"position": 4, "text": "En casos como el suyo se considera adecuado el cribado mediante estudios periódicos de sangre oculta en heces pero con una frecuencia superior a la utilizada en el cribado de la población general."}]'::jsonb, 4, 3, 'definitiva', 'Los pacientes con enfermedad inflamatoria intestinal (EII) tienen un riesgo aumentado de cáncer colorrectal, sean o no fumadores. Se recomienda empezar el cribado a los 8-10 años del diagnóstico de la EII (o antes si aparece en ese intervalo una colangitis esclerosante primaria o concurren otros hechos). Las técnicas recomendadas son la colonoscopia con biopsias al azar (respuesta 3) y la cromoendoscopia pancolónica con tinción, que es actualmente el gold standard porque detecta mejor la displasia, aunque requiere mayor experiencia técnica.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-30268a1e5c7f', 'a445b2758e06a1631d30738b8e6b8d90cb93a7cb', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Un hombre de 67 años, diagnosticado de cirrosis hepática y bebedor activo, ingresa por cuadro de distensión abdominal progresiva con malestar difuso, de dos semanas de evolución. No refiere fiebre ni otros síntomas. A la exploración destaca matidez cambiante a la percusión abdominal, con ausencia de edemas. Se realiza una paracentesis diagnóstica, encontrando un líquido ligeramente turbio, con 2.300 células/mL, de las cuales 30% son linfocitos, 60% polimorfonucleares y 10% hematíes.', '¿Cuál es la primera medida terapéutica que pautaría en este paciente de forma inmediata?', '[{"position": 1, "text": "Restricción de sal y líquidos."}, {"position": 2, "text": "Tratamiento diurético con espironolactona oral."}, {"position": 3, "text": "Tratamiento con una cefalosoporina de tercera generación."}, {"position": 4, "text": "Paracentesis evacuadora."}]'::jsonb, 4, 3, 'definitiva', 'Se trata de una peritonitis bacteriana espontánea (PBE), definida por presencia de > 250 polimorfonucleares/mL en el líquido ascítico (en este caso tiene 1.380, que son el 60% de 2.300). Es indicación de iniciar cefalosporinas de 3ª generación (ceftriaxona o cefotaxima) y albúmina. Lo demás son tratamientos que pueden esperar a una mejoría (no hablan de ascitis a tensión).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-232fb050b610', '413b7a428b90c07b8e67a3a90108a14df5a4713d', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'En un programa de cribado de cáncer de colon, a un paciente de 52 años se le realiza una colonoscopia. Todo el colon es de aspecto normal, salvo el hallazgo de un pólipo pediculado de 2 cm en sigma que se extirpa con asa de diatermia. El resultado anatomopatológico nos indica que existe un carcinoma in situ limitado a la cabeza del pólipo. Tiene una TC toracoabdominal informado como normal.', 'Indique cuál sería la conducta correcta a seguir.', '[{"position": 1, "text": "Resección segmentaria del colon afecto."}, {"position": 2, "text": "Vigilancia periódica endoscópica."}, {"position": 3, "text": "Resección local de la base del pólipo."}, {"position": 4, "text": "Sigmoidectomía más linfadenectomía."}]'::jsonb, 4, 2, 'definitiva', 'El carcinoma in situ está delimitado por la membrana basal, o sea que no es invasivo aún, y por tanto, el tratamiento es la polipectomía, que ya está hecha. Posteriormente conviene hacer un seguimiento endoscópico (con biopsias) con un intervalo de entre 3 y 6 meses en función de sus antecedentes, edad y patologías concomitantes.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-bc5474b4b968', '58bb28280fe918ba1922c3ef20f71da0227efcbb', NULL, NULL, NULL, false, false, 'Anatomía Patológica', 'Mujer de 20 años con tumoración ovárica de 15 cm, sólido-quística, detectada por ecografía tras presentar síntomas abdominales inespecíficos. En el estudio anatomopatológico de la pieza correspondiente se encuentran dientes, pelos, zonas de epitelio intestinal, áreas de epitelio escamoso (15%) y bronquial, así como elementos neuroectodérmicos y embrionarios en varias de las preparaciones histológicas.', 'En referencia a este caso, señale el diagnóstico correcto:', '[{"position": 1, "text": "Teratocarcinoma."}, {"position": 2, "text": "Teratoma inmaduro."}, {"position": 3, "text": "Teratoma quístico maduro."}, {"position": 4, "text": "Disgerminoma."}]'::jsonb, 4, 2, 'definitiva', 'Tras leer la pregunta y las posibles respuestas, contamos con dos opciones tumorales y dos no tumorales. En ningún momento nos comentan rasgos atípicos celulares, con lo que podemos descartar sin miedo las lesiones tumorales, quedando dudas entre las respuestas 2 y 3. En este caso, tendríamos que decantarnos por el TERATOMA INMADURO, al mencionar la presencia de restos embrionarios.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e13aa7b527f0', '2cad56ba89728d3671e4db469204dc9004486314', NULL, NULL, NULL, false, false, 'Anatomía Patológica', 'Mujer de 67 años diagnosticada de un carcinoma ductal infiltrante de mama y sin historia familiar de neoplasia.', '¿Qué estudios adicionales deben realizarse en el tumor por sus implicaciones clínico-terapéuticas?', '[{"position": 1, "text": "Estudio fenotípico completo mediante citometría de flujo."}, {"position": 2, "text": "Estudio de receptores hormonales y de HER2."}, {"position": 3, "text": "Estudio de receptores hormonales, e-cadherina y estudio de familiares de primer grado."}, {"position": 4, "text": "Estudio de BRCA 1-2 y estudio de familiares de primer grado."}]'::jsonb, 4, 2, 'definitiva', 'La respuesta correcta sería la 2, ESTUDIO DE RECEPTORES HORMONALES Y DE HER2 ya que unos receptores positivos para HER2 implican una mayor agresividad del tumor pero tratamiento con trastuzumab y unos receptores hormonales positivos implicarían la utilización de hormonoterapia. La respuesta 1 es descartable de visu, mientras que la 3 y la 4 debieran descartarse ya que al tratarse de la primera mujer en la familia con carcinoma de mama, no sería obligado el estudio de los familiares de la paciente. Así mismo, la e-cadherina es importante para el diagnóstico diferencial de un carcinoma lobulillar de mama, no de uno ductal.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-325e6a427b1d', 'eda4d97c4c8897409dd73c85a86e7e41a6771b24', NULL, NULL, NULL, false, false, 'Cirugía General', NULL, 'Señale de entre las siguientes la complicación más probable que presenta un paciente intervenido, hace 20 años, de úlcera gástrica mediante antrectoínía y gastroyeyunostomía (Billroth II) que acude a su consulta refiriendo dolor abdominal postpradial, distensión abdominal, diarrea y datos analíticos de malabsorción de grasas y de vitamina B12:', '[{"position": 1, "text": "Gastropatía por reflujo biliar."}, {"position": 2, "text": "Adenocarcinoma gástrico."}, {"position": 3, "text": "Síndrome de evacuación gástrica rápida (dumping)."}, {"position": 4, "text": "Síndrome de asa aferente con sobrecrecimiento bacteriano."}]'::jsonb, 4, 4, 'definitiva', 'El enunciado ha descrito la clínica de este síndrome. Suele ser una complicacion tardía (el paciente fue intervenido hace 20 años de un Bilroth II, recordemos que es una gastrectomia parcial, cierre del muñón gastrico y anastomosis de primera asa yeyunal al muñón), se acompaña de dolor postprandial, distensión abdominal. Lo que ha ocurrido es una estenosis del asa aferente, por lo que las secreciones biliares y pancreáticas no se mezclan con el bolo, se acumulan, producen dolor que se alivia con el vómito, no es posible la absorción de las grasas (falta la lipasa pancreatica), por lo que hay diarreas, y si se asocia con sobrecrecimiento bacteriano, hay malabsorción de vitamina B12. Si se tratara de Adenocarcinoma gástrico, habrían hablado de síndrome constitucional, manifestaciones extradigestiva (nódulo hermana Maria Jose, tumor de Krukenberg, nódulo Virchow). No es dumping porque no habla de clinica vegetativa (palpitaciones, rubefacción facial, etc…). La gastropatía por reflujo biliar es un diagnostico endoscópico, ademas no se asocia con diarreas ni con malabsorción.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-a1d2fa5c774f', 'f8d2856ee7176eac293eab562e1ea056ea0e02cc', NULL, NULL, NULL, false, false, 'Dermatología', 'Un hombre de 58 años refería una historia de 3 semanas de evolución con lesiones cutáneas progresivas, medianamente dolorosas, en su brazo izquierdo. Había empezado como una lesión eritematosa en su pulgar izquierdo. Tenía unas estrías rojizas visibles como líneas de conexión entre las lesiones. El paciente no presentaba fiebre ni otros síntomas generales. Había estado trabajando en su jardín pero no recordaba haberse hecho ninguna herida. El diagnóstico etiológico se realizó por cultivo de una biopsia cutánea.', '¿Cuál es el agente causal más probable de este proceso?', '[{"position": 1, "text": "Dermatofitosis por Microsporum gypseum."}, {"position": 2, "text": "Infección cutánea por Staphylococcus aureus."}, {"position": 3, "text": "Esporotricosis."}, {"position": 4, "text": "Infección cutánea por Mycobacterium marinum."}]'::jsonb, 4, 3, 'definitiva', 'Las lesiones con patrón esporotricoide o linfocutáneo que se describen pueden corresponder a una esporotricosis o a un granuloma de los acuarios, de modo que las dos primeras quedarían descartadas. El antecedente de haber estado trabajando en el jardín orienta más a una esporotricosis, aunque despista un poco el hecho de que la pregunta pide por el “agente causal” y no el nombre de la enfermedad, de modo que si consideramos la esporotricosis en realidad la respuesta debería ser Sporothrix schenckii Pese a ello, a sabiendas que esta pregunta será correcta para muchos examinados aunque esté mal redactada -lo cual la anula directamente- no se promoverá la impugnación.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-3f25205590b9', '403545cac6224dbac53e8f3e32752854803370a8', NULL, NULL, NULL, false, false, 'Dermatología', NULL, 'Ante un paciente de 8 años de edad que acude por presentar desde hace 3 días lesiones pustulosas superficiales, erosiones y costras amarillentas alrededor de la boca pensaremos en:', '[{"position": 1, "text": "Eritema exudativo multiforme."}, {"position": 2, "text": "Impétigo contagioso."}, {"position": 3, "text": "Acné infantil."}, {"position": 4, "text": "Psoriasis pustuloso."}]'::jsonb, 4, 2, 'definitiva', 'Es un cuadro clínico típico y frecuente en niños. Está describiendo un impétigo contagioso. No hay mucha discusión. El agente causal más frecuente en la forma ampollosa es S. aureus fago II.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-06738e735461', '2f159b8711b1b67d2949d3dcf7f451922a8aef82', NULL, NULL, NULL, false, false, 'Dermatología', 'Un paciente acude a urgencias por presentar una eritrodermia con fiebre y malestar general. En la exploración se aprecia en las uñas la presencia de piqueteado ungueal y unas zonas amarillentas distales en mancha de aceite.', '¿Cuál es la enfermedad primaria que ha originado el cuadro?', '[{"position": 1, "text": "Linfoma cutáneo."}, {"position": 2, "text": "Dermatitis atópica."}, {"position": 3, "text": "Psoriasis."}, {"position": 4, "text": "Ictiosis."}]'::jsonb, 4, 3, 'definitiva', 'Cualquiera de las 4 opciones puede ser la causa de la eritrodermia, aunque la descripción de lesiones ungueales altamente sugestivas de psoriasis hacen de este diagnóstico el más probable.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e250b93f48e9', '6b03a85ca9af12dc6aa0283f241cb92a2bccb188', NULL, NULL, NULL, false, false, 'Genética e Inmunología', 'Amalia es una niña de 3 años que ha sido intervenida de tetralogía de Fallot. Presentó además una disfunción tímica en el periodo neonatal y una hipocalcemia así como una voz nasal junto a retraso psicomotor.', '¿Qué prueba genética considera más adecuada para llegar a su diagnóstico etiológico?', '[{"position": 1, "text": "Estudio de delección 22q11 (síndrome de Di George o Velo-cardio-facial)."}, {"position": 2, "text": "Estudio de la expansión del gen FMR1, responsable del síndrome de X frágil."}, {"position": 3, "text": "Secuenciación de los genes relacionados con el HRAS (síndrome de Noonan)."}, {"position": 4, "text": "Estudio genético de síndrome de Williams Beuren."}]'::jsonb, 4, 1, 'definitiva', 'Pregunta en la que hay que reconocer el cuadro clínico: anomalías cardiovasculares – Tetralogía de Fallot -; aplasia/hipoplasia tímica -que conlleva inmunodeficiencia celular primaria por células T; aplasia/hipoplasia de paratiroides- de ahí la hipocalcemia-; anomalías del paladar – voz nasal; retraso psicomotor. En mi opinión, solo con las palabras “disfunción tímica”, hipocalcemia y cardiopatía, tendríamos que irnos directos a pensar en Síndrome de DiGeorge. Efectivamente el defecto genético es una delección 22q11.2 (que si nos lo sabemos, mejor, pero con la clínica nos bastaría). La única opción con la que podría haber duda es con el Noonan, que también puede asociar cardiopatía, pero sobre todo se caracteriza por talla baja, cardiopatía y alteraciones óseas; además, en la mayoría de los casos está producido por una alteración en el gen PTPN11, no en los que menciona la pregunta.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5d6aa699f20f', '77a4effeba2ddeb6aea127cea7afe3e5e7d78fe8', NULL, NULL, NULL, false, false, 'Genética e Inmunología', NULL, 'Indique la situación clínica que, en relación con la infección por virus de la hepatitis B, presenta un paciente de 5 años procedente de Nigeria, con exploración física normal y con la siguiente serología frente a hepatitis B: HBsAg + /ANTI- HBs – / HBeAg – / ANTI- Hbe + / ANTI- Hbc IgM – / ANTI- Hbc IgG +/ DNA VHB +:', '[{"position": 1, "text": "Infección aguda."}, {"position": 2, "text": "Infección crónica."}, {"position": 3, "text": "Paciente vacunado."}, {"position": 4, "text": "Portador asintomático."}]'::jsonb, 4, 2, 'definitiva', 'Pregunta en la que teniendo una tabla en la cabeza sale sola descartando opciones: Opción 1: La infección aguda cursaría con HBeAg + y ANTI-HBe –. Además el ANTIHBc seria tipo IgM (solo por este último dato, tendríamos que descartarla de manera directa). Opción 2: la correcta. Cumple con todas las características. Opción 3: El paciente vacunado no puede tener DNA del virus!! (Lo único que positiviza en un vacunado es el AntiBs. Tipo IgG). Opción 4: La opción que podría ofrecer más dudas. En el portador asintomático (portador crónico /seroconvertido) la diferencia es que no hay DNA viral.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4138b9763378', 'c4d114bd0e0a21d8b8adccb81f216a238735ebe3', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Paciente de 71 años, fumador de 2 paquetes de cigarrillos/día desde hace 50 años, con buena calidad de vida previa y sin otros antecedentes patológicos de interés que consulta por tos y expectoración hemoptóica. A la exploración física no se aprecian datos patológicos significativos. En la radiografía simple de tórax se evidencia una masa de 4x3,4 cm inferior derecha, hallazgo que se confirma en la TC toracoabdominal que localiza la lesión en el lóbulo inferior y no halla adenopatías ni imágenes de metástasis. La broncoscopia objetiva una lesión imfiltratnte en la pirámide basal derecha cuya biopsia es de carcinoma epidermoide bien diferenciado. En cuanto a las pruebas de función respiratoria la FVC es de 3.300 cc (84%) y la FEV 1 de 2.240 cc (80%)', '¿Cuál debería ser el siguiente paso a seguir en este paciente?', '[{"position": 1, "text": "Realizar una mediastinoscopia."}, {"position": 2, "text": "Debe contraindicarse la intervención quirúrgica con intención curativa por la edad avanzada del paciente."}, {"position": 3, "text": "Se debe llevar a cabo un test de consumo de oxígeno, dada la limitación respiratoria que presenta."}, {"position": 4, "text": "Debe indicarse la resección quirúrgica (lobectomía del lóbulo inferior del pulmón derecho) de forma directa."}, {"position": 5, "text": "Debe realizarse una punción trantorácica."}]'::jsonb, 5, 4, 'definitiva', '1 y 5: Son pruebas diagnósticas, no tienen sentido puesto que ya tienes el diagnóstico hecho. 2: La edad no debe ser un factor limitante, y menos teniendo en cuenta que son solo 71 años, pero sobre todo porque la “calidad de vida” del paciente es buena (y entrecomillo “calidad de vida” porque es un término utilizado erróneamente, se supone que quieren decir que mantiene un buen grado funcional). 3: Presenta una limitación respiratoria muy leve, no requiere de dicha prueba. 4: Es la correcta.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8ac1ecd2cb40', '4ff459e366678106379550ed610a410f438953aa', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Un paciente de 87 años con antecedentes de bronquitis crónica e insuficiencia cardiaca, ha sido diagnosticado de colecistitis aguda litiásica. Tras 4 días de hospitalización en tratamiento con dieta absoluta, sueroterapia piperacilina-tazobactam, el paciente continúa con fiebre, dolor abdominal persistente y leucocitosis..', 'La actitud más adecuada en este momento sería:', '[{"position": 1, "text": "Tratamiento quirúrgico urgente."}, {"position": 2, "text": "Drenaje biliar mediante colecistostomía percutanea."}, {"position": 3, "text": "Sustituir la piperacilina-tazobactam por metronidazol-cefotaxima."}, {"position": 4, "text": "Sustituir la piperacilina-tazobactam por amikacina-clindamicina."}, {"position": 5, "text": "Añadir al tratamiento un aminoglucósido como gentamicina."}]'::jsonb, 5, 2, 'definitiva', 'En esta pregunta, insisten en la edad y a comorbilidad del paciente, así como en el tiempo de evolución, por lo que la respuesta probablemente no será la 1. De todas formas lo ideal es drenar esa vesícula que no acaba de remontar por lo que la respuesta que yo pondría sería la 2.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-75b9c035c104', 'ff949fce2a4b6950a990d39ed612612ea3c01926', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Un hombre de 32 años natural de Camerún consulta por fiebre tos y dolor en hemitórax izquierdo de 1 mes de evolución. Tomó durante 1 semana amoxicilina-clavulánico sin mejoría de los síntomas. Se le realiza un análisis donde destaca una cifra de leucocitos de 8000/microL y una hemoglobina de 12,8 g/dL. En la radiografía de tórax se observa un derrame pleural izquierdo loculado que ocupa un tercio del hemitórax. Una toracentesis muestra un líquido amarillento con las siguientes características: hematíes 2000/uL, leucocitos 2500/ uL, con 90% de linfocitos, proteínas 4,9 g/dL, lactato deshidrogenasa 550 U/L, glucosa 67 mg/dL y ausencia de células malignas en el estudio citológico.', '¿Cuál de las siguientes pruebas sería más útil para diagnosticar la causa del derrame pleural?', '[{"position": 1, "text": "Una tomografía computarizada (TC) torácica."}, {"position": 2, "text": "Medición del pH del líquido pleural."}, {"position": 3, "text": "Medición de la adenosina desaminasa del líquido pleural."}, {"position": 4, "text": "Prueba de la tuberculina."}]'::jsonb, 4, 3, 'definitiva', 'La determinación de ADA, ante un cuadro de neumonía de larga evolución que no mejora con tratamiento antibiótico, con un derrame con abundantes leucocitos y predominio linfocítico, en que se descarta la presencia de neoplasia, con valores mayor de 70 UI/L nos tiene que hacer tener un alto grado de sospecha sobre la etiología tuberculosa y enviar el líquido pleural a microbiología para estudio de tuberculosis.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5f9ee016304a', 'b6b3223151e8ae40498bd1a8ca55db1db477dbc4', NULL, NULL, NULL, false, false, 'Nefrología', NULL, 'En una paciente con artritis reumatoide en tratamiento con metotrexate, prednisona e indometacina que presenta de forma aguda edemas y aumento de la creatinina plasmática con un sedimento de orina poco expresivo y proteinuria inferior a 100 mg/24 h la causa más probable es:', '[{"position": 1, "text": "Amiloidosis renal."}, {"position": 2, "text": "Glomerulonefritis secundaria a la artritis reumatoide."}, {"position": 3, "text": "Insuficiencia renal por antiinflamatorios no esteroideos."}, {"position": 4, "text": "Nefritis intersticial por metotrexate."}]'::jsonb, 4, 3, 'definitiva', 'La insuficiencia renal aguda prerrenal por AINEs parece la opción más plausible en este caso. La nefritis túbulo-intersticial por metotrexate es menos probable por la ausencia de rash, fiebre o eosinofilia, que aunque son poco frecuentes en el MIR suelen aparecer. Aunque en la AR es relativamente frecuente la aparición de GMN y amiloidosis renal, el sedimento de orina anodino y la ausencia de proteinuria hacen poco probables estas opciones.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-bda9c4500c00', 'dc55d53d1a332089f2f337064a0fb14902eb9da4', NULL, NULL, NULL, false, false, 'Nefrología', 'Hombre de 87 años con antecedentes de hipertensión y gonartrosis. Situación basal con autonomía funcional y cognitiva plena que le permite continuar viviendo solo en la comunidad. Realiza tratamiento habitual con perindopril y diurético tiazídico para control de la presión arterial y toma de forma rutinaria ibuprofeno 1800 mg/día para control de los síntomas derivados de su gonartrosis. Tras control rutinario se objetiva, de forma persistente, una presión arterial de 190 y TAD 80 mmHg.', '¿Cuál sería la modificación terapéutica más razonable para conseguir el control de las cifras tensionales?', '[{"position": 1, "text": "Añadiría un bloqueante del calcio."}, {"position": 2, "text": "Aumentaría la dosis de hidroclorotiazida a 25 mg/día."}, {"position": 3, "text": "Cambiaría el ibuprofeno por paracetamol para evitar la posible influencia del mismo sobre el efecto de los hipotensores."}, {"position": 4, "text": "Añadiría un bloqueante alfa por la elevada prevalencia de síndrome prostático en varones de esta edad."}]'::jsonb, 4, 3, 'definitiva', 'Antes de intensificar el tratamiento antihipertensivo se deben solucionar las causas potenciales. En este caso se trata de un paciente añoso con un tratamiento crónico con AINEs que produce hipertensión arterial secundaria a hipoperfusión renal. La opción más razonable sería retirar el ibuprofeno y sustituirlo por un analgésico de un grupo diferente a los AINEs (paracetamol, opiáceos), vigilando posteriormente la evolución de las cifras tensionales.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7f8f669ab698', '77943631167b833b31fd3b0099ae5c6ba7212259', NULL, NULL, NULL, false, false, 'Oftalmología', 'Paciente de 34 años que jugando a tenis recibe el impacto de la bola a nivel de la órbita izquierda. A la exploración presenta importante hematoma palpebral, hiposfagma, diplopia a la visión superior con limitación de la versión superior del globo ocular.', '¿Qué sospecharía?', '[{"position": 1, "text": "Fractura de la pared inferior del suelo de la órbita con atrapamiento del músculo recto inferior."}, {"position": 2, "text": "Fractura del arco cigomático."}, {"position": 3, "text": "Fractura de la pared superior de la órbita con atrapamiento del músculo recto superior."}, {"position": 4, "text": "Fractura dentoalveolar."}]'::jsonb, 4, 1, 'definitiva', 'En el enunciado describen diplopia a la vision superior con limitacion para la ersion superior del globo ocular. Al estar comprometida la funcion de forma mecanica del recto inferior izquierdo, no permitiria completar el movimiento de supraduccion generando diplopia vertical, esto mas el antecedente traumatico permite sospechar de una Fractura de piso orbitario con atrapamiento muscular del recto inferior. La Fractura de techo es mucho menos frecuente y el atrapamiento del recto superior provocaria limitacion para la infraduccion.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-6025e8aab025', '2e363948f0fc317f857568578bbd8f84cdef2cf9', NULL, NULL, NULL, false, false, 'Oftalmología', 'Un hombre con miopía magna, de 47 años, intervenido de cataratas hace 2 años acude a urgencias refiriendo una pérdida profunda e indolora de la visión en su ojo derecho.', '¿Cuál de los siguientes diagnósticos puede provocar esta sintomatología?', '[{"position": 1, "text": "Endoftalmitis postquirúrgica."}, {"position": 2, "text": "Desprendimiento de retina."}, {"position": 3, "text": "Degeneración macular asociada a la edad, forma húmeda."}, {"position": 4, "text": "Desprendimiento posterior de vítreo."}]'::jsonb, 4, 2, 'definitiva', 'Se refiere a un paciente post operado hace 2 años de catarata con perdida profunda e indolora en OD. La endoftalmitis postquirurgica se asocia mas a pacientes en post operatorio inmediato, ademas de ser muy dolorosa con disminucion de la agudeza visual rapidamente progresiva porlo que no es correcta. El Desprendimiento de retina es coherente con el caso clinico por tratarse ademas de un paciente miope quienes suelen tener especial predisposicion al desprendimiento. La DMRE suele ocurrir en pacientes mayores y la disminucion de la vision es progresiva. En el DVP puede o no haber leve disminucion de la agudeza visual y el paciente suele referir cierto disconfort o dolor al inicio del cuadro clinico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-77538ebd2ca3', 'aa31fbfbb7fe98ccc6067cd96824863422467ef0', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Un paciente diagnosticado previamente de EPOC acude a urgencia spor un cuadro de 3 días de duración con aumento de su disnea habitual hasata hacerse de reposo, tos con expectoración blanquecina y somnolencia acentuada. Tras recibir tratamiento con oxígeno a bajas concentraciones, broncodilatadores y coticoides se realiza una segunda gasometría arterial con fracción inspiratoria de oxígeno al 28% que muestra un pH de 7.32, pO2 61 mmHg, pCO2 58 mmHg, HCO3- 29 mmol/l', '¿Cuál sería la interpretación que haría usted de la gasometría arterial y qué tratamietno utilizaría?', '[{"position": 1, "text": "Aumentaría el flujo de oxígeno porque tiene acidosis respiratoria aguda e hipoxemia."}, {"position": 2, "text": "Iniciaría ventilación mecánica no invasiva porque tiene una insuficiencia respiratoria hipercápnica aguda con acidosis respiratoria moderada."}, {"position": 3, "text": "Añadiría bicarbonato sódico para corregir la acidosis metabólica aguda."}, {"position": 4, "text": "El paciente no tiene insuficiencia respiratoria por lo que continuaría con la misma pauta farmacológica."}, {"position": 5, "text": "Añadiría aminofilina intravenosa como estimulante respiratorio, ya que aprecio hipoxemia e hipercapnia."}]'::jsonb, 5, 4, 'definitiva', 'Esta es una pregunta con muy mala leche, apostaré a una respuesta, pero dependiendo de datos que no nos dan podrían valer tres respuestas como válidas. La trampa consiste en que nos dan la clínica de inicio SIN GASOMETRÍA y luego nos dan la gasometría de después SIN CLÍNICA, así no hay forma de saber cuál ha sido la evolución del paciente con nuestro tratamiento por lo que es imposible acertar qué hacer. Si el paciente inicialmente venía con una gasometría con pH de 7,05 y ahora tiene la que nos dan, lo estamos haciendo bien (aunque tampoco nos dicen el intervalo de tiempo entre una cosa y otra) y, en este caso, podría valer seguir con el mismo tratamiento. Si no ha evolucionado nada, la clínica es igual y la gasometría al principio era parecida habría que hacer algo (también dependiendo del estado basal del paciente, que tampoco nos cuentan). En caso de decidirnos por hacer algo, en la actualidad puede ser que nos decidiéramos por la ventilación más que por la teofilina aunque con "tan poca" alteración del pH (y más si pensamos que es un crónico que quizá tiene una gasometría basal parecida a la que nos presentan) puede parecer "exagerado". "Contra" la teofilina no tenemos nada (no nos cuentan ninguna contraindicación), pero en la actualidad es raro recurrir a ella. 1: Errónea, es un paciente “retenedor” y aumentando el flujo de O2 es altamente posible que aumentase también la hipercapnia y, por tanto, la acidosis. 2: Nos quedaremos con esta como correcta. 3: ¡No es una acidosis metabólica!, el bicarbonato no está disminuído, al contrario, está ligeramente aumentado intentando compensar la acidosis respiratoria. 4: No llega a insuficiencia respiratoria por definición (pO2 60), pero tiene hipercapnia y ligera acidosis. Si supiéramos la primera gasometría y esta estuviese mucho peor (es decir, estuviese evolucionando muy bien) seguir con la misma medicación sería una opción, ¡¡falta ese dato!!, en todo caso parece una respuesta trampa. 5: En la actualidad y -ya comentado- teniendo en cuenta que no hay contraindicación formal, no se suele utilizar.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-ecc3e1fc461f', '203058b37930dde1c654adac3cb84e5e5711d075', NULL, NULL, NULL, false, false, 'Oftalmología', 'Unos padres acuden a urgencias con su hijo de dos años porque refieren que se ha dado un golpe cerca del ojo derecho jugando. Efectivamente se observa un hematoma en el párpado derecho aparentemente sin importancia. En el fondo de ojo se observan hemorragias intrarretinianas no sólo en el ojo que refieren los padres sino también en el otro ojo. Llama la atención que el niño parece adormilado y con poco tono.', '¿Cuál de las siguientes afirmaciones debería considerar respecto a este cuadro clínico?', '[{"position": 1, "text": "Es una historia altamente sugestiva de maltrato infantil."}, {"position": 2, "text": "Es la evolución normal de un traumatismo intraocular no perforante."}, {"position": 3, "text": "El diagnóstico más probable es un edema de Berlin."}, {"position": 4, "text": "Es el cuadro característico de la angiopatía retiniana traumática de Purstcher."}]'::jsonb, 4, 1, 'definitiva', 'Pregunta en principio fácil, pero con un poco de trampa. Si al leerla tienes la intuición correcta y vas directamente a lo que piensas, posiblemente la aciertes. El problema es la opción 4, que nos puede confundir. Veamos: tenemos un golpe en la zona del ojo derecho, con un hematoma en el párpado. Hasta aquí todo normal. El problema es que aparecen hemorragias retinianas no sólo en ese ojo (que ya de por sí es raro, porque por un golpe externo del ojo en un niño raramente se produce sangrado en la retina), sino en el otro. Con lo cual, algo que no ha sido el golpe ha causado hemorragias en ambas retinas. Luego nos dicen que el niño parece adormilado y con poco tono. Aquí ya tenemos las dos claves; tenemos que sospechar lo que no se menciona en las respuestas, pero que es lo que tiene el niño: el síndrome del niño sacudido (shaken baby syndrome). Lo característico de este síndrome son las hemorragias retinianas bilaterales, edema cerebral y hematoma subdural. También puede haber fractura de huesos largos y otros problemas. El adormilamiento y la hipotonía nos permiten sospechar las complicaciones intracraneales. La causa del síndrome del niño sacudido es casi siempre el maltrato, así que la respuesta es la 1. Las opciones 2 y 3 son fáciles de descartar: nada nos indica traumatismo perforante, y no explica las hemorragias del otro ojo. Y el edema de berlin es un edema de la mácula y aparece como una lesión blanquecina, que no está descrita en el enunciado. La trampa es la opción 4. La retinopatía de Purstcher puede aparecer también en el contexto de del niño del niño sacudido, y por tanto ocurrir en el caso de maltrato infantil. Al ver estas dos preguntas en parte relacionadas, podemos dudar. Sin embargo, si leemos bien la respuesta 4, no nos habla de que si hay maltrato infantil se pueda producir un Purstcher. Nos afirma que el cuadro descrito antes (hemorragias intrarretinianas, sin otros hallazgos) es característico de la angiopatía de Purstcher. Y no es así. En el Purstcher hay hemorragias, pero también exudados algodonosos y edema. Si sólo hay hemorragias, no es un Purstcher. Aquí está lo lioso, pero realmente está bien redactado. Si tuviera un Purstcher también podría ser por maltrato infantil, pero no lo tiene.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f10392f9c7e6', '23bb0964346c5ddc2a37611c0572df3920253f02', NULL, NULL, NULL, false, false, 'Oftalmología', 'Mujer de 84 años que acude por pérdida de visión en el ojo izquierdo de 4 días de evolución acompañada de metamorfopsias. En la mácula se aprecian abundantes exudados duros, dos pequeñas hemorragias profundas y un desprendimiento de la retina neurosensorial localizado. En el ojo contralateral presenta abundantes drusas blandas.', 'Ante este cuadro, ¿Cuál de los siguientes diagnósticos le parece más probable?', '[{"position": 1, "text": "Desprendimiento posterior de vítreo agudo."}, {"position": 2, "text": "Degeneración macular asociada a la edad (DMAE) exudativa."}, {"position": 3, "text": "Obstrucción de arteria central de la retina."}, {"position": 4, "text": "Neuropatía óptica isquémica anterior no arterítica."}]'::jsonb, 4, 2, 'definitiva', 'Pregunta en principio fácil, incide en una enfermedad que se repite con frecuencia en los exámenes MIR. La descripción es la típica de la opción 2. Se trata de una DMAE exudativa (aunque como decíamos en la pregunta 215, con la clasificación nueva, hablaríamos de una DMAE avanzada en su variante neovascular). De cualquier manera, tenemos una paciente mayor con pérdida de visión y metamorfopsias en un ojo. En la exploración hay lesiones en la mácula. Ya con eso podemos descartar el desprendimiento de vítreo posterior agudo, que no produce pérdida visual, ni metamorfopsias, ni lesiones en la mácula. Y también la neuropatía óptica isquémica anterior no arterítica, porque ésta, si bien produce pérdida visual y es típica de personas mayores, no produce metamorfopsias. Y no hay lesiones en la mácula sino edema de papila. En la obstrucción de arteria central de la retina no es especialmente característico las metamorfopsias (sí la perdida visual y la edad avanzada), pero varían las lesiones en el fondo del ojo. En el caso de oclusión arterial, hay un edema intracelular que se ve como ausencia de hemorragias y un fondo blanquecino, pálido. Además de que afecta en global a toda la retina, y puede aparecer una mancha rojo cereza en la mácula. En este caso las lesiones son totalmente diferentes. Nos describen exudados duros, hemorragias profundas y desprendimiento de retina neurosensorial localizado. Todo ello en la mácula. Son los hallazgos característicos de la DMAE neovascular (o exudativa). Como pista, en el otro ojo hay abundantes drusas blandas. Las drusas los los hallazgos típicos la DMAE. Así que tiene DMAE en ambos ojos y en el ojo derecho recientemente se ha complicado con la aparición de la neovascularización.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-31f3843e7533', 'e69c8b4193fadf34721b225b7e89442a0db7d4c2', NULL, NULL, NULL, false, false, 'Oncología', 'Paciente de 57 años, diagnosticado de adenocarcinoma de colon estadio T3N1M0. Fue tratado con resección seguida de quimioterapia postoperatoria FOLFOX (fluorouracilo, leucovorin y oxaliplatino) durante 6 meses. En un control rutinario, dos años después, se detecta elevación de antígeno carcinoembrionario (CEA) a 30 ng/mL (previo menor de 2 ng/mL). No tiene síntomas, el examen físico es anodino, la radiografía de tórax es normal. En la TC se aprecia una masa de 3 cm en el lóbulo hepático derecho que capta en PET. No se observan otras alteraciones en TC ni en PET.', '¿Qué actitud le parece más correcta?', '[{"position": 1, "text": "Quimioterapia con FOLFIRI (fluorouracilo, leucovorin e irinotecan) más bevacizumab."}, {"position": 2, "text": "Monoquimioterapia con capecitabina."}, {"position": 3, "text": "Valoración por cirugía de resección de la lesión hepática."}, {"position": 4, "text": "Radioterapia hepática."}]'::jsonb, 4, 3, 'definitiva', 'Nos encontramos ante una situación de probable metástasis hepática de un adenocarcinoma de colon localizado tratado hace 2 años. Probable porque no tenemos confirmación histológica, aunque como suele suceder ¿qué otra cosa va a ser? Como se trata de una situación de oligometástasis y los tratamientos para adenocarcinoma de colon avanzado permiten una superviviencia prolongada y con buena calidad de vida en estos pacientes, si no existe nada que contraindique la cirugía, esa debe ser la primera opción (respuesta 3 correcta). Adjunto el algoritmo que propone la NCCN en situaciones de recurrencia (http://www.nccn.org/professionals/physician_gls/pdf/colon.pdf). En caso de ser una situación irresecable, se plantearía un tratamiento de quimioterapia con intención de convertir la lesión metastásica única en resecable. Dado que han pasado más de 12 meses desde el tratamiento con FOLFOX, se podría usar el mismo esquema, auqnue FOLFIRI+bevacizumab también sería útil. Capecitabina en monoterapia, en la situación actual del paciente tampoco sería una buena opción de inicio, ya que las respuestas son menores en comparación con las combinaciones FOLFOX o FOLFIRI más antiangiogénicos. La radioterapia hepática podría valorarse ya que existen técnicas de SBRT que consiguen muy buenos resultados pero en este caso lo mejor es que empecemos pidiendo valoración por los cirujanos y si descartaran la cirugía ya plantearíamos la RT.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-fc867dc22427', 'd3340264352d4aa23f6b0239652e0c580c86636a', NULL, NULL, NULL, false, false, 'Reumatología', 'Mujer de 70 años con antecedente de anorexia, pérdida de peso, molestias en la musculatura y articulaciones proximales más dolorimiento en la región temporo-mandibular que acude al servicio de urgencias por pérdida de visión unilaterai (movimiento de manos), de aparición brusca e indolora (defecto pupilar aferente).', '¿Qué prueba solicitaría en primer lugar con fines diagnósticos?', '[{"position": 1, "text": "Punción lumbar."}, {"position": 2, "text": "Proteína C Reactiva."}, {"position": 3, "text": "Angio Resonancia Magnética."}, {"position": 4, "text": "Ecografía carotídea."}]'::jsonb, 4, 2, 'definitiva', 'Es posiblemente una arteritis de la temporal, basta con el cuadro clínico y una analítica con aumento de reactantes para confirmar la sospecha. Después habría que hacer una valoración ocular para descartar NOIA, instaurar tratamiento urgente (si hay NOIA 3 bolos de metilprednisolona 1 gr, si no la hay prednisona mg/kg) y valorar biopsiar.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8338744e8f51', '880ec6bafc981e45fa8a35aae21c3f1865b7d272', NULL, NULL, NULL, false, false, 'Reumatología', 'Chico de 20 años, que consulta por dolor lumbosacro de ritmo inflamatorio de 4 meses de evolución. También talalgia bilateral y rigidez matutina de 1 hora. En los últimos 2 meses aparición de cuadros diarreicos con pérdida de 4 kg de peso.', '¿Cuál es la aproximación diagnóstica más correcta?', '[{"position": 1, "text": "Dada la edad del paciente, lo más probable es que padezca lumbalgia inespecífica y una tendinitis en los pies. Si persisten las diarreas realizaría estudio digestivo."}, {"position": 2, "text": "Realizaría estudio digestivo para descartar patología tumoral. El dolor lumbar puede ser debido a patología visceral."}, {"position": 3, "text": "El cuadro clínico es muy sugestivo de espondiloartritis. Habría que descartar enfermedad inflamatoria intestinal."}, {"position": 4, "text": "Solicitaría RNM lumbar para descartar hernia discal y si persiste diarrea, estudio digestivo."}]'::jsonb, 4, 3, 'definitiva', 'El cuadro clínico es el típico de una espondiloartritis, y junto con la clínica digestiva seguramente sea una asociada a enfermedad inflamatoria intestinal.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-405d4a8cf396', '3194c8a454f0f0961e70461dfa3d6f947825a71e', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Un paciente diagnosticado de asma bronquial que está siendo tratado con esteroides inhalados a dosis bajas (200 microgramos de budesonida cada 12 horas) y medicación de rescata (salbutamol a demanda) acude a control clínico periódico. El paciente refiere que en los últimos 3 meses no ha tenido agudizaciones y que utiliza el salbutamol una vez al día. Unicamente tiene disnea al subir cuestas y algunas noches dureme de forma irregular por la tos.', '¿Cuál de las sigueinte opciones terapéuticas se consiedera de elección?', '[{"position": 1, "text": "Aumentar la dosis de corticoides inhalados a 800 microgramos/día."}, {"position": 2, "text": "Añadir tiotropio."}, {"position": 3, "text": "Mantener la misma pauta farmacológica."}, {"position": 4, "text": "Cambiar a una terapia ocmbinada con corticoides inhalados a dosis bajas y beta2 adrenérgicos de acción prolongada."}, {"position": 5, "text": "Añadir leucotrienos."}]'::jsonb, 5, 4, 'definitiva', 'Algoritmo de tratamiento del asma. Descartamos seguir con el mismo tratamiento ya que el paciente está sintomático.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-acc3386628c6', '180cf967ddbc4e218e3e2565879650bf5e6cc313', NULL, NULL, NULL, false, false, 'Reumatología', 'Acude a una revisión programada encontrándose asintomático un hombre de 50 años diagnosticado de poliangeitis con granulomatosis 10 años antes y sin tratamiento desde hace 5. La radiografía de tórax, análisis de sangre y sedimento de orina son normales salvo unos anticuerpos anticitoplasma del neutrófilo (ANCA) positivos a titulo 1/320, con especificidad antiproteinasa 3, que previamente se habían negativizado.', '¿Cuál es la actitud terapéutica más aconsejable?', '[{"position": 1, "text": "Iniciar tratamiento con corticoides."}, {"position": 2, "text": "Iniciar tratamiento con ciclofosfamida."}, {"position": 3, "text": "Iniciar tratamiento con micofenolato de mofetilo."}, {"position": 4, "text": "Vigilancia expectante."}]'::jsonb, 4, 4, 'definitiva', 'En las vasculitis ANCA, sea cual sea, estos anticuerpos han demostrado relación con la actividad de la enfermedad pero en ningún momento obligatoriedad de cambios en el tratamiento por sus niveles. En este caso, estando el paciente asintomático y con pruebas objetivas de falta de actividad, habría que hacer un seguimiento estrecho sin reiniciar ni modificar tratamiento.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-db2aca74eab1', '84eace554b7ab8c28914539f7e4ae90517d63587', NULL, NULL, NULL, false, false, 'Urología', 'Un chico de 22 años de edad con hiposmia presenta falta de desarrollo de caracteres sexuales secundarios e infertilidad. Volumen testicular de 4 mL bilateral. Analíticamente, EST-I 1,2 U/L (vn 5-15); LH 0,6 U/L (vn 3-15); testosterona 100 ng/dL (vn 300-1200), prolactina normal.', 'Señale el tratamiento que le propondrá para conseguir fertilidad:', '[{"position": 1, "text": "Bomba de infusión de GnRH."}, {"position": 2, "text": "Administración intramuscular mensual de triptorelina."}, {"position": 3, "text": "Administración intramuscular de FSH y LH una vez por semana."}, {"position": 4, "text": "Tratamiento con bromocriptina."}]'::jsonb, 4, 1, 'definitiva', 'Se trata de un síndrome de Kallman (hipogonadismo hipogonadotropo + alteración olfactiva). La triptorelina es un agonista de la GnRH, que mediante acción continua reduce la FSH y LH, y se usa en cánceres dependientes de hormonas sexuales, así como pubertad precoz. La bromocriptina es un agonista dopaminérgico que se usa en hiperPRL (este tiene la PRL normal), tumores hipofisarios… Nos quedamos entre la 1 y la 3. Para inducir la maduración testicular, se pude usar GnRH pulsátil con bomba, hCG o FSH+hCG. No se usa la LH como tratamiento, se estimularía a través de la GnRH intermitente.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-eb79c11a135b', 'cb4a78382b2822c7b8d8821d6f389e9cf355a5c2', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Una paciente de 70 años ingresa en UCl tras sufrir IAM anterior tratado mediante angioplastia coronaria y colocación de stent en la arteria descendente anterior. 4 días después presenta bruscamente hipotensión que obliga a aporte vigoroso de volumen, inicio de drogas vasoactivas, intubación orotraqueal y conexión a la ventilación mecánica. A la exploración física destaca un soplo no presente previamente. Ante la sospecha de complicación mecánica del infarto, se realiza ecocardiografia transtorácica que muestra derrame pericárdico.', 'Señale la Respuesta CORRECTA:', '[{"position": 1, "text": "La mortalidad con tratamiento médico es del 20%."}, {"position": 2, "text": "En caso de rotura de pared libre hay saltooximétrico en el ventrículo derecho en el cateterismo de Swan-Ganz."}, {"position": 3, "text": "En caso de rotura de pared libre no hay frémito palpable."}, {"position": 4, "text": "Las complicaciones mecánicas suelen aparecer en el primer día postinfarto."}]'::jsonb, 4, 3, 'definitiva', 'La mortalidad no es tan baja, el salto oximétrico se da en el caso de rotura del septum, al igual que el frémito (de ahí que la respuesta correcta sea la 3) y las complicaciones se pueden presentar hasta en la primera semana.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-279361974170', '931bf78f107f82013c57cb1c25feef2c7ef803ad', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Paciente de 54 años que ingresa por fiebre termometrada de 38°C en los cinco días previos y disnea de reposo(NYHA lV) que apareció 6 horas antes de acudir al hospital. En urgencias la exploración es compatible con insuficiencia cardiaca y el ECG muestra bloqueo auriculo-ventricular completo con una frecuencia ventricular de escape de 45 lpm. Los signos de insuficiencia cardiaca son refractarios al tratamiento médico y la ecocardiografia transesofágica realizada muestra una válvula aórtica con orificio regurgitante efectivo de 0.5 cm2. Los cultivos seriados son positivos para Streptococcus gallolyticus.', 'Indique la actitud más acertada:', '[{"position": 1, "text": "Cirugía cardiaca de reemplazo valvular aórtico por prótesis mecánica con terapia antibiótica según antibiograma."}, {"position": 2, "text": "Terapia antibiótica según antibiograma e implantación de balón de contrapulsación intra-aórtico y marcapasos transitorio hasta 3 semanas, tras las cuales se implantará marcapasos definitivo."}, {"position": 3, "text": "Implantación de marcapasos transitorio, terapia antibiótica según antibiograma e implantación percutánea de prótesis valvular aórtica."}, {"position": 4, "text": "Implantación urgente de marcapasos definitivo con terapia antibiótica según antibiograma durante 6 semanas."}]'::jsonb, 4, 1, 'definitiva', 'La respuesta correcta es la 1, ya que entre las indicaciones de cirugía cardíaca se encuentran la aparición de insuficiencia cardíaca o de nuevos trastornos de conducción, y en este caso presenta ambas cosas.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-064e4e74545e', 'd85d863ae2c0aba51bd3271eb00f926e652d8e39', NULL, NULL, NULL, false, false, 'Endocrinología', 'Hombre de 49 años que consulta por poliuria y polidipsia intensas y pérdida involuntaria de 10 kg de peso y es diagnosticado de diabetes mellitus por una glucemia plasmática de 322 mg/dL y una hemoglobina glicosilada de 9,8%. Su médico le da recomendaciones dietéticas, la conveniencia de realizar ejercicio físico, e inicia tratamiento con metformina 850 mg/12 horas y glimepirida 6 mg/dia. En las semanas siguientes los controles glucémicos se van reduciendo progresivamente. A los 4 meses la glucemia es de 94 mg/dL y la HbA1c de 5,9%. El paciente se queja de episodios frecuentes de mareo, dolor epigástrico, visión borrosa, sudoración y temblor, que mejoran comiendo algo y que ocurren sobre todo al final de la mañana y al final de la tarde.', '¿Qué modificación propondria en su tratamiento?', '[{"position": 1, "text": "Revisar la distribución de hidratos de carbono de su dieta."}, {"position": 2, "text": "Suspender la metformina."}, {"position": 3, "text": "Suspender la sulfonilurea."}, {"position": 4, "text": "Sustituir la metformina por un inhibidor de la DPP4."}]'::jsonb, 4, 3, 'definitiva', 'Suspender la sulfonilurea por Riesgo de hipoglucemia.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5e935057d47f', '005113be0f3446823e42e6fecbdb141b87bf1eb4', NULL, NULL, NULL, false, false, 'Endocrinología', 'Un chico de 22 años de edad con hiposmia presenta falta de desarrollo de caracteres sexuales secundarios e infertilidad. Volumen testicular de 4 mL bilateral. Analíticamente, FSH 1,2 U/L (vn 5-15); LH 0,6 U/L (vn 3-15); testosterona 100 ng/diu (vn 300-1200), prolactina normal.', 'Señale el tratamiento que le propondrá para conseguir fertilidad:', '[{"position": 1, "text": "Bomba de infusión de Gn_RH."}, {"position": 2, "text": "Administración intramuscular mensual de triptorelina."}, {"position": 3, "text": "Administración intramuscular de FSH y LH una vez por semana."}, {"position": 4, "text": "Tratamiento con bromocriptina."}]'::jsonb, 4, 1, 'definitiva', 'El síndrome de Kallman o síndrome de Morsier es una insuficiencia congénita que se asocia a un hipogonadismo hipogonadotrópico por un déficit en la producción de hormona GnRH. Para restaurar la fertilidad se realizan inyecciones repetidas de GnRH.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-67578c63b2da', 'ff72500dc27fea1cdd7935a8815fb9182a120fa0', NULL, NULL, NULL, false, false, 'Endocrinología', NULL, 'En un paciente hospitalizado que no es capaz de alimentarse por vía oral durante más de 6 días, ¿en cuál de las situaciones clínicas siguientes hemos de usar necesariamente nutrición parenteral?', '[{"position": 1, "text": "Ictus cardioembólico con disfagia neurológica completa."}, {"position": 2, "text": "Caquexia por empiema crónico en paciente inmunodeprimido."}, {"position": 3, "text": "lleo paralítico prolongado."}, {"position": 4, "text": "Enfermedad de Alzheimer avanzada con grave riesgo de broncoaspiración."}]'::jsonb, 4, 3, 'definitiva', 'El íleo paralítico es un fallo en la propulsión intestinal que aparece de forma aguda en ausencia de obstrucción mecánica; es secundario a diversas causas y afecta a la contractilidad intestinal. Por lo que es necesaria la vía parenteral.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-49d0f4ea0050', '849e3ca9e361b385e0f6d7b9958ac547088634cd', NULL, NULL, NULL, false, false, 'Farmacología', 'Mujer diagnosticada de diabetes mellitus tipo 1 desde hace 24 años. Acude a la consulta con clínica de 3 meses de evolución de hormigueos en ambos pies, con distribución en calcetín, con dolor parestésico y sensación de pies calientes de predominio nocturno, que interfiere notablemente con el sueño.', '¿Cuál de los siguientes fármacos utilizaría en primera línea para el tratamiento de su patología?', '[{"position": 1, "text": "Ibuprofeno."}, {"position": 2, "text": "Oxicodona."}, {"position": 3, "text": "Duloxetina."}, {"position": 4, "text": "Paracetamol."}]'::jsonb, 4, 3, 'definitiva', 'Duloxetina; el cuadro clínico descrito es de neuropatía diabética. De los fármacos propuestos el de primera elección sería un antidepresivo dual como la duloxetina.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-6123a7a7e863', '189ccebb7d281b355c9180902b1050540aa23efe', NULL, NULL, NULL, false, false, 'Farmacología', 'Un hombre de 88 años viene a consulta porque se ha caído 3 veces en los últimos 6 meses. Ninguna de las caídas se acompañaba de mareo o síncope. Una caída ocurrió mientras caminaba por el jardín. Sus antecedentes médicos incluyen hipertensión arterial sin cambios posturales en la presión arterial, gota, artrosis y depresión. Toma 5 medicinas regularmente.', '¿Cuál de las siguientes es la que más probablemente contribuya a las caídas en este paciente?', '[{"position": 1, "text": "Alopurinol."}, {"position": 2, "text": "Hidroclorotiazida."}, {"position": 3, "text": "Lisinopril."}, {"position": 4, "text": "Paroxetina."}]'::jsonb, 4, 4, 'definitiva', 'Paroxetina; pregunta complicada ya que tanto hidroclorotiazida como lisinopril pueden también producir caídas en ancianos, pero generalmente se acompañarían de mareo.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4fcfc086e807', '2ed4d754f9270303c31376ceb4912a95d593b645', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Un hombre de 64 años, diagnosticado de miastenia gravis hace 1 año, en tratamiento con esteroides a dosis bajas (3 mg/día de deflazacort) y anticolinesterásicos, asintomático desde hace 6 meses, consulta por leve dificultad para tragar y diplopia vespertina desde hace unos días. Ingresa en el hospital por sospecha de crisis miasténica y se inicia tratamiento de la misma. Al día siguiente la paciente avisa a las 03 horas de la madrugada porque el paciente hace un ruido extraño al inspirar, como un ronquido suave, el paciente está profundamente dormido y muy sudoroso, pero no impresiona de estar fatigado.', '¿Qué actitud es más correcta?', '[{"position": 1, "text": "Tranquilizar a la enfermera y a la familia, pues el paciente es roncador habitual y está tranquilamente dormido. Se debe colocar en decúbito lateral."}, {"position": 2, "text": "Avisar a cuidados intensivos por sospecha de insuficiencia respiratoria aguda, para valorar posible intubación orotraqueal y ventilación asistida."}, {"position": 3, "text": "Hacer estudio polisomnográfico para descartar apnea del sueño."}, {"position": 4, "text": "Disminuir la dosis de esteroides; si tiene una miopatía esteroidea mejorará."}, {"position": 5, "text": "Pedir una TC torácica para descartar que timoma comprensivo sobre la tráquea asociado a la miastenia."}]'::jsonb, 5, 2, 'definitiva', 'Se trata de un paciente con miastenia descompensada con síntomas bulbares (disfagia) y por lo tanto riesgo de afectación de musculatura respiratoria. La clínica respiratoria se corresponde a un agotamiento de los músculos, primero inspiratorios y luego accesorios (el paciente no parece fatigado ni taquipneico porque los músculos no dan más), progresando a un coma carbónico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c01c8cb585fc', 'd1e3068533c4b936a35feb4dabc2e94cf8c7aee6', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Una mujer de 24 años, primigesta, sufre un aborto espontáneo a las 7 semanas de gestación. El estudio anatomopatológico de los restos abortivos indica enfermedad molar.', 'Le debemos informar que:', '[{"position": 1, "text": "El riesgo de una nueva gestación molar en un futuro embarazo es del 50%."}, {"position": 2, "text": "No debe quedar embarazada hasta realizar controles periódicos y haber pasado un años con niveles de BHCG negativos."}, {"position": 3, "text": "No es necesario realizar controles posteriores si la evacuación del tejido trofoblástico fue completa."}, {"position": 4, "text": "Es necesario que se realice controles periódicos ya que en el 40% de los casos desarrollará una neoplasia trofoblástica gestacional."}]'::jsonb, 4, 2, 'definitiva', 'La enfermedad trofoblástica gestacional debe mantener un seguimiento posterior (independientemente de si la evacuación ha sido completa o no) y se debe aconsejar a la paciente no quedar gestante de nuevo hasta conseguir al menos 6 meses con títulos de BHCG negativos. El riesgo de recurrencia en otra gestación es bajo (1/55) y el 90% de los casos evoluciona de forma satisfactorias sin desarrollar una neoplasia.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-341eeb5b4840', '25623ed7fd43c2ee0e7fda680215caf779504e50', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Mujer de 69 años que acude a su consulta refiriendo sangrado genital de varios meses de evolución. Niega tratamiento hormonal sustitutivo y anticoagulación. Aporta citología cervicovaginal normal. Exploración física general y genital sin hallazgos de interés. IMC de 38kg/m2.', 'Indique la actitud más correcta:', '[{"position": 1, "text": "Prescribir progesterona cíclica."}, {"position": 2, "text": "Biopsia endometrial."}, {"position": 3, "text": "Biopsias de cérvix al azar."}, {"position": 4, "text": "Valoración hormonal con FSH, LH y estradiol."}]'::jsonb, 4, 2, 'definitiva', 'Nos están presentando un caso de metrorragia postmenopáusica. Ante un caso como este debemos descartar una neoplasia endometrial, por lo que estaría indicado realizar una biopsia endometrial, bien mediante cánula de Cornier si es posible, o bien mediante histeroscopia. La realización de biopsia cervical no es de interés en este caso dado que la citología es normal y la valoración hormonal tampoco va a ser útil en el diagnóstico de una neoplasia endometrial. Por último, prescribir progesterona cíclica no está indicado al ser una mujer postmenopáusica.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-61c28dd9fdc1', 'dc1cb851088165798c05bf7bdcc0a4dd2245f589', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Mujer de 45 años, madre de 3 hijos, acude a consulta de diagnóstico precoz. La citología cervicovaginal es compatible con lesión escamosa intraepitelial de alto grado.', '¿Cuál de las siguientes opciones elegiría?', '[{"position": 1, "text": "Repetir la citología en 1 mes."}, {"position": 2, "text": "Colposcopia con eventual biopsia."}, {"position": 3, "text": "Histerectomía con salpinguectomía bilateral y conservación de ovarios."}, {"position": 4, "text": "Legrado uterino fraccionado."}]'::jsonb, 4, 2, 'definitiva', 'Tienen indicación de colposcopia todas las pacientes con citología alterada (lesión intraepitelial o sospecha de cáncer invasor o infección VPH), como segundo nivel de screening. En caso de observarse lesiones en esta prueba, se procederá a realizar una biopsia de la lesión. No tiene sentido repetir la citología (ya que esta es una prueba de screening, no diagnóstica), realizar una histerectomía por una lesión intraepitelial que no se ha confirmado por biopsia tampoco está indicado y la realización de legrado de la cavidad endometrial no aporta información ya que la lesión es del cérvix.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-895f07bc19a0', '0213bf6d22b5017ad13a1252c0891777fa20368b', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Mujer de 27 años remitida a consulta de ginecología para su valoración refiriendo dispareunia desde hace unos 8 meses, junto con disquecia y rectorragia ocasional coincidiendo con la menstruación desde hace 3-4 meses. También refiere dismenorrea desde hace años que controla bien con ibuprofeno. Lleva intentando quedarse embarazada unos 16 meses sin haberlo conseguido aún. En la exploración ginecológica tan sólo se aprecia dolor al presionar fondo de saco vaginal posterior.', '¿Qué prueba considera Ud que le permitiría llegar al diagnóstico de certeza de su patología?', '[{"position": 1, "text": "Ecografía transvaginal."}, {"position": 2, "text": "Laparoscopia diagnóstica."}, {"position": 3, "text": "Resonancia magnética."}, {"position": 4, "text": "Colonoscopia."}]'::jsonb, 4, 2, 'definitiva', 'El caso clínico que presentan es una mujer en edad fértil (27 años) que presenta dispareunia + dismenorrea + esterilidad, lo cual debe hacernos pensar en una endometriosis. La historia clínica y la ecografía dan un diagnóstico de sospecha, pero el diagnóstico de certeza lo da la observación directa (con biopsia asociada o no) de implantes de tejido endometrial ectópico, bien por laparotomía o por laparoscopia.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-2fff08e00453', '8cb9d7fbe89ae6475a9d2c4efb9eb294f0ba8364', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Una embarazada de 10 semanas de gestación, acude urgencias hospitalarias por presentar una presión arterial de 160/105 mmHg. Buen estado general, sólo leve cefalea, motivo por el que se tomó la presión arterial. Tras 4 horas de reposo presenta cifras de 150/95mmHg. Se le realiza un hemograma que es normal y una proteinuria que es negativa.', '¿Qué tipo de hipertensión presenta?', '[{"position": 1, "text": "Preeclampsia moderada."}, {"position": 2, "text": "Hipertensión inducida por el embarazo."}, {"position": 3, "text": "Hipertensión crónica."}, {"position": 4, "text": "Eclampsia."}]'::jsonb, 4, 3, 'definitiva', 'La respuesta correcta es la 3. La SEGO en su protocolo de 2006 «Trastornos hipertensivos del embarazo» refiere que se trata de una hipertensión crónica, aunque diagnosticada en el embarazo. Esto es así porque ha sido diagnosticada a las 10 semanas de gestación. Por encima de las 20 semanas de gestación, ya hablaríamos de preeclampsia (si HTA + proteinuria ó indice de pulsatilidad de arterias uterinas por encima del percentil 95), hipertensión inducida por el embarazo (sólo HTA) ó eclampsia (es una forma de preeclampsia grave).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-388f7d614ea9', '284763fb0ba5b85281b6d06f1f962debf3275769', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Una mujer de 24 años de edad consulta al haber apreciado adenopatías inguinales. En el interrogatorio no se recoge la presencia de ninguna molestia local ni datos sugerentes de infección de transmisión sexual. En la exploración se aprecian dos adenopatías, una en cada ingle, de 1 cm de diámetro mayor, blandas, móviles, no dolorosas. No se aprecia ninguna lesión cutánea en miembros inferiores, ano ó periné.', '¿Qué prueba considera imprescindible?', '[{"position": 1, "text": "Una serología de lúes puesto que lo más probable es que se trate de una infección por Treponema pallidum."}, {"position": 2, "text": "Una exploración ginecológica a fin de descartar un cáncer de ovario."}, {"position": 3, "text": "Por las características clínicas parece tratarse de unos ganglios normales y no deben hacerse exploraciones complementarias."}, {"position": 4, "text": "Debe realizarse una prueba de Paul-Bunell, a fin de descartar una mononucleosis infecciosa."}]'::jsonb, 4, 3, 'definitiva', 'La presencia de ganglios inguinales de hasta 1-1,5cm puede ser normal ante la ausencia de síntomas. En este caso, son ganglios muy inespecíficos, sin signos de malignidad (móviles, blandos, no dolorosos) que no nos hacen sospechar infiltración neoplásica y la falta de otra clínica también nos lleva a descartar la presencia de ETS.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8252c2b712b4', '45107cd1e6f003a23aa49eccee11bfbb238958f7', NULL, NULL, NULL, false, false, 'Hematología', NULL, 'La determinación en una mujer de 70 años de hematocrito 32%, Hb 9,6 g/dL, VCM 85 fL (70-99), Fe 25 ug/dL (37-145) y ferritina 350 ng/mL (15-150), es más sugestivo de:', '[{"position": 1, "text": "Perdida de sangre reciente por aparato digestivo."}, {"position": 2, "text": "Malabsorcion intestinal."}, {"position": 3, "text": "Polimialgia reumática."}, {"position": 4, "text": "Talasemia minor."}]'::jsonb, 4, 3, 'definitiva', 'Polimialgia reumática. Clasico ejemplo supongo, y se ve en clínica a mansalva. Mujer mayor con anemia normocitica y patrón ferrocinetico claro de trastorno crónico (hiposideremia pero hiperferritinemia). La única que cuadra, y de lujo, es la 3; solo les faltaba darnos una VSG alta. La 1: si es pérdida reciente, el VCM podría mantenerse normal, pero la ferritina debería afectarse, y desde luego no estar elevada. La 2: lo mismo. Si es por malabsorción de Fe, la ferritina debería ser baja. Y si fuera por malabsorción de B12, el VCM nos lo pondrían claramente mas alto. La 4: 70 tacos y VCM normal. Esta sobra.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-a8fda08ed21e', 'b284d8034c279ac704372bff3a1d3bc547a44630', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Un paciente de 56 años sin antecedentes personales y familiares de interés es estudiado por presentar desde hace seis meses dificultad para andar con la pierna derecha. No refiere otros síntomas. La exploración muestra una debilidad 4/5 para la flexión dorsal y eversión del pie y 4/5 para flexión e inversión del pie, estando los reflejos musculares aumentados y con Babinski presente, siendo el resto normal.', 'El diagnóstico sindrómico sería:', '[{"position": 1, "text": "Mononeuropatía del N. peroneo común derecho."}, {"position": 2, "text": "Afectación focal de primera motoneurona y probable de segunda."}, {"position": 3, "text": "Afectación hemimedular derecho (Brown-Sequard)."}, {"position": 4, "text": "Mononeuropatía múltiple con afectación de N. peroneo común y tibial posterior derecho."}, {"position": 5, "text": "Plexopatía lumbar derecha."}]'::jsonb, 5, 2, 'definitiva', 'Respuesta 1 incorrecta: No explica el piramidalismo. Respuesta 2 correcta: Una respuesta inespecífica, pero probablemente la respuesta correcta. Respuesta 3 incorrecta: Nos faltarían datos para pensar en un síndrome hemimedular de Brown Sequard. Explicaría el piramidalismo, pero faltarían datos sugestivos de este cuadro como una hipoestesia contralateral. Respuesta 4 incorrecta: Podría explicar la dificultad para la flexión dorsal y plantar del pie, pero no el piramidalismo. Respuesta 5 incorrecta: De una forma similar a la anterior podría explicar parte de la clínica, pero no el piramidalismo.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-62168830c612', 'fa8bd4c6fca372611b8636c4e9e75c3a81d6c06f', NULL, NULL, NULL, false, false, 'Hematología', 'Mujer de 46 años con antecedentes de valvulopatía reumática, que precisa sustitución valvular mitral por una prótesis mecánica. La evolución postoperatoria inicial es favorable. Sin embargo, tras comenzar tratamiento con acenocumarol desarrolla un cuadro de necrosis cutánea afectando región abdominal y extremidades.', '¿Cuál de las siguientes alteraciones justificaría este cuadro?', '[{"position": 1, "text": "Deficiencia de antitrombina."}, {"position": 2, "text": "Factor V Leiden."}, {"position": 3, "text": "Hiperhomocisteinemia."}, {"position": 4, "text": "Deficiencia de proteina C."}]'::jsonb, 4, 4, 'definitiva', 'La necrosis cutánea inducida por Warfarina es un efecto adverso grave y poco común en la terapia con anticoagulantes orales, solo se da en un 0,01 a 0,1% de pacientes y está especialmente relacionado con la deficiencia de proteína C y S de la coagulación.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-ecc3cc5e931d', '1b913a17acaa38c652150a12a83a046fd0458f7c', NULL, NULL, NULL, false, false, 'Hematología', 'Hombre de 51 años que es ingresado desde Urgencias por anemia macrocítica (Hb 6,3 g/dL, VCm 120 fL). En los estudios realizados se descarta un origen carencial. Los reticulocitos son de 24000/microL. El estudio de médula ósea es compatible con un síndrome mielodisplásico (SMD). La citogenética muestra una delección en 5q', '¿ Cuál es la afirmación correcta en relación a este paciente?', '[{"position": 1, "text": "Esta delección (5q-) es una alteración de buen pronóstico y tiene un tratamiento específico (lenalidomida)."}, {"position": 2, "text": "Lo recomendable en este paciente sería realizar tipajes HLA para organizar un trasplante alogénico."}, {"position": 3, "text": "Se trata de un paciente con un Índice Internacional de pronóstico (IPSS) alto."}, {"position": 4, "text": "El tratamiento en este caso serían las transfusión únicamente."}]'::jsonb, 4, 1, 'definitiva', 'Estamos ante un paciente joven y sin comorbilidades por lo que es candidato a recibir tratamiento con intención curativa por lo que la opción 4 se descarta. La opción 3 tampoco es la correcta ya que no podemos saber el IPSS que tiene el paciente ya que nos falta saber el número de blastos y el número de leucocitos y plaquetas para calcular el riesgo. La opción 2 también es incorrecta ya que la indicación de un trasplante de médula ósea en SMD es aquellos pacientes con IPSS alto o intermedio-2, y en este caso desconocemos el riesgo, lo único que conocemos del riesgo es la citogenética que es de buen pronóstico que nos daría 0 puntos. Por lo tanto la correcta es la 1 ya que es cierto que tiene una citogénetica favorable (5q-) y tiene un tratamiento específico la lenalidomida, también usada en otras patologías como el mieloma multiple.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5d69233490f6', '9e49b3d1df8e3a9829da9a10df3956ce9859aef3', NULL, NULL, NULL, false, false, 'Hematología', 'Paciente de 35 años que, debido a hematemesis por ulcus, recibe una transfusión de 2 concentrados de hematíes. A los 5-10 minutos de iniciarse la transfusión comienza con fiebre, escalofríos, hipotensión y dolor en región lumbar.', '¿Cuál sería el diagnóstico más probable?', '[{"position": 1, "text": "Contaminación bacteriana de la sangre."}, {"position": 2, "text": "Reacción febril secundaria a la transfusión."}, {"position": 3, "text": "Reacción febril por el plasma que contamina los hematíes."}, {"position": 4, "text": "Reacción transfusional hemolítica."}]'::jsonb, 4, 4, 'definitiva', 'Las reacciones transfusionales hemolíticas agudas pueden ocurrir en cuestión de minutos. Clínicamente se caracterizan por escalofríos, fiebre, urticaria, taquicardia, náuseas y vómitos, dolor lumbar, hemorragia por coagulación intravascular diseminada (CID)…. Nos cuentan de un paciente que en pocos minutos tras iniciar una transfusión presenta un cuadro agudo y muy grave (con shock). Esa situación tan aguda y grave solo cuadra con la opción 4.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-3d0dddf32305', 'ac256ffefe9618a68de2cf55d77c93a9c3f17536', NULL, NULL, NULL, false, false, 'Hematología', 'Mujer de 78 años con antecedentes de diabetes tipo 2 en tratamiento con antidiabéticos orales, HTA en tratamiento con beta-bloqueantes e inhibidores de la ECA, e insuficiencia cardiaca congestiva grado 1 de la NYHA con FEVI del 48%, y actualmente asintomática. Estado funcional: ECOG 0. Historia de 2 años de evolución de pequeños bultos en el cuello. Biopsia de adenopatía cervical: linfoma folicular grado 2. Estudio de extensión: Hb 12 gr/dL, Leucocitos 6.900/microL (Neutrófilos 60%, Linfocitos 27%, Monocitos 6%, Eosinófilos 4%, Basófilos 4%), Plaquetas 220.000/microL. MO: infiltrado por Linfoma folicular. Creatinina 1,5 mg/dL, LDH 235 U/L, Beta2 microglobulina 2,1 microg/mL. TAC: adenopatías menores de 3 cm en territorios cervical, axilar, retroperitoneo, ilíacos e inguinales; hígado y bazo normales.', '¿Cuál de los siguientes tratamientos es el más apropiado?:', '[{"position": 1, "text": "Rituximab-CHOP (Ciclofosfamida, Adriamicina, Vincristina, Prednisona)."}, {"position": 2, "text": "Rituximab-CVP (Ciclofosfamida, Vincristina, Prednisona)."}, {"position": 3, "text": "No tratar y vigilar (esperar y ver)."}, {"position": 4, "text": "Rituxirnab-Bendamustina."}]'::jsonb, 4, 3, 'definitiva', 'Puede haber debate sobre si comenzar Rituximab con algún otro medicamento citostático o en monoterapia, pero dada la ausencia de beneficio en la supervivencia con el inicio precoz del tratamiento, en las guías tipo NCCN recomiendan esperar y ver, salvo que se reúnan criterios GELF para iniciar tratamiento: Criterios GELF (Grupo de Estudio de Linfomas Foliculares): – Compromiso de ≥3 áreas ganglionares, cada una con un diámetro ≥ 3 cm. – Cualquier masa ganglionar o extraganglionar con un diámetro ≥ 7 cm. – Síntomas B. – Esplenomegalia. – Derrame pleural o ascitis. – Citopenias (leucocitos < 1.0 x 109 / L y/o plaquetas < 100 x 109 /L). – Leucemia (> 5.0 x 109 /L de células malignas).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-15df1b21e4ed', '60a1f5450ada5593cced812f75c573f803e75751', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'Un hombre de 32 años natural de Camerún consulta por fiebre tos y dolor en hemitórax izquierdo de 1 mes de evolución. Tomó durante 1semana amoxicilina-clavulánico sin mejoría de los síntomas. Se le realiza un análisis donde destaca una cifra de leucocitos de 8000/microL y una hemoglobina de 12,8 g/dL. En la radiografía de tórax se observa un derrame pleural izquierdo loculado que ocupa un tercio del hemitórax. Una toracentesis muestra un líquido amarillento con las siguientes características: hematíes 2000/µL, leucocitos 2500/µL con 90% de linfocitos, proteínas 4,9 g/dL, lactato deshidrogenasa 550 VIL, glucosa 67 mg/dL y ausencia de células malignas en el estudio citológico.', '¿Cuál de las siguientes pruebas sería más útil para diagnosticar la causa del derrame pleural?', '[{"position": 1, "text": "Una tomografía computarizada (TC) torácica."}, {"position": 2, "text": "Medición del pH del líquido pleural."}, {"position": 3, "text": "Medición de la adenosína desaminasa del líquido pleural."}, {"position": 4, "text": "Prueba de la tuberculina."}]'::jsonb, 4, 3, 'definitiva', 'La sospecha es muy alta para derrame pleural tuberculoso, en paciente joven de una zona con alta tasa de TBC, un exudado linfocitario que apunta aTBC, linfoma o tumoral. Tumoral poco probable por edad, citología negativa. Linfoma podría ser pero no hay evidencia de patología ganglionar asociada. La Adenosin deaminasa alta en LP permitiría apuntar con mucha seguridad a una TBC pleural aunque convendría confirmar el diagnostico con una biopsia pleural dado que se puede presentar también en linfomas y empiemas de otro origen.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-12b2c9a5fa0b', '5289156b9fe7e7bcb92ec20b01155c5463e966f5', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Una mujer de 85 años consulta por cansancio y debilidad especialmente por las mañanas. A veces se encuentra inestable al caminar y tiene que sentarse para recuperar el equilibrio. En dos ocasiones ha tenido que sentarse para no caer pero niega síntomas de mareo. Tiene hipertensión arterial, incontinencia urinaria y artrosis. Su tratamiento es hidroclorotiazida (25 mg/d), oxibutinina (10 mg/d), lisinopril (10 mg/d), calcio (1500 mg/d) y paracetamol (3 gr/d). A la exploración destaca una tensión arterial de 115/70 mm Hg, pulso 80 lpm. Sus movimientos son lentos. Tiene un temblor moderado las manos. Puede levantarse de la silla lentamente pero sin necesidad de apoyarse en los brazos. Camina levemente inclinada hacia adelante con poco balanceo de los brazos. Gira lentamente pero sin perder el equilibrio. No es capaz de mantenerse sobre un solo pie.', '¿Cuál de las siguientes posibles actuaciones realizaría en primer lugar?', '[{"position": 1, "text": "Valorar agudeza visual."}, {"position": 2, "text": "Realizar una resonancia magnética."}, {"position": 3, "text": "Estudio con mesa basculante."}, {"position": 4, "text": "Medir la tensión arterial tumbada y levantada."}, {"position": 5, "text": "Intento terapéutico con L-dopa."}]'::jsonb, 5, 5, 'definitiva', 'La respuesta correcta es iniciar tratamiento con L-dopa, ya que la clínica descrita es de un parkinsonismo cuyo diagnóstico es exclusivamente clínico. El resto de respuestas pueden realizarse para diagnóstico diferencial, pero la realización de pruebas complementarias no justifica el retraso del inicio de tratamiento.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d3e22998edc1', '8de97b15b9d26a25d6f43be18eba7b92c7bc7daf', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'Un paciente ex fumador, diagnosticado previamente de EPOC acude a revisión. En la exploración física se detecta la existencia de hipocratismo digital de aparición reciente.', '¿Cuál es la explicación más aceptable para este hallazgo en el contexto clínico que se describe?', '[{"position": 1, "text": "Carcinoma pulmonar."}, {"position": 2, "text": "Bronquiectasias."}, {"position": 3, "text": "Fibrosis pulmonar."}, {"position": 4, "text": "Cardiopatía cianótica."}]'::jsonb, 4, 1, 'definitiva', 'En una hipocratismo digital de aparicion reciente en un paciente fumador, la primera opción a descartar es el carcinoma broncopulmonar. Las otras patologías también pueden dar pero no de forma tan súbita.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos')
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('casimedicos-939fedafd577', 'e6a0630c49e114ac329c3b15cdefd895996d5d72', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'Hombre de 55 años que consulta por disfonía. En la anamnesis refiere llevar un mes con astenia y pérdida de peso no cuantificada. La radiografía de tórax presenta un aumento de densidad en lóbulo superior izquierdo y ocupación de la ventana aortopulmonar. La broncoscopia constata una parálisis de la cuerda vocal izquierda, sin imagen endoscópica sugestiva de neoplasia.', '¿Cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Neoplasia pulmonar."}, {"position": 2, "text": "Sarcoidosis."}, {"position": 3, "text": "Silicosis."}, {"position": 4, "text": "Tuberculosis."}]'::jsonb, 4, 1, 'definitiva', 'La causa mas frecuente de parálisis del nervio recurrente es el carcinoma broncopulmonar. Que no sea accesible a la visión endoscópica no quiere decir que no este.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-a95c187dd441', '59d3e7797cde2b17920d51bae04aeed114c48548', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Nos remiten desde oftalmología a un hombre de 31 años que consultó por pérdida de visión y cefalea progresiva. En la exploración fisica se constata una hemianopsia temporal y en la resonancia magnética hipofisaria una turnoración de 35 x 30 x 20 mm que comprime quiasma y seno cavernoso. Los resultados del estudio funcional son cortisol 14 microg/dL, TSH 1,4 microU/ml, T4L 1,2 ng/dL, prolactina 480 microg/L (vn < 15), testosterona 160 ng/dL (vn 300-1200), FSH 1,2 U/I., (vn 5-15) y LH 2 U/L (vn 3-15).', '¿Cuál es el abordaje terapéutico inicial?:', '[{"position": 1, "text": "Agonistas dopaminérgicos."}, {"position": 2, "text": "Cirugia transesfenoidal."}, {"position": 3, "text": "Radioterapia externa o radiocirugía."}, {"position": 4, "text": "Tratamiento del hipogonadismo hipogonadotropo con testosterona."}]'::jsonb, 4, 1, 'definitiva', 'Por lo que nos describen se trata de un macroprolactinoma al tratarse de una tumoración hipofisaria de más de un centímetro, que segrega prolactina y con una insuficiencia del resto de hormonas hipofisarias. El tratamiento de elección de primera línea son los agonistas dopaminérgicos, aunque cuando afecta al campo visual se puede optar por la opción quirúrgica. En este caso al comentarnos que el seno cavernoso se encuentra presionado por la masa por lo que el riesgo quirúrgico aumenta. Por ello, en este caso particular, la opción quirúrgica parece más arriesgada. Teniendo en cuenta esto y que es un tumor productor de altos niveles de prolactina, lo que nos indica que probablemente responda al bloqueo farmacológico, la opción más adecuada sería la 1, el tratamiento con agonistas dopaminérgicos.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-161e14e76ff0', '3aa3130842e5a721a78dd2e94a36e02580db4bd4', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Paciente de 45 años en estudio por posible meningitis, con fiebre, cefalea y vómitos de 2 días de evolución. Le realizan una RM cerebral y una punción lumbar. Veinte horas después, al levantarse para ir al baño, se queja de cefalea intensa, muy marcada al incorporarse pero que desaparece al tumbarse. Ya no presenta fiebre ni vómitos.', '¿Cuál es con más probabilidad el origen de esta cefalea?', '[{"position": 1, "text": "La meningitis sigue siendo la causa fundamental de su cefalea, pues es el mismo tipo de cefalea que al inicio de los síntomas."}, {"position": 2, "text": "Es una cefalea post-punción lumbar."}, {"position": 3, "text": "Hay que buscar una causa diferente a esta cefalea, pues no es tipica del sindrome post-punción lumbar ni de la meningitis."}, {"position": 4, "text": "Lo más probable es que no fuera una meningitis viral, sino una hemorragia subaracnoidea. Por este motivo, la cefalea inicial desaparece casi completamente al tumbarse."}]'::jsonb, 4, 2, 'definitiva', 'El cuadro que describen de cefalea intensa con el ortostatismo que desaparece al tumbarse, aunque si bien es cierto que la presentación más típica es entre las primeras 24-48 horas y en este caso es algo anterior. Aún así el resto de respuestas son improbables: la primera no puede ser porque no nos han dicho como era la cefalea inicial, la tercera si bien podía ser por el tiempo de aparición (como ya dije un poco antes de lo esperado) la realidad es que es tan típica la cefalea con el ortostatismo que sería la causa más probable; la última tampoco podría ser porque una HSA no sigue ese patrón en relación con el ortostatismo.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5365a77f398b', '8e6194bf357bc7591d0c20637ebdb37743102600', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Hombre de 39 años de edad que en los 3 últimos meses ha tenido dos episodios de movimientos saltatorios amplios e involuntarios de miembros izquierdos, que en unos dos minutos llevan a pérdida de conciencia.', 'En el estudio neuroradiológico se ha encontrado una lesión expansiva frontal derecha sugestiva de glioma cerebral.¿Cómo clasificaría la epilepsia de este paciente?', '[{"position": 1, "text": "Generalizada sintomática."}, {"position": 2, "text": "Parcial sintomática."}, {"position": 3, "text": "Parcial criptogénica."}, {"position": 4, "text": "Parcial secundariamente generalizada sintomática."}]'::jsonb, 4, 2, 'definitiva', 'Hacen referencia a una crisis parcial que se sigue de pérdida de nivel de consciencia, por lo que senso estricto sería una crisis parcial compleja sintomática, no una crisis parcial secundariamente generalizada (que esto se da cuando los movimientos tónico-clónicos se extienden al resto de extremidades). Por este motivo la opción más correcta sería la dos porque no especifica que es una crisis parcial simple sintomática, sino que deja abierta la posibilidad de que se trate de una crisis parcial simple o compleja sintomática.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d1430712f445', '6a0e88e0630b062f38adde4ff1ad4224cca53780', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', NULL, 'Una paciente de 65 años debutó dos años antes con una apraxia del habla y evolutivamente ha desarrollado un parkinsonismo rigido-acinético de predominio en hemicuerpo derecho con mioclonias sobreimpuestas y fenómeno de mano alienígena o miembro extraño. ¿Qué diagnóstico considera más probable?', '[{"position": 1, "text": "Enfermedad de Parkinson."}, {"position": 2, "text": "Degeneración corticobasal."}, {"position": 3, "text": "Enfermedad de Alzheimer."}, {"position": 4, "text": "Enfermedad de Huntington."}]'::jsonb, 4, 2, 'definitiva', 'Por como nos lo describen como un fenómeno apráxico que se sigue de un parkinsonismo rígido-acinético asimétrico y con mioclonías sobreañadidas es típico de la degeneración córticobasal. La enfermedad de parkinson no puede ser porque no presentan apraxia como rasgo inicial, el Alzheimer no presenta un parkinsonismo asimétrico y el Hungtinton típico no es de personas tan mayores y cuando debuta con edad avanzada se comporta como una corea.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-76d498900bcf', 'b879a54af27ada1e92f924773ac1b0f4b0186e9a', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Un paciente de 72 años acude a consulta con pérdida de memoria progresiva y dificultad para encontrar las palabras de un año de evolución.', '¿Cuál es la exploración más útil para caracterizar el tipo de déficit cognitivo que presenta?', '[{"position": 1, "text": "Evaluación neuropsicológica."}, {"position": 2, "text": "Resonancia magnética cerebral."}, {"position": 3, "text": "Tomografía de Emisión de Positrones."}, {"position": 4, "text": "Electroencefalograma."}]'::jsonb, 4, 1, 'definitiva', 'La caracterización de los precesos de deterioro cognitivo sigue siendo clínica, siendo las pruebas de imagen (RM o PET) una herramienta de apoyo en algunas ocasiones. Sería la opción correcta la primera porque permite medir de forma estandarizada cada uno de los dominios cognitivos lo que nos permitirá encuadrar los déficis del paciente en un síndrome concreto y la monitorización del deterioro con exploraciones repetidas en el tiempo.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-b6abece4d90b', 'a3f7d6497f68110437fcc61a526008f34523de7e', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Una chica de 20 años acude a urgencias porque ha notado tras levantarse, al mirarse al espejo, debilidad en toda la mitad derecha de la cara (incluida la frente, cerrar el párpado y para sonreir) Se acompaña de disgeusia, con sensación de sabor metálico de los alimentos asi como de hiperacusia y dolor mastoideo ipsilateral. En la exploración no se evidencia déficit de la fuerza ni déficits sensitivos en extremidades ni alteraciones del habla ni lenguaje.', 'En este caso,¿cuál de las siguientes aseveraciones es la correcta?', '[{"position": 1, "text": "El diagnóstico más probable es una placa desmielinizante en hemiprotuberancia contralateral, la exploración complementaria más necesaria Sería una resonancia magnética craneal."}, {"position": 2, "text": "Los corticoides vía oral son de elección en el tratamiento de la paciente."}, {"position": 3, "text": "Debe ser considerada la fibrinolisis endovenosa si el tiempo de evolución es menor a 3h."}, {"position": 4, "text": "Lo más probable es que el cuadro sea irreversible."}]'::jsonb, 4, 2, 'definitiva', 'Nos describen un cuadro de parálisis facial periférica típica, con disgeusia, hiperacusia y dolor mastoideo. En este caso el tratamiento es corticoideo. No sería correcta la primera porque aunque dentro del rango de edad de debut de la esclerosis múltiple normalmente la presentación es gradual a lo largo de días y la afectación nuclear del VII nervio craneal (que podría simular un facial periférico) no provocaría disgeusia, hiperacusia ni dolor mastoideo. En la tercera respuesta nos proponen que se trate de un cuadro vascular y por tanto que la parálisis facial sea central, por lo que queda descartada y la última no es correcta porque la mayoría de las parálisis faciales periféricas idiopáticas (parálisis de Bell) curan sin secuelas.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7bbfb9846345', '8aa3eb236bc9a283de63640aba337663a34357be', NULL, NULL, NULL, false, false, 'Oftalmología', 'Una mujer de 78 años consulta por pérdida de visión aguda del ojo izquierdo. En las últimas 3 semanas ha presentado febrícula dolor en hombros cuello y caderas así como cefalea moderada. La funduscopia evidencia un disco óptico pálido y edematoso. La movilización de hombros y caderas produce dolor. No se observan alteraciones en la palpación de las arterias temporales. Datos analíticos: hemoglobina 9,7 g/dL ferritina 450 ng/mL velocidad de sedimentación globular 115 mm/h.', '¿Cuál es la acción inmediata más apropiada en esta paciente?', '[{"position": 1, "text": "Solicitar una ecobrafía doppler de arterias temporales."}, {"position": 2, "text": "Iniciar tratamiento con prednisona 60mg al día y aspirina 100 mg al día."}, {"position": 3, "text": "Iniciar tratamiento con prednisona 10 mg al día."}, {"position": 4, "text": "Solicitar una biopsia de arteria temporal."}, {"position": 5, "text": "Solicitar una resonancia nuclear magnética cerebral."}]'::jsonb, 5, 2, 'definitiva', 'La clínica que nos cuentan es fuertemente sugerente de arteritis de células gigantes (ACG), con febrícula, dolor en cintura escapular y pélvica, y cefalea. La edad y el sexo también apuntan a esa posibilidad. La pérdida visual unilateral brusca, con edema pálido de papila es muy indicativo de neuropatía óptica isquémica arterítica por ACG. La VSG está elevada, que nos viene a aclarar más todavía el diagnóstico. Tenemos que iniciar rápidamente el tratamiento corticoideo. Ya podemos descartar la 1 y la 5 porque no aportan nada. La 4 podría hacernos dudar, y es cierto que tendremos que pedir una biopsia de arteria temporal, pero eso no es lo inmediato: en el enunciado nos lo dejan muy claro que tenemos que actuar en seguida. La tendencia actual es utilizar megadosis de corticoides intravenosos, y a pesar de que tradicionalmente se ha propuesto la aspirina para reducir los eventos isquémicos, la evidencia señala en este momento que los antiagregantes no aportan mucho. Una dosis oral de corticoide en torno de 1mg/Kg también sería aceptable. Por lo tanto, si descartamos la 3 porque la dosis es demasiado baja, tendríamos que quedarnos con la 2. Con reservas, ya que la aspirina tiene un papel más bien dudoso, y la dosis de corticoide queda ambigua (no sabemos cuánto pesa la paciente). De todas las preguntas de oftalmología, quizás esta es la que tiene más posibilidades de impugnarse.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-62ae27ceca80', 'e924e17124ba68707326694dd183376e64334450', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Un paciente de 25 años, durante un partido de tenis, tiene dolor intenso en el cuello y en el ojo izquierdo. La mañana siguiente se despierta con sensación de inestabilidad de la marcha y tiene ptosis palpebral del ojo izquierdo y anisocoria, siendo la pupila izquierda más pequeña que la derecha. El paciente mantiene buena agudeza visual.', '¿Dónde localizaría con más probabilidad la lesión?', '[{"position": 1, "text": "III par craneal."}, {"position": 2, "text": "Quiasma óptico."}, {"position": 3, "text": "Ganglio cervical superior."}, {"position": 4, "text": "Bulbo raquídeo."}]'::jsonb, 4, 4, 'definitiva', 'El cuadro que nos presentan es el de un síndrome de Horner (miosis con ptosis) por lo que las posibilidades quedan reducidas a las opciones 3 o 4, pero especifican que el paciente presenta inestabilidad de la marcha, que no se justifica por un Horner por disección carotídea que afecte el ganglio cervical superior, que es lo que nos quieren hacer creer cuando hablan del dolor en el cuello y en el ojo. Si el paciente verdaderamente tiene una ataxia, la única localización posible sería el bulbo raquídeo.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5dbe4050a8e7', '86921f1d1667d2027f25a12c103425e7b929e189', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Hombre de 33 años autónomo para todas las actividades de la vida diaria y con antecedentes de HTA bien controlada, fibrilación auricular antiagregada y un adenocarcinoma de próstata a los 73 años actualmente libre de enfermedad. Es traído a urgencias por clínica de afasia y hemiparesia derecha de inicio brusco, 45 minutos antes.', '¿Cuál es la actitud más correcta?', '[{"position": 1, "text": "Realizar TC craneal y si no hay lesiones hemorrágicas ni otras contraindicaciones en la analítica, iniciaría trombolisis endovenosa de forma inmediata."}, {"position": 2, "text": "Realizar TC craneal urgente y si no hay sangrado iniciar anticoagulación."}, {"position": 3, "text": "Realizar TC craneal e ingreso en centro de rehabilitación, ya que su actitud no diferirá independientemente de si la etiología es isquémica o hemorrágica."}, {"position": 4, "text": "No hace falta TC craneal, aunque retiraría la antiagregación."}]'::jsonb, 4, 1, 'definitiva', 'El paciente sufre un déficit neurológico brusco en probable relación con un evento vascular, por lo que en primer lugar tendremos que realizar un TC craneal para descartar que se trate de un ictus hemorrágico. Si el TC no muestra sangrado, el paciente presenta un ictus isquémico agudo, probablemente cardioembólico por su patología cardiológica, no anticoagulada. Dado que su proceso tumoral se encuentra controlado, no existen contraindicaciones para la administración de fibrinolísis en este caso, ya que el paciente presenta una buena situación basal. Aunque el paciente presenta 88 años, la edad ya no se presenta como un criterio de exclusión absoluto, sino que debe tenida en cuenta la situación general del paciente y en este caso especifican que presenta una buena situación basal.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-0506d0bdb1bd', '3bab64887173fdff11016e00164e44b38bcbaa7a', NULL, NULL, NULL, false, false, 'Pediatría', 'Niño de 12 meses de edad, que en los exámenes de salud practicados desde el nacimiento presenta testículo derecho en conducto inguinal que no es posible descender hasta el escroto.', 'Señale la respuesta correcta:', '[{"position": 1, "text": "El diagnóstico más probable es el de testículo retráctil."}, {"position": 2, "text": "Se ha de esperar hasta los dos años de edad a que ocurra descenso espontáneo del mismo."}, {"position": 3, "text": "La gonadotropina coriónica humana es el tratamiento de primera elección."}, {"position": 4, "text": "La indicación de orquidopexia no debe diferirse."}]'::jsonb, 4, 4, 'definitiva', 'El testículo retráctil se caracteriza porque el teste se encuentra permanentemente fuera de la bolsa escrotal, siendo posible descenderlo manualmente (aunque al soltarlo vuelve automáticamente a su ubicación inicial). Se suele deber a un pedículo corto. En este caso nos están diciendo que el teste se encuentra siempre en canal inguinal (criptorquidia) por lo que podemos descartar la opción 1. El tratamiento hormonal con HCG ya ha caído en desuso, debido a la poca eficacia, posibilidad de reascenso y porque se han descrito fenómenos apoptóticos e inflamatorios en el teste asociados a su uso (descartamos la opción 3). La orquidopexia es el tratamiento de elección cuando os encontramos ante una criptorquidia, siendo deseable realizarla entre los 6 meses y el año, no debiendo diferirse más allá de los dos años de edad.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-3ef91f603141', '0c61864bedd2223800f2fc6772b141ba86a4c913', NULL, NULL, NULL, false, false, 'Pediatría', NULL, '¿Cuál es el diagnóstico más probable de un recién nacido con microcefalia, retraso del crecimiento intrauterino, cardiopatía congénita, pie astrágalo vertical y una facies peculiar (microftalmia, hendiduras palpebrales pequeñas, micrognatia y orejas displásicas), las manos con el dedo índice y meñique sobre el medio y anular?', '[{"position": 1, "text": "Trisomía 18. (Síndrome de Edwards)."}, {"position": 2, "text": "Trisomía 13. (Sindrome de Patau)."}, {"position": 3, "text": "Trisomía 21. (Síndrome de Down)."}, {"position": 4, "text": "Trisomía 9."}]'::jsonb, 4, 1, 'definitiva', 'Está describiendo fielmente un S. de Edwards. Aunque las cardiopatías y la alteración del pie que describe son comunes a varias cromosomopatías, la alteración de los dedos de las manos es muy característica del Edwards.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-25dfb7d8d5ff', '42b769f23d53fcaf614185e02714ffba5d3c9a4d', NULL, NULL, NULL, false, false, 'Pediatría', NULL, 'La aparición de fiebre elevada de 39°C en un lactante de 10 meses que cede bruscamente después de 3-5 días, seguido de un exantema morbiliforme cefalocaudal con enantema constituido por pápulas rojizas en paladar, y que se resuelve en una semana, asociado a buen estado general, suele estar producido por:', '[{"position": 1, "text": "Parvovirus B19."}, {"position": 2, "text": "Herpes virus tipo 6."}, {"position": 3, "text": "Virus Coxackie A16."}, {"position": 4, "text": "Primoinfección por virus de Epstein-Barr."}]'::jsonb, 4, 2, 'definitiva', 'La pregunta de enfermedades exantemáticas que tanto gustan a los pediatras y a los que ponen el examen MIR. Por el cuadro de fiebre alta de varios días que cede súbitamente con aparición de un rash estamos ante un exantema súbito, causado por el Herpes virus tipo 6 (acordaos de la regla mnemotécnica de “Hexantema súbito”). El parvovirus B19 es el causante del eritema infeccioso o “quinta enfermedad”, cuyo exantema característico es en mejillas, dando aspecto de cara abofeteada. El coxackie A16 produce la herpangina y también la enfermedad boca-mano-pie, que presenta un exantema inicialmente macular, que no respeta palmas ni plantas y que evoluciona a vesículas que estallan. Por último, la infección por el VEB produce un síndrome mononucleósico que cursa con fiebre alta de varios días de evolución, con eritema faríngeo y exudados grisáceos en las amígdalas. Puede presentar si se dan penicilinas para tratarlo (al confundirlo con una faringoamigdalitis estreptocócica) un exantema generalizado. Además, también cursa con fatiga, inflamación hepática con aumento de transaminasas y esplenomegalia.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7a5a2e447205', '581bb334244c361607dc87e1c20c7f07a705600e', NULL, NULL, NULL, false, false, 'Pediatría', 'Lactante de 5 meses de edad alimentado con lactancia materna exclusiva hasta la actualidad que por motivo de trabajo materno se le introduce biberón con fórmula de inicio y hace unos días se le adiciona con cereales con y sin gluten. Como antecedentes familiares destaca madre de 28 años asmática, padre de 32 años sano y hermano de 5 años afecto de enfermedad celíaca y dermatitis atópica. Como antecedentes personales, embarazo sin incidencias y parto mediante cesárea habiéndosele ofrecido biberón con fórmula de inicio el primer día de vida en la maternidad. Desde hace unos días comienza con distensión abdominal, deposiciones diarreicas, rechazo a las tomas, eritema peribucal con duración más prolongada en el tiempo tras la ingesta del biberón y últimamente vómitos tras su ingesta, tolerando bien el pecho materno.', '¿Cuál es su diagnóstico más probable?', '[{"position": 1, "text": "Enfermedad celíaca."}, {"position": 2, "text": "Gastroenteritis aguda."}, {"position": 3, "text": "Alergia a las proteínas de la leche de vaca."}, {"position": 4, "text": "Alergia a los biberones."}]'::jsonb, 4, 3, 'definitiva', 'Niño con múltiples antecedentes familiares de alergia (asma, atopia), que ha recibido leche artificial en las primeras horas de vida (sensibilización a la proteína de la leche de vaca) y que coincidiendo con la toma de leche artificial inicia clínica digestiva y exantema = APLV.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7ccfd46076ef', '50b8b918b78ce2cf7624cbd1fafd1a665fa991a9', NULL, NULL, NULL, false, false, 'Oftalmología', 'Mujer de 52 años que consulta por haber notado durante la semana previa coloración amarillenta de conjuntivas. No refiere conductas sexuales de riesgo ni antecedentes epidemiológicos de riesgo de hepatitis vírica. No consume alcohol ni fármacos hepatotóxicos. Relata historia de un año de evolución de prurito generalizado astenia sequedad de boca y ausencia de lagrimeo de causa no filiada. Resto de la anamnesis sin datos patológicos. En la exploración física se observan lesiones de rascado ictericia conjuntival y hepatomegalia no dolorosa. Aporta analítica realizada en su empresa con los siguientes resultados patológicos: bilirrubina total 3 mg/dl fosfatasa alcalina 400 UI velocidad de sedimentación 40 mm a la primera hora.', 'Indique cual sería la recomendación más acertada para establecer el diagnóstico etiológico del cuadro que presenta la paciente:', '[{"position": 1, "text": "Anticuerpos antimitocondriales."}, {"position": 2, "text": "Estudio del metabolismo del hierro."}, {"position": 3, "text": "Estudio del metabolismo del cobre."}, {"position": 4, "text": "Resonancia magnética hepática."}, {"position": 5, "text": "Serología de virus B y virus C."}]'::jsonb, 5, 1, 'definitiva', 'Una mujer de mediana edad con síntomas similares al Sjögren (ausencia de lagrimeo, sequedad de boca), con hiperbilirrubinemia, ictericia y hepatomegalia, nos hace pensar en una cirrosis biliar primaria. Para diagnosticarlo utilizaremos anticuerpos antimitocondriales (AMA IgG). Por lo tanto, sería la respuesta 1.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f66ab14e58e3', '349e33da732c6ddfe997832b2255ff4b1805b4af', NULL, NULL, NULL, false, false, 'Psiquiatría', 'Hombre de 26 años, soltero, que es traído a consulta por su familia por llevar 3 meses negándose a salir se su casa. La razón que aduce el paciente es el convencimiento de que tiene la mandíbula asimétrica y la cara torcida. Según refiere esta situación es progresiva y cada vez se ve mas deforme cuando se observa en el espejo. Se avergüenza de su aspecto, por lo que no quiere salir, se angustia mucho cuando ve su imagen y no puede dejar de pensar todo el día en su deformidad. Ha consultado con varios cirujanos maxilofaciales pero éstos le dicen que no presenta asimetría facial y lo remiten al psiquiatra.', 'El diagnóstico del paciente es:', '[{"position": 1, "text": "Trastorno depresivo mayor con ideas delirantes incongruentes con el estado de ánimo."}, {"position": 2, "text": "Trastorno obsesivo compulsivo."}, {"position": 3, "text": "Esquizofrenia paranoide."}, {"position": 4, "text": "Trastorno dismórfico corporal."}]'::jsonb, 4, 4, 'definitiva', 'Otra pregunta sencilla de respuesta inmediata, que no ofrece duda. Nos describe a un paciente preocupado por un defecto físico inexistente, cuya preocupación le angustia e impide salir de casa. Como residente de psiquiatría me gustaría que las preguntas del MIR de mi especialidad invitaran algo más a la reflexión y a la profundidad, aunque sé que los segundos que os habréis ahorrado al marcar la cuarta directamente son muy valiosos.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e889494b660e', '9bfea7676a66e8ab587334e7aafe38d9c0d66796', NULL, NULL, NULL, false, false, 'Psiquiatría', 'Una paciente presenta una larga historia de múltiples síntomas físicos: pérdida de memoria, dolor de cabeza, mareos, vómitos, dolor genital, dolor en extremidades, distensión abdominal e irregularidades menstruales. Los diversos exámenes médicos han descartado enfermedad médica alguna.', '¿Cuál de los siguientes cuadros es más probable que padezca?', '[{"position": 1, "text": "Trastorno conversivo."}, {"position": 2, "text": "Trastorno hipocondríaco."}, {"position": 3, "text": "Trastorno de somatización."}, {"position": 4, "text": "Trastomo disociativo."}]'::jsonb, 4, 3, 'definitiva', 'Según la CIE-10 los criterios para diagnosticar el Trastorno de somatización (F45.0) son: A. Historia de múltiples síntomas físicos, que empieza antes de los 30 años, persiste durante varios años y obliga a la búsqueda de atención médica o provoca un deterioro significativo social, laboral, o de otras áreas importantes de la actividad del individuo. B. Deben cumplirse todos los criterios que se exponen a continuación, y cada síntoma puede aparecer en cualquier momento de la alteración: 1. Cuatro síntomas dolorosos: historia de dolor relacionada con al menos cuatro zonas del cuerpo o cuatro funciones (p. ej., cabeza, abdomen, dorso, articulaciones, extremidades, tórax, recto; durante la menstruación, el acto sexual, o la micción). Dos síntomas gastrointestinales: historia de al menos dos síntomas gastrointestinales distintos al dolor (p. ej., náuseas, distensión abdominal, vómitos [no durante el embarazo], diarrea o intolerancia a diferentes alimentos). 3. Un síntoma sexual: historia de al menos un síntoma sexual o reproductor al margen del dolor (p. ej., indiferencia sexual, disfunción eréctil o eyaculatoria, menstruaciones irregulares, pérdidas menstruales excesivas, vómitos durante el embarazo). 4. Un síntoma pseudoneurológico: historia de al menos un síntoma o déficit que sugiera un trastorno neurológico no limitado a dolor (síntomas de conversión del tipo de la alteración de la coordinación psicomotora o del equilibrio, parálisis o debilidad muscular localizada, dificultad para deglutir, sensación de nudo en la garganta, afonía, retención urinaria, alucinaciones, pérdida de la sensibilidad táctil y dolorosa, diplopía, ceguera, sordera, convulsiones; síntomas disociativos como amnesia; o pérdida de conciencia distinta del desmayo). C. Cualquiera de las dos características siguientes: 1. Tras un examen adecuado, ninguno de los síntomas del Criterio B puede explicarse por la presencia de una enfermedad médica conocida o por los efectos directos de una sustancia (p. ej., drogas o fármacos). 2. Si hay una enfermedad médica, los síntomas físicos o el deterioro social o laboral son excesivos en comparación con lo que cabría esperar por la historia clínica, la exploración física o los hallazgos de laboratorio. D. Los síntomas no se producen intencionadamente y no son simulados (a diferencia de lo que ocurre en el trastorno facticio y en la simulación). Todo cuadra con lo descrito en el enunciado. Descartamos el trastorno conversivo o disociativo porque éstos suelen estar relacionados con factores psicológicos, asociados al síntoma o al déficit (no deliberado). El inicio o la exacerbación del cuadro vienen precedidos por conflictos u otros desencadenantes, algo que no menciona el enunciado. Tampoco sería un Trastorno hipocondríaco porque esto supone una preocupación y miedo a tener, o la convicción de padecer, una enfermedad grave a partir de la interpretación personal de síntomas somáticos. Pero no conlleva la existencia de signos o síntomas físicos.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e3b1f4604e72', 'b69d3462b9b52390e8364ec0c998e64b9a5d3005', NULL, NULL, NULL, false, false, 'Psiquiatría', 'Mariano es un señor de 53 años de edad que acude a su consulta refiriendo sentir un gran malestar desde hace ya unos años. Relaciona el malestar con una conducta que encuentra absurda pero que es incapaz de evitar. Esta conducta que lleva a cabo siempre al llegar a su casa de vuelta del trabajo consiste en accionar el pomo del baño del piso superior de la vivienda antes de hacer cualquier otra cosa, incluso antes de saludar a su familia. Algunas veces ha intentado resistirse a hacerlo pero solo ha conseguido angustiarse y demorar la conducta unos minutos.', 'Éste comportamiento que Mariano realiza de un modo incoercible y automático es lo que se denomina:', '[{"position": 1, "text": "Trastorno obsesivo-compulsivo."}, {"position": 2, "text": "Obsesión."}, {"position": 3, "text": "Impulsión."}, {"position": 4, "text": "Compulsión."}]'::jsonb, 4, 4, 'definitiva', 'En esta pregunta piden el nombre del síntoma, no de la enfermedad, así que por ello la respuesta correcta es compulsión. Según el DSM-5, una compulsión es un comportamiento (p.ej: lavarse las manos, ordenar, comprobar cosas) o acto mental (p.ej: rezar, contar, repetir palabras en silencio) repetitivo que el sujeto realiza como respuesta a una obsesión o de acuerdo con reglas que ha de aplicar de forma rígida. El objetivo de los comportamientos o actos mentales es prevenir o disminuir la ansiedad o malestar, o evitar algún suceso o situación temida; sin embargo, estos comportamientos o actos mentales no están conectados de una manera realista con los destinados a neutralizar o prevenir o bien resultan claramente excesivos.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-b03dec02d8a1', 'f30550b75061fb865cfda18508dae16fabb4d178', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Usted valora a un paciente de 66 años con dolor inguinal acentuado con la bipedestación prolongada algunos días al mes. Una radiografía simple de caderas muestra estrechamiento del espacio articular fémoro-acetabular, esclerosis y ostefitos.', '¿Cuál es su actitud?', '[{"position": 1, "text": "Hago el diagnóstico de coxartrosis y envío al traumatólogo para colocar una prótesis de cadera."}, {"position": 2, "text": "Inicio tratamiento con opioides débiles que han demostrado evidencia en detener la progresión de la enfermedad."}, {"position": 3, "text": "Instauro tratamiento con paracetamol, explico que la evolución es muy variable y la indicación quirúrgica depende de la funcionalidad y control del dolor."}, {"position": 4, "text": "Por las características radiológicas descritas, necesito una RMN de cadera antes de tomar una decisión terapéutica."}]'::jsonb, 4, 3, 'definitiva', 'Presenta una coxartrosis (no se necesitan más pruebas de imagen), y se agotan las opciones conservadoras antes de optar por el tratamiento quirúrgico. Los opioides débiles no son el tratamiento inicial de elección.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c4180ee7790d', 'ce87d67234f9c6a99f06f0dda8adbcfda6beb32f', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Chico de 20 años, que consulta por dolor lumbosacro de ritmo inflamatorio de 4 meses de evolución. También talalgia bilateral y rigidez matutina de 1 hora. En los últimos 2 meses aparición de cuadros diarreicos con pérdida de 4 kg de peso.', '¿Cuál es la aproximación diagnóstica más correcta?', '[{"position": 1, "text": "Dada la edad del paciente, lo más probable es que padezca lumbalgia inespecífica y una tendinitis en los pies. Si persisten las diarreas realizaría estudio digestivo."}, {"position": 2, "text": "Realizaría estudio digestivo para descartar patología tumoral. El dolor lumbar puede ser debido a patología visceral."}, {"position": 3, "text": "El cuadro clínico es muy sugestivo de espondiloartritis. Habría que descartar enfermedad inflamatoria intestinal."}, {"position": 4, "text": "Solicitaría RMN lumbar para descartar hernia discal y si persiste diarrea, estudio digestivo."}]'::jsonb, 4, 3, 'definitiva', 'El paciente presenta las características clínicas de una espondilartropatía, que a menudo se asocia a enfermedad inflamatoria intestinal, como sugiere este caso.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-ce275f3653da', '2e9ee89f3c9576d9631b45c19b0db7ded3bd0b40', NULL, NULL, NULL, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', 'Mujer de 60 años, con diagnóstico de cáncer de mama tratado con cirugía y radioterapia hace 10 años. Actualmente con metástasis a nivel columna dorsal y articulación sacroilíaca por lo que durante los últimos dos años ha recibido tratamiento con ácido zoledrónico i.v. de forma mensual. Acude a la consulta por presentar exposición ósea de forma espontánea a nivel del hueso mandibular de aproximadamente 2 cm. No existen signos de infección aguda y la encía alrededor de la exposición ósea es estrictamente normal. El TAC mandibular evidencia una zona de esclerosis ósea.', '¿Cuál sería su diagnóstico?', '[{"position": 1, "text": "Absceso odontógeno."}, {"position": 2, "text": "Osteonecrosis por bifosfonatos."}, {"position": 3, "text": "Osteorradionecrosis."}, {"position": 4, "text": "Raíz dental incluída."}, {"position": 5, "text": "Metástasis de carcinoma de mama."}]'::jsonb, 5, 2, 'definitiva', 'Ésta me ha resultado difícil, vamos a ir descartando. La 1 no puede ser, porque habría signos infecciosos. La 2 es posible porque los bifosfonatos crean necrosis mandibular. La 3 me parece poco probable porque la radioterapia que recibió la paciente estaría orientada sobre la mama y no sobre la mandíbula. La 4 la descarto, no es un cuadro de raíz dental incluída. La 5 es posible; al fin y al cabo, la paciente ya tiene metástasis óseas. Así pues, dudo entre dos, la 2 y la 5, ¿cuál escoger? Desde luego no sé bien qué significado tiene una esclerosis ósea en un TAC, pero una metástasis en un hueso tendría un comportamiento más destructivo que esclerotizante. Por otro lado, usando psicología inversa, ¿qué quería el que puso la pregunta que yo supiera? ¿Que los bifosfonatos pueden crear necrosis mandibular? ¿O que una mujer con varias metástasis óseas puede tener una metástasis también en la mandíbula? Lo segundo parece demasiado sencillo, y haría que me inclinara más hacia la 2, pero no lo tengo claro. Sea como sea, entre dos respuestas posibles hay que contestar siempre, y entre la 2 y la 5, hay que marcar la 2, que es más probable.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-60b26dc96ba3', '4325aa824eb0934cc61080c5f2f31a73300733cf', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Una mujer de 76 años sin otros antecedentes que hipertensión arterial, consulta por ictericia indolora y prurito con anorexia. Analíticamente destaca bilirrubina de 12 mg/dl (9,5 de directa). La ecografía muestra dilatación biliar intra y extrahepática junto con un nódulo hepático único menor de 2 cm localizado periféricamente en la cara anterior de lóbulo izquierdo. La TC confirma estos hallazgos demostrando además la presencia de masa pancreática de 3,5 cm. En la cabeza pancreática. La punción aspiración del nódulo hepático resulta concluyente para adenocarcinoma.', 'Señale la mejor opción terapéutica:', '[{"position": 1, "text": "Quimio/radioterapia neoadyuvante, condicionando la opción de cirugía radical a la respuesta inicial."}, {"position": 2, "text": "Drenaje biliar externo percutáneo con carácter paliativo con eventual reconversión a drenaje interno en caso de intolerancia o complicaciones."}, {"position": 3, "text": "Derivación biliar quirúrgica paliativa con o sin gastroyeyunostomía profiláctica en función de los hallazgos intraoperatorios."}, {"position": 4, "text": "Prótesis biliar metálica mediante colangiopancreatografía retrógrada endoscópica con opción a quimioterapia paliativa."}, {"position": 5, "text": "Duodenopancreatectomía cefálica, con ablación percutánea mediante radiofrecuencia o alcoholización de la lesión hepática."}]'::jsonb, 5, 4, 'definitiva', 'Caso que no me parece tan fácil. Es un adenocarcinoma de páncreas con metástasis, por lo cual el tratamiento debe ser paliativo con lo que quitamos las opciones 1 y 5. En principio es una paciente con moderadamente buen estado general con lo que lo ideal sería hacer una derivación biliar permanente y quimioterapia siendo la 4 la opción que considero más correcta.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-b54bb7a0ded5', '2d328c2ff5512a9daf359bce9fdb6466b0428344', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Un niño de 13 años presenta dolor dorsal de varios meses de evolución, sólo a la bipedestación y a la marcha, ¿Qué diagnóstico debemos de pensar?', '[{"position": 1, "text": "Enfermedad de Scheuermann."}, {"position": 2, "text": "Escoliosis torácica."}, {"position": 3, "text": "Tumor maligno del cuerpo vertebral."}, {"position": 4, "text": "Se trata de una sobrecarga mecánica."}]'::jsonb, 4, 4, 'definitiva', 'El dolor es de características mecánicas, y la causa más frecuente de dolor mecánico de espalda en adolescentes es la sobrecarga mecánica. No hay datos en el enunciado que orienten hacia ninguna de las otras etiologías.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-3660406ddd9d', '9d2657e003c6425ca4f88c658965e7c36caab007', NULL, NULL, NULL, false, false, 'Atención Primaria', 'Juan, residente de segundo año, atiende en urgencias a Sofia, una muchacha de 15 años que, al parecer, se ha desmayado en la escuela sin llegar a perder la conciencia. La paciente cuenta que estaba pendiente de realizar un examen, lo que le causaba mucha ansiedad. Por el interrogatorio, parece entreverse una situación de cierto acoso por parte de sus compañeros y la posibilidad de que sufra un trastorno alimentario. Las constantes vitales y exploración neurológica son normales. Juan mantiene a Soﬁa en observación a la espera de que sus padres acudan al servicio echando, periódicamente, una ojeada a cómo se encuentra la paciente. Tras el susto inicial, la paciente parece encontrarse cada vez más animada y es muy simpática. En una ocasión, Juan la encuentra chateando activamente con su móvil. Juan le indica que sería mejor que dejase el móvil y descansase y para tranquilizarla, le cuenta que el también utiliza mucho las redes sociales desde la facultad. Soﬁa pide perdón por desconocer que tenía que tener el móvil apagado, y tras apagarlo, le pregunta si podrá hacerle una solicitud de amistad en Facebook.', '¿Cuál cree que es la mejor respuesta de Juan?', '[{"position": 1, "text": "Decirle que haga la solicitud de amistad y que la aceptará, pues está seguro de que en su página no hay elementos inapropiados para una chica de la edad de Soﬁa."}, {"position": 2, "text": "Dado que considera a Soﬁa una paciente vulnerable y le preocupa que pueda interpretar mal un rechazo, aceptar que haga la solicitud pero solamente permitirle el acceso a determinados contenidos de su página."}, {"position": 3, "text": "Contestarle que es importante mantener unos ciertos limites profesionales entre pacientes y facultativos y que, desafortunadamente, si hace la petición no podrá aceptarla, por lo que mejor que no lo haga."}, {"position": 4, "text": "Decirle que haga la petición pero sin intención de aceptarla."}]'::jsonb, 4, 3, 'definitiva', 'Es indudable que la relación médico-paciente hoy día trasciende el entorno físico de la consulta. Pero no debemos olvidar que debemos mantener en ella los mismos códigos éticos y profesionales que en el entorno real. El código deontológIco Artículo 26-3. El ejercicio clínico de la medicina mediante consultas exclusivamente por carta, teléfono, radio, prensa o internet, es contrario a las normas deontológicas. La actuación correcta implica ineludiblemente el contacto personal y directo entre el médico y el paciente.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-050b76fa744e', '1f9696243cc02304ba51089c985f79bc03eaee5b', NULL, NULL, NULL, false, false, 'Oncología', 'Acude a la consulta una mujer de 30 años de edad refiriendo en los tres últimos meses ansiedad, pérdida de unos 6 kgs de peso y sensación de “nerviosismo”. En la exploración física destaca taquicardia, hiperreflexia y ausencia de bocio. En la analítica realizada los valores de la TSH son < 0.01 microU/mL, la T4 está elevada y los niveles de tiroglobulina descendidos. Al realizarle una gammagrafía se detecta una ausencia de captación en la región tiroidea.', '¿Cuál le parece el diagnóstico más probable?', '[{"position": 1, "text": "Tirotoxicosis facticia."}, {"position": 2, "text": "Hipertiroidismo por Enfermedad de Graves."}, {"position": 3, "text": "Teratoma de ovario (estruma ovárico)."}, {"position": 4, "text": "Tiroiditis subaguda."}]'::jsonb, 4, 1, 'definitiva', 'Los pacientes que padecen este trastorno ingieren voluntaria o accidentalmente cantidades excesivas de hormona tiroidea, lo que provoca hipertiroidismo en ausencia de bocio. En contraste con todas las demás causas de hipertiroidismo, la tiroglobulina sérica no está elevada y está casi siempre baja o en el límite inferior de la normalidad. La duda fundamental la tuvimos con el teratoma del ovario (struma ovárico) que es una variante poco frecuente de teratoma maduro monodermal compuesto por tejido tiroideo descrito a principios del siglo XX. Recibe este nombre cuando el teratoma está compuesto predominantemente por tejido tiroideo maduro (al menos un 50%, para poder clasificarlo como struma ovarii). Representa entre el 2,5 y 5% de los teratomas ováricos. En sí, es una tumoración benigna, pero hasta en un 5% de casos puede desarrollar una transformación maligna de sus elementos, denominándose clásicamente en estos casos struma ovarii maligno. Principalmente, el tejido neoplásico desarrollado es un carcinoma papilar, menos frecuentemente corresponde a carcinoma folicular. Esta transformación maligna surge mayoritariamente de las formas clásicas de struma, pero es extremadamente infrecuente su aparición en casos de teratomas quísticos maduros. Su comportamiento es similar al de otros tumores ováricos primarios, tendiendo a metastatizar en cavidad peritoneal y vía hematógena a hueso, hígado y cerebro. La edad media de presentación del carcinoma tiroideo sobre struma ovarii se sitúa entre 42,9-44 años y entre 21 a 63 para la variante de carcinoma papilar. Clínicamente, la forma de presentación predominante es como masa pélvica o dolor abdominal (45%), menos frecuentemente hipertiroidismo (5-8%) o ascitis (17%). Se postula que el tejido tiroideo ovárico en el struma es autónomo en la producción de hormonas tiroideas, por lo cual es fundamental la medición de niveles séricos de tiroglobulina en pacientes afectadas de hipertiroidismo, ya que orientan hacia la producción extratiroidea de hormona tiroidea.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d795cfc735b4', 'e735468d447b253db6344b416bd37d7307850075', NULL, NULL, NULL, false, false, 'Atención Primaria', 'Mujer de 45 diagnosticada de cáncer de mama estadio IV con metástasis óseas múltiples en tratamiento hormonal y bifosfonatos iv. Acude a su consulta refiriendo dolor óseo intenso (EVA=7), en varias localizaciones sin sintomatología neurológica asociada y exarcerbaciones del dolor (EVA=9) varias veces al dia que le obligan a permanecer en reposo.', 'En el tratamiento con ibuprofeno (600 mg cada 8 h) y tramadol (150 mg al día). ¿Qué tratamiento consideraría más adecuado en este paciente para mejorar el dolor?', '[{"position": 1, "text": "Suspender ibuprofeno y tramadol e iniciar un opioide mayor como morfina u oxicodona."}, {"position": 2, "text": "Suspender tramadol, mantener ibuprofeno e iniciar un opioide mayor como morfina y oxicodona."}, {"position": 3, "text": "Suspender ibuprofeno y tramadol e iniciar un opioide mayor como morfina u oxicodona y a la vez iniciar tratamiento del dolor irruptivo con fentanilo sublingual"}, {"position": 4, "text": "Suspender tramadol, mantener ibuprofeno e iniciar un opioide mayor como morfina y oxicodona y a la vez tratamiento para el dolor irruptivo con fentanilo sublingual."}]'::jsonb, 4, 4, 'definitiva', 'La respuesta correcta es la 4 porque si la paciente tiene metástasis óseas y puede sufrir fracturas podemos controlar el dolor de tipo inflamatorio con el ibuprofeno y además nos irá bien para utilizar la sinergia antiálgica. Debemos cambiar el tratamiento a un opioide mayor y hacer tratamiento del dolor disrrupativo de forma enérgica ya que está en casi el dolor máximo que puede soportar.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4f8c9ddd417d', '41abb79fa285601145ad570dc263f7a8b2fdbf61', NULL, NULL, NULL, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', 'Paciente de 64 años de edad, fumador y bebedor importante que refiere adenopatía yugulodigástrica derecha no dolorosa de crecimiento progresivo en los últimos dos meses cuya punción-aspiración con aguja fina fue informada como carcinoma epidermoide.', 'Cuál de las siguientes localizaciones es la más probable del tumor primario:', '[{"position": 1, "text": "Cuero cabelludo."}, {"position": 2, "text": "Parótida."}, {"position": 3, "text": "Pulmón."}, {"position": 4, "text": "Esófago."}, {"position": 5, "text": "Laringe."}]'::jsonb, 5, 5, 'definitiva', 'Estás en medio del bloque de ORL. Ya has pasado el bloque de Neumología y el de Digestivo. Falta por salir el de Dermatología, pero un dermatólogo (respuesta 1) no preguntaría esto. Así que nos queda parótida y laringe; pero el carcinoma epidermoide de parótida es raro; yo marcaría la 5 y me quedaría tranquilo. Quizás porque todas las adenopatías a este nivel que yo he visto han acabado correspondiendo a carcinomas de la vía aérodigestiva superior.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-07e0f7d25801', '437d6814b42d926d96eccf33a31f34b1471cfebf', NULL, NULL, NULL, false, false, 'Atención Primaria', 'Un hombre de 75 a ingresa en el hospital porque se niega a comer y ha perdido un 30% de su peso. Tiene historia de esclerosis múltiple que ha empeorado en los últimos meses. Su único familiar que era su hermana murió hace 3 meses y desde entonces es cuando él se ha deteriorado. Se ha vuelto incontinente, ha dejado de comer y de participar en eventos sociales. Impresiona de depresión psicótica. Físicamente es capaz de comer. Se inicia medicación psicótropa que se suspende por eventos adversos. Si su estado nutricional mejora es posible retomar sus medicaciones. Rechaza líquidos intravenosos y luego los acepta pero se arranca la vía IV unas horas más tarde. Una alternativa es realizar una gastrostomía endoscópica percutánea (PEG) y darle alta a su residencia.', '¿Cuál de las siguientes actuaciones es la más apropiada para este paciente?', '[{"position": 1, "text": "Solicitar a la comisión de ética del hospital que ayude a determinar la decisión que sea de mayor interés para el paciente"}, {"position": 2, "text": "Valorar se la residencia acoge al paciente si no se realiza la PEG"}, {"position": 3, "text": "Pedir una orden judicial para realizar la PEG"}, {"position": 4, "text": "Enrolar al paciente en cuidados paliativos terminales"}]'::jsonb, 4, 1, 'definitiva', 'La respuesta correcta es la 1 ya que el paciente está en una situación de depresión psicótica y no es capaz de decidir por su vida y no parece que el paciente haya rellenado el documento de últimas voluntades lo más conveniente es presentar el caso a la comisión de ética del centro para que tome una decisión al respecto ajustada a derecho.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9f8b72957301', '2b769f4a3e21369a9d7e4a9fb20149f25adc83f1', NULL, NULL, NULL, false, false, 'Bioestadística', 'Una pareja con un primer hijo varón (caso índice) afecto de fibrosis quística (mucoviscidosis) acude a la consulta dc consejo genético. El diagnóstico molecular indica que el caso índice es homocigoto para la mutación F5O8del y sus padres portadores heterocigotos. El genetista clínico les informará acerca de la forma de transmisión de la enfermedad.', '¿Qué afirmación es la correcta?', '[{"position": 1, "text": "La probabilidad de que el siguiente descendiente esté afecto es del 25%."}, {"position": 2, "text": "La probabilidad de que el siguiente descendiente esté afecto es del 50%."}, {"position": 3, "text": "Al haber tenido un hijo afecto, el siguiente descendiente también estará afecto."}, {"position": 4, "text": "Al haber tenido un hijo homocigoto F5O8del, el siguiente descendiente será portador heterocigoto (67%) o de genotipo homocigoto sin la mutación (33%)."}]'::jsonb, 4, 1, 'definitiva', 'Los dos padres son portadores de una mutación (porque no están enfermos y ya han tenido un hijo homocigoto), y el próximo descendiente tiene un 50% de probabilidad de recibir la mutación de cada uno de los padres, por lo que la probabilidad de recibirla de ambos es 50%x50%=25%.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5e63b5eab501', '9b64afdd6f897213e678e953459733fc2b668741', NULL, NULL, NULL, false, false, 'Bioestadística', 'Isabel tiene tres hijos varones y una hija (María), todos ellos sanos. Un hermano y un tío materno de Isabel fallecieron por estar afectos de la enfermedad de Duchenne: una enfermedad recesiva ligada al cromosoma X. Actualmente, María desea quedarse embarazada y quiere conocer el riesgo de transmitir la enfermedad a su descendencia.', 'Con los datos recogido, ¿cuál es la probabilidad de que María sea portadora de la enfermedad de Duchenne?', '[{"position": 1, "text": "2/3."}, {"position": 2, "text": "1/2."}, {"position": 3, "text": "1/4."}, {"position": 4, "text": "Menos de 1/4."}]'::jsonb, 4, 3, 'definitiva', 'La abuela materna era portadora de la mutación en una copia del gen en un cromosoma X (no nos dicen que sufriera la enfermedad, y en cambio un hijo suyo, tío materno de Isabel, sí que la sufrió). La madre de Isabel sigue portándolo, ya que un hermano de Isabel ha sufrido la enfermedad pero no su padre. Así pues, Isabel tiene un 50% de probabilidades de haber heredado el gen mutado de la madre (como sus hijos están todos sanos, no estamos seguros de que sea portadora), y por lo tanto su hija un 25% de probabilidades de haber heredado el gen mutado de la abuela.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-3af427e56490', 'ad6191173cd86321cf4012e8d2bffbd3c40bd364', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Un hombre de 45 años, con antecedentes de un cuadro febril y dolor toracico, acude al hospital con disnea y taquipnea. En la exploración fisica las cifras de presión arterial estan bajas, la presión venosa yugular elevada con un seno x descendente prominente y tiene pulso paradójico.', '¿Qué diagnóstico sospecharía?', '[{"position": 1, "text": "Miocardiopatía dilatada."}, {"position": 2, "text": "Derrame pericardico con taponamiento cardiaco."}, {"position": 3, "text": "Pericarditis constrictiva."}, {"position": 4, "text": "Cardiopatia isquémica."}]'::jsonb, 4, 2, 'definitiva', 'Es la exploración clásica: tuvo cuadro febril y dolor, hizo una pericarditis con derrame, y ahora este está provocando un taponamiento. De ahí la hipotensión (su corazón no puede llenarse bien de sangre y bombear), la ingurgitación yugular y la dependencia de la respiración para conseguir precarga y gasto cardíaco (i.e. pulso paradójico).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e143dd721d57', '7afcebf3eaef888cb86f03e799b2fb5ae164d48e', NULL, NULL, NULL, false, false, 'Cirugía General', 'Mujer de 78 años con demencia e institucionalizada es traída por sus cuidadores por dolor abdominal importante con deterioro del estado general y distensión abdominal. Analítica con leucocitosis, hematocrito elevado, insuficiencia renal y acidosis metabólica. El ECG muestra fibrilación auricular. La tomografia abdominal detecta asas de intestino delgado edematizadas, con acumatosis Intestinal y portal.', 'El diagnostico mas probable es:', '[{"position": 1, "text": "Perforación de ulcus gastrico o duodenal."}, {"position": 2, "text": "lleo biliar."}, {"position": 3, "text": "Neoplasia obstructiva de sigma con perforación."}, {"position": 4, "text": "Isquemia mesentérica."}]'::jsonb, 4, 4, 'definitiva', 'Este es un cuadro clásico y el autor de la pregunta se ha preocupado de darnos las suficientes pistas para que no la fallemos. Al leer este enunciado se encienden múltiples alarmas: – Fibrilación auricular: En el mir y en la puerta de urgencias, cualquier anciano con una FA y dolor abdominal es una isquemia mesentérica de causa embolígena hasta que no se demuestre lo contrario. – Dolor abdominal agudo, SIRS, fracaso renal, acidosis metabólica (isquemia!), probablemente un láctico elevado… – TAC: El hallazgo de gas portal ambién es altamente indicativo de una isquemia mesentérica, también nos podrían haber hablado de neumatosis intestinal. ¿Por qué no son los otros cuadros? – Ulcus perforado: Nos habrían hablado de historia de consumo de AINES, o de una historia de dolor que mejora con la ingesta, de neumoperitoneo en Rx de tórax. – Íleo Biliar: Existirían antecedentes de cólicos biliares o de dolor en hipocondrio derecho, igualmente hablarían de aerobilia en prueba de imagen y dilatación de asas de delgado con imagen (o no) de litiasis biliar en ileon terminal. – Neo de sigma: En el mir nos hablarían de pérdida de peso, cambio de hábito deposicional, neumoperitoneo en Rx o TAC y exploración abdominal peritonítica pudiendo incluso palpar la masa.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-825a60c692c2', 'f809dee1c75c0d39b98f0bee5b818c74457a6f61', NULL, NULL, NULL, false, false, 'Cirugía General', 'Mujer de 80 años que acude urgencias con dolor abdominal de inicio en epigastrio e irradiado posteriormente a fosa iliaca izquierda. Se acompaña de fiebre de 37,5ºC, Se le realiza una TC abdominal, objetivando inflamación en las paredes del sigma y absceso mesenterico de 2 cm.', 'El tratamiento de elección es:', '[{"position": 1, "text": "lngreso en planta con dieta absoluta y tratamiento antibiótico de amplio espectro."}, {"position": 2, "text": "Colostomia de descarga."}, {"position": 3, "text": "Drenaje mediante cirugía laparoscópica."}, {"position": 4, "text": "Cirugía urgente con sigmoidectomía y anastomosis colorrectal."}]'::jsonb, 4, 1, 'definitiva', 'Nos preguntan por el manejo de una patología muy habitual, la diverticulitis. Y nos plantean las distintas opciones terapeúticas según lo avanzada que se encuentre. La respuesta correcta es la 1, no cumple criterios para requerir drenaje mediante punción guiada (el absceso no es mayor de 5-6 cm). La colostomía de descarga en este caso no tiene sentido alguno, ya que no se trata de solventar un cuadro obstructivo. El drenaje mediante cirugía laparoscópica no tiene indicación en este caso. Podría estar indicado en ausencia de posibilidad de drenaje percutáneo tras fracaso de tratamiento conservador, aunque es una opción muy discutida en este momento. La sigmoidectomía y anastomosis tampoco es requerida. En un alto número de casos tras la resolución del cuadro se reducen los brotes y pueden llegar a no volver a padecerlos con dieta y hábitos higiénico dietéticos.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7218f8664997', '26fd49299247a5205d78e18b7f3912a3c56b94b1', NULL, NULL, NULL, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', NULL, 'Ante un paciente con mal estado general, fiebre (temperatura axilar 39,5º), tumefacción submandibular bilateral de seis días de evolución, dolor bucal y trismus, ¿cuál de las siguientes afirmaciones es correcta?', '[{"position": 1, "text": "La primera probabilidad diagnóstica es de carcinoma de suelo de boca con metástasis cervicales bilaterales."}, {"position": 2, "text": "La prioridad terapéutica es garantizar la alimentación del paciente."}, {"position": 3, "text": "Nos encontramos casi con seguridad ante una mediastinitis."}, {"position": 4, "text": "Debemos considerar de forma prioritario el riesgo de obstrucción de la vía aérea."}, {"position": 5, "text": "Debemos realizar como primera medida diagnóstica una citología mediante punción aspiración con aguja fina."}]'::jsonb, 5, 4, 'definitiva', 'Este paciente está grave. El trismus y la fiebre obligan a pensar en una infección del espacio profundo cervical y eso no es un juego porque puede obstruirse la vía aérea. Sabiendo esto, las opciones 1, 2 y 5 están fuera de lugar y me quedan la 3 y la 4. Puede haber ya una mediastinitis; al fin y al cabo, la historia natural de las infecciones del espacio profundo cervical es ésa, pero la respuesta 4 es más correcta y además, estamos en el bloque de ORL, la especialidad de la vía aérea. Me gusta esta pregunta porque exige un conocimiento que es importante en la práctica clínica.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4a9b482f44ed', 'a137c2232bdc023b0016ebed3797c1af67c71004', NULL, NULL, NULL, false, false, 'Cirugía General', 'Hombre de 52 años de edad derivado al servicio de digestivo por cuadro de hematoquezia, tenesmo y reducción del diámetro de las heces. Se realizan una serie de pruebas, diagnosticandose un adenocarcinoma de sigma sin metastasis a distancia. El paciente es intervenido quirúrgicamente y remitido a la consulta de oncologia médica para valorar tratamiento quimioterapico complementario.', '¿Cual de los siguientes factores es de mal pronóstico tras la resección quirúrgica y habra que tener en cuenta a la hora de planificar el tratamiento de quimioterapia?', '[{"position": 1, "text": "La presencia de anemia al diagnóstico."}, {"position": 2, "text": "La existencia de antecedentes familiares de cancer colorrectal."}, {"position": 3, "text": "El tamaño de la lesión primaria y la diferenciación histológica."}, {"position": 4, "text": "La perforación o adhesión del tumor a órganos adyacentes."}]'::jsonb, 4, 4, 'definitiva', 'No están preguntando por factores que afectan al pronóstico oncológico y que por tanto implican un cambio en la estrategia QT. Esta pregunta es sencilla. La opción 4 nos está describiendo un estadio T4, bien por invasión de órganos adyacentes o bien por perforación. Los T4 conllevan una posibilidad de recidiva mucho mayor, de hecho hay estudios en marcha que plantean la HIPEC profiláctica en T4 y la cirugía de second look + HIPEC en tumores de colon perforados.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-755b1479d3e4', '2a3e46c0488c464d0989c8d60f3a954ca7d9a92c', NULL, NULL, NULL, false, false, 'Endocrinología', NULL, '¿Cual es el tratamiento de elección de un hombre de 38 años diagnosticado de enfermedad de Cushing en relación con un macroadenoma hipofisario de 22 mm de diámetro?', '[{"position": 1, "text": "Probar inicialmente tratamiento médico y, en caso de no ser efectivo, recurrir a cirugía."}, {"position": 2, "text": "Adrenalectomia."}, {"position": 3, "text": "Resección quirúrgica selectiva del adenoma."}, {"position": 4, "text": "Radioterapia para intentar disminuir el tamaño tumoral."}]'::jsonb, 4, 3, 'definitiva', 'A pesar de que la mayoría de los adenomas productores de ACTH recidivan, la primera opción terepéutica es siempre la cirugía. La medicación disponible (ketoconazol,análogos de la somatostatina) van dirigidos a disminuir los efectos del exceso de cortisol o disminuir la liberación de ACTH, pero no son curativos.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-0e54ceca67ee', '875b012da3f33d2333286361c474478e87fd66fc', NULL, NULL, NULL, false, false, 'Endocrinología', 'Una mujer de 27 años de edad consulta por presentar amenorrea secundaria de un año de evolución. No refiere antecedentes yatrogénicos. Analíticamente, la concentración de estradiol es inferior a la normalidad y el valor de prolactina es de 12 ng/mL.', 'Indique cual de las exploraciones que se citan a continuación solicitaría como primera medida para tratar de filiar el origen del trastorno:', '[{"position": 1, "text": "Resonancia magnética hipotalamohipofisaria."}, {"position": 2, "text": "Cariotipo."}, {"position": 3, "text": "FSH basal."}, {"position": 4, "text": "Estimulación con gonadotropina coriónica."}]'::jsonb, 4, 3, 'definitiva', 'Mujer joven con amenorrea secundaria, sin antecedentes de interés. Los valores de prolactina son normales (se considera hiperprolectinemia valores por encima de 20ngr/ml), descartándose por tanto hiperprolactinemia como la causa de la amenorrea. Nos dicen que el nivel estrogénico es bajo. En este caso debemos sospechar un fallo ovárico precoz. Para su diagnóstico solicitaremos una FSH basal (en los casos de fallo ovárico prematuro se encontraría elevada).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e57309a4c933', '6c9bcf93e7bf982bd4e35f92db1f09d7263cb9ce', NULL, NULL, NULL, false, false, 'Endocrinología', 'Un paciente de 73 años… deglución una disfagia neurológica completa, secundaria a un ictus cardioembolico en el territorio de la arteria cerebral media izquierda. va a precisar apoyo nutricional a largo plazo.', 'De las siguientes modalidades de tratamiento, ¿cual considera mas indicada para este caso?', '[{"position": 1, "text": "Nutrición enteral por sonda nasogastrica."}, {"position": 2, "text": "Nutrición enteral por sonda nasoduodenal."}, {"position": 3, "text": "Nutrición enteral por gastrostomia."}, {"position": 4, "text": "Nutrición enteral por yeyunostomia."}]'::jsonb, 4, 3, 'definitiva', 'La nutrición enteral es una técnica de soporte nutricional que consiste en administrar los nutrientes directamente en el tracto gastrointestinal mediante sonda. La lección de la vía de administración de la fórmula depende del estado nutricional, la edad del paciente y la enfermedad de base. Si se considera que la nutrición enteral es de corta duración, la vía de elección es la sonda nasogástrica o nasoduodenal-nasoyeyunal… Si se prevé una nutrición prolongada la vía de elección es la gastrostomía (opción 3), quedando la yeyunostomía reservada para casos en los que no es posible usar la vía gástrica.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-6cf0c1c2db5a', '7adb4756e2a0b0710b003ab2ea2a3f289412b298', NULL, NULL, NULL, false, false, 'Endocrinología', 'Mujer de 45 años de edad que acude al servicio de urgencias por cuadro confusional que se acompaña de disfonia. A la exploración presenta masa palpable en el cuello y en el análisis de sangre cifras de calcio plasmático de 15 mg/dL (normal hasta 10,2 mg/dL).', 'Ante estos hallazgos, ¿cual de los siguiente diagnósticos debe sospecharse?', '[{"position": 1, "text": "Carcinoma paratiroideo."}, {"position": 2, "text": "Carcinoma medular de tiroides."}, {"position": 3, "text": "MEN tipo I."}, {"position": 4, "text": "Adenoma de paratiroides."}]'::jsonb, 4, 1, 'definitiva', 'Masa palpable en el cuello: sospechar patología de tiroides/paratiroides. Nos aportan el dato de que asocia hipercalcemia, por tanto, la opción de ca. Medular de tiroides queda descartada (no afecta el nivel de calcemia). Para pensar en un MEN tipo I deberíamos asociar otras patologías (tumores hipofisarios, pancreáticos o duodenales). La presencia de una calcemia superior a 13mgr/dl, junto con la disfonía, nos orienta a tumor maligno (mayor nivel de calcemia e infiltración), decantándonos por tanto por la opción 1.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-b250c464c03f', 'f5719e958d9093a49032096cf0949431abcf7e55', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Hombre de 62 años que acude a urgencias del hospital por presentar fiebre de 38,3″C y escalofríos. Está taquicárdico y taquipnéico. Analítica de sangre: leucocitosis con desviación izquierda. La presión arterial es de 90/60 mmHg. No se escuchan soplos en la auscultación cardíaca y la RX de tórax descarta una neumonía. Como historial de interés refiere infecciones del tracto urinario de repetición. Hace una semana el médico de cabecera le recetó cefuroxima, fármaco que está tomando actualmente. Se le extraen dos hemocultivos y se remite orina para examen del sedimento y cultivo microbiológico. El sedimento es patológico, con intensa piuria, pera nitritos negativos. A las 24 horas se informa desde el laboratorio de microbiología que tanta la orina como los hemocultivos remitidos son positivos y en elias se observa cocos grampositivos agrupados en cadenas, pendientes de identificación y antibiograma.', 'A la espera del resultada definitiva, ¿qué recomendaría usted?', '[{"position": 1, "text": "Continuar con cefuroxima a la espera del resultada definitivo, pues el paciente ha llevado múltiples tratamientos y no deberíamos equivocamos en su tratamiento actual."}, {"position": 2, "text": "Cambiar a ertapenem, pensando en la posibilidad de microorganismos multirresistentes."}, {"position": 3, "text": "Cambiar a un tratamiento antimicrobiano de amplio espectro que cubra Enterococcus spp."}, {"position": 4, "text": "Cambiar a un tratamiento antimicrobiana de amplio espectro que contenga imipenem, pensando en la posibilidad de Staphylococcus aureus, ya que nuestro hospital tiene una elevada incidencia de S. aureus resistente a meticilina (SARM)."}]'::jsonb, 4, 3, 'definitiva', 'Con la prueba de nitritos en orina detectamos la presencia en la orina de nitritos. Estos aparecen por la presencia en la orina de gran concentración de bacterias que posean la enzima nitrato reductasa por la cual son capaces de reducir a nitritos los nitratos presentes en la orina. Esta enzima es activa en la mayoría de bacterias que producen infección urinaria con más frecuencia, como muchos bacilos Gram negativos. Otros microorganismos, causa relativamente frecuentes de infección urinaria, no poseen esta enzima y no reducen los nitratos como enterococos, estafilococos y levaduras. Como la tinción de Gram nos indica que las bacterias se agrupan en cadenas, al ser esto típico de enterococo, sugerimos la necesidad de cubrir con el tratamiento antibiótico a este grupo de bacterias. Los estafilococos típicamente se observan en la tinción de Gram como cocos Gram positivos formando racimos y las levaduras, aunque con igual coloración, tienen una morfología típica diferente a los cocos Gram positivos.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5164f0dc1a17', 'aa80e7aefc3a000f74420a915ea8d1e337442541', NULL, NULL, NULL, false, false, 'Pediatría', 'Niño de año y medio que acude a la Urgencia por presentar un cuadro de dolor abdominal e ictericia. En la exploración se palpa una masa abdominal. Al realizar una ecografía se observa la presencia de un quiste de colédoco.', '¿Qué actitud terapéutica adoptaremos?', '[{"position": 1, "text": "Se realizará una punción percutánea para lavado peritoneal con objeto de comprobar que el quiste contiene bilis para dejar un drenaje que mejore el cuadro de dolor abdominal."}, {"position": 2, "text": "Se indicará una laparotomía exploradora y se procederá a la resección radical de toda la vía biliar para sustituirla por un asa de intestino."}, {"position": 3, "text": "Se indicará una laparotomía exloradora para drenar el quiste y cuando remita la dilatación de retirará el drenaje."}, {"position": 4, "text": "Se realizará una colangio-resonancia para delimitar el quiste y se indicará una laparotomía para la resección de quiste y anastomosis de la vía biliar."}, {"position": 5, "text": "Es necesario un estudio gammagráfico HIDA, para delimitar el quiste y poder realizar el drenaje percutáneo con seguridad."}]'::jsonb, 5, 4, 'definitiva', 'La respuesta correcta es la 4. El quiste de colédoco es una patología congénita que suele dar clínica más allá del periodo neonatal. Lo adecuado es tener una imagen de calidad que delimite la lesión para decidir el abordaje quirúrgico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-051c87113bb7', 'a2ab052c2adcf0bf36f20e33d479ccbae2db40dd', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Mujer de 65 años, sometida a trasplante de precursores hematopoyétlcos hace 30 dias y neutropenia grave. Comienza con tos y expectoración hemoptoica además de fiebre y disnea de moderados esfuerzos que no mejora a pesar de cinco días de tratamiento con amoxicilina-clavulánico (875/125 mg/8 h) y levofloxacino (500 mg/12 h). En la radiografía de tórax se observan múltiples nódulos pulmonares mal definidos, alguna de ellos cavitado.', 'De entre los siguientes, ¿cual es el diagnóstico de sospecha más probable?', '[{"position": 1, "text": "Embolismos sépticos."}, {"position": 2, "text": "Aspergilosis pulmonar invasiva."}, {"position": 3, "text": "Neumonía por Staphylococcus aureus."}, {"position": 4, "text": "Candidiasis sistémica."}]'::jsonb, 4, 2, 'definitiva', 'Paciente en su día 30 post-transplante de precursores hematopoyéticos, en neutropenia grave que acude por tos con expectoración hemoptoica. Este cuadro usualmente se aprecia en la infección por Aspergillus spp. Podemos descartar la infección por Staphylococcus aureus por el tratamiento previo, aunque no sabemos si plantea la respuesta también un posible MRSA.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7717bf8a9586', '7fa377ec214ee35d91f2b9269ed5c48708055f65', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Hombre de 38 años que acude a urgencias por cuadro de fiebre por encima de 39ºC y deterioro del nivel de conciencia tras haber realizado un viaje a Guinea Ecuatorial sin profilaxis antimalárica. En la analitica destaca: creatinina de 3,4 mg/dL, AST 764 UlL, ALT 678 UlL. El laboratorio informa de la visualización en sangre de un Plasmodium falciparum con un nivel de parasitemia del 6%.', '¿Qué tratamiento instauraría en este momento?', '[{"position": 1, "text": "Mefloquina por vía oral."}, {"position": 2, "text": "Artesunato íntravenoso."}, {"position": 3, "text": "Doxiciclína por vía oral."}, {"position": 4, "text": "Sulfato de quinina por vía oral."}]'::jsonb, 4, 2, 'definitiva', 'En cuadro severo de infección por Plasmodium el mayor riesgo de mortalidad se produce en las primeras 24 horas de la presentación clínica por lo que se debe instaurar tratamiento inmediatamente. El tratamiento con artesunato parenteral o intramuscular es más indicado en infección severa por Plasmodium, tanto en adulto como en niño y en mujer embarazada.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-04f777122061', '2b2e6b6b82271606ca5deb46547132a213dfd070', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Hombre de 85 años portador de catéter venosa periférico que, una semana después de estar hospitalizado por un ictus, comienza con tiritona y fiebre. Se realizan hemocultivos y desde microbiología se informa que están creciendo cocos gram positivos en racimos.', 'En espera del antibiograma, ¿cual es el tratamiento antibiótico más adecuado?', '[{"position": 1, "text": "Cefazolína."}, {"position": 2, "text": "Cloxacilina."}, {"position": 3, "text": "Vancomicína."}, {"position": 4, "text": "Linezolid."}]'::jsonb, 4, 3, 'definitiva', 'La causa más frecuente de infección por catéter es una bacteria que coloniza la piel. La tinción de Gram nos dice que es un estafilococo, la mayoría de las especies de este género adquirido de forma intrahospitalaria son meticilin resistente, por lo que se consideran resistente a Cloxacilina, Cefazolina y no hay datos clínicos acerca de la eficacia de linezolid para el tratamiento de la infección sistémica relacionada con catéter. Esto, más la experiencia con el uso de vancomicina en este cuadro se considera de elección empíricamente a vancomicina.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-0e358c7c576a', 'bce01c9f4e0baaee7b0b3e2bf5a7fa91f6dfab87', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Mujer de 38 años de edad de profesión veterinaria, encargada de la vigilancia de animales salvajes y de ayudar a partos de ganado doméstico. Comienza con un cuadro de fiebre alta con escalofríos, cefalea, mialgias y tos no productiva que interpreta como un proceso gripal. Acude por presentar dolor torácico. En la radiografía de tórax se objetivan infiltrados pulmonares bilaterales en campos inferiores. Se realiza una prueba serológica con elevación de títulos de anticuerpos frente a antígenos en fase Il.', '¿CuáI de las siguientes afirmaciones es CIERTA?', '[{"position": 1, "text": "La forma de trasmisión de esta entidad es por garrapatas."}, {"position": 2, "text": "Tanto la doxiciclina como la hidroxicloroquina son eficaces para tratar las formas agudas de esta enfermedad."}, {"position": 3, "text": "En su forma aguda también presenta, generalmente, elevación de anticuerpos frente a antígenos en fase l."}, {"position": 4, "text": "La mortalidad en las formas agudas es casi inexistente."}]'::jsonb, 4, 4, 'definitiva', 'Infección aguda por Coxiella burnetii que se manifiesta en este caso por Neumonía. La infección por Coxiella no se transmite por garrapata. El contacto puede ser con alta probabilidad en el momento del parto de algún animal de granja infectado, en el que se disemina la bacteria en aerosoles. El tratamiento de elección es con doxiciclina en la fase aguda (si hay meningitis se prefieren quinolonas por la penetración de la barrera hematoencefálica). Se puede usar la combinación de doxiciclina más hicroxicloroquina, pero para la fiebre Q crónica (que es donde se observa elevación de anticuerpos contra los antígenos en fase I y conlleva mayor riesgo de mortalidad).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e74bc40ee753', '278ae0f020c54b360d6a487521d7d31bd4fd7293', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Mujer de 64 años. Menopausia a los 54 años. Dos embarazos y partos eutócicos. No toma ninguna medicación. Acude al servicio de urgencias refiriendo sangrado vaginal de dos días de duración con molestias en hipogastrio. La exploración clínica realizada por el ginecólogo no objetiva lesiones en genitales externos, vagina ni cérvix. El tacto vaginal no es concluyente.', '¿Cual de las siguientes conductas le parece mas adecuada como primera aproximación diagnóstica?', '[{"position": 1, "text": "Ecografia transvaginal y medición del espesor endometrial. En función de éste tomar biopsia endometrial o no."}, {"position": 2, "text": "Biopsia endometrial por aspiración en consulta. Con ella puedo obtener el diagnóstico muy fiablemente y es económica."}, {"position": 3, "text": "Histeroscopia con sedación y biopsia dirigida si se ve alguna lesión."}, {"position": 4, "text": "Realizaría un microlegrado, ya que es la prueba que me proporcionaría el diagnóstico definitivo."}]'::jsonb, 4, 1, 'definitiva', 'Siendo la causa más frecuente de sangrado vaginal en mujer postmenopáusica la atrofia uro-genital, no se puede descartar la existencia de una patología endometrial. Según la SEGO: «El sangrado genital anómalo es el signo principal de sospecha que nos debe llevar a descartar una patología neoplásica endometrial, en particular en pacientes postmenopáusicas, o con factores de riesgo asociados. (…) Ante el signo de sospecha la realización de una ecografía transvaginal, o en su defecto transrectal, nos permite: descartar patología orgánica (miomas, pólipos); medición del grosor endometrial en un corte longitudinal. Se recomienda utilizar un punto de corte de 3mm para la realización de biopsia endometrial en la paciente sintomática».', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5f18fcd8bfe2', '6cfcbed04491a21c2240886d506c9a74d20cbd14', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Mujer de 34 años de edad que consulta por coitorragias de repetición. Aporta una citologia con una lesión Intraepitelial de alto grado (U-SIL). Posteriormente se realiza colposcopia y biopsia sobre una zona de mosaico y la histología nos habla de un foco de carcinoma escamoso invasor de 2 mm de longitud.', '¿Qué opción terapéutica es la más adecuada para esta paciente?', '[{"position": 1, "text": "Conización."}, {"position": 2, "text": "Histerectomia total sin anexectomia."}, {"position": 3, "text": "Radioterapia pélvica con intención curativa."}, {"position": 4, "text": "Repetir una biopsia mas amplia."}]'::jsonb, 4, 1, 'definitiva', 'Según la SEGO: «Extirpar la totalidad de la lesión con el objetivo de que pueda ser evaluada histológicamente. Implica la escisión de toda la zona de transformación. En general, la escisión debe adaptarse al tamaño y características lesionales. Se distinguen 3 tipos de escisión según la presencia de componente endocervical de la lesión. Escisión tipo 1 (aplicable en casos con zona de transformación tipo 1, en los que el asa diatérmica no debe incluir canal endocervical ni superar los 8 mm de profundidad), escisión tipo 2 (indicada en zonas de transformación tipo 2, implica resecar una pequeña parte de canal endocervical visible mediante colposcopia) y escisión tipo 3 (indicada en zonas de transformación tipo 3, incluye parte de epitelio endocervical).». Cuando hablan de escisión, es sinónimo de conización; como la lesión es menor de 8mm de profundidad, éste es el tratamiento indicado.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-21ece9c4780b', '98dc071e957df4af26195be6a2046f20e4e2dcf0', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Mujer de 64 años, sin comorbilidades relevantes, intervenida de un cáncer de mama derecha mediante una tumorectomia ampliada y biopsia selectiva del ganglio centinela, con el siguiente resultado anatomopatologico: carcinoma ductal Infiltrante pobremente dlferenciado (grado 3), tamaño de 2,2 cm (pT2), receptores de estrógenos y progesterona positivo., Ki67 25%, HER2 negativo. Presenta afectación macroscópica del ganglio centinela, aunque no hay afectación del resto de ganglios axilares aislados (pN1).', '¿Qué tratamiento sistémico adyuvante considera mas adecuado para esta paciente?', '[{"position": 1, "text": "Hormonoterapia adyuvante que incluya inhibidores de aromatasa."}, {"position": 2, "text": "Quimioterapia adyuvante, preferentemente con antraciclinas y taxanos, seguida de hormonoterapia."}, {"position": 3, "text": "Quimioterapia adyuvante en asociación con el anticuerpo monoclonal trastuzumab, seguida de hormonoterapia."}, {"position": 4, "text": "Quimioterapia adyuvante, preferiblemente con antraciclinas y taxanos."}]'::jsonb, 4, 2, 'definitiva', 'Se trata de un Luminal B. Según la SEGO, esta paciente sí es candidata a tratamiento con quimioterapia por ser de alto grado histológico y elevada proliferación tumoral.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-0dce6cf3f658', 'a63e72a2d32e264eb4e2bef78571e098e0f2b81f', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Mujer de 45 años. Dos gestaciones previas con partos normales (G2PN2). Sangrado menstrual abundante desde hace aproximadamente 1 año. En ecografia se observa un mioma subseroso de 2 cm que ha permanecido estable desde hace varios años. Se realiza biopsia endometrial que resulta normal. La paciente presenta hemoglobina 10 g/dL a pesar de ferroterapia oral y la cantidad de flujo menstrual no ha disminuido a pesar de tratamiento con ácido tranexamico y acido mefenamico.', '¿Cual de los siguientes es el tratamiento de primera elección en esta paciente?', '[{"position": 1, "text": "Histerectomia total conservando anejos."}, {"position": 2, "text": "Anticonceptivos combinados orales."}, {"position": 3, "text": "Ablación endometríal."}, {"position": 4, "text": "DIU de levonorgestrel."}]'::jsonb, 4, 4, 'definitiva', 'Según la SEGO, en mujeres perimenopáusicas con sangrado menstrual abundante y/o prolongado que precisen anticoncepción, el DIU de levonorgestrel (también llamado DIU MIRENA) es la primera opción.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d02414123374', 'e581019a2448787dc70b09d34fd0ac656f718e3a', NULL, NULL, NULL, false, false, 'Nefrología', 'Hombre de 28 años de edad que acude a Urgencias del hospital por presentar hematuria macroscópica.', '¿Cuál de las siguientes alteraciones en el análisis de orina apoyaría el diagnóstico de glomerulonefritis?', '[{"position": 1, "text": "Hematíes dismórficos y/o cilindros hemáticos."}, {"position": 2, "text": "Proteinuria de 1 g/día, con resultado negativo en tira reactiva y con microalbuminuria mayor de 300 mg/24 horas."}, {"position": 3, "text": "Coexistencia de hematuria con piuria sin bacteriuria."}, {"position": 4, "text": "Coágulos en la orina a simple vista."}]'::jsonb, 4, 1, 'definitiva', 'La glomerulonefritis se asocia típicamente con hematíes dismórficos y cilindros hemáticos en el sedimento (opción 1 correcta). También puede aparecer proteinuria en rango variable, si bien no es habitual en forma de microalbuminuria aislada (opción 2 incorrecta), y hematuria con piuria aunque no es característico (opción 3 incorrecta). Los coágulos suelen aparecer en el contexto de alteraciones de la vía urinaria baja (opción 4 incorrecta).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos')
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('casimedicos-bdc60ee74cb6', 'a141e3a7a3558be86af6716a367bd5dab8dc8182', NULL, NULL, NULL, false, false, 'Nefrología', 'Hombre de 25 años sin antecedentes conocidos de interés. Lleva 2 meses con orinas espumosas y cargadas, sin otra sintomatología. Exploración física sin hallazgos. Orina elemental: pH 5; glucosa negativo; hemoglobina ++; proteínas ++; esterasa leucocitaria negativo; proteinuria 1,5 g/24 horas; Na urinario 60 mEq/L; K urinario 30 mEq/L; Cl urinario 100 mEq/L. Bioquímica sanguínea: creatinina 1,6 mg/dL; urea 80 mg/dL; Na 140 mEq/L; K 3,8 mEq/L. Estudio inmunológico: antiDNA negativo; ANCA negativo; antiMBG negativo, factor reumatoide negativo; C3 20 mg/dL (normal 60-120); C4 10 mg/dL (normal 20-40). Se realiza biopsia renal.', '¿Cuál de estos diagnósticos le parece más probable encontrar en la biopsia?', '[{"position": 1, "text": "Glomerulonefritis membranosa."}, {"position": 2, "text": "Glomerulonefritis de cambios mínimos."}, {"position": 3, "text": "Glomerulonefritis mesangial IgA."}, {"position": 4, "text": "Glomerulonefritis membranoproliferativa."}]'::jsonb, 4, 4, 'definitiva', 'Nos presentan muchos datos analíticos pero solo nos tenemos que fijar en dos: los niveles de las fracciones C3 y C4 del complemento son bajos. De las opciones que nos dan, únicamente la glomerulonefritis membranoproliferativa cursa con hipocomplementemia (opción 4 correcta).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-55a5c2995e87', 'e9a2de65dc06b798d405a50b132c80832732b490', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Mujer de 59 años con crisis epilépticas de reciente instauración que acude a urgencias. En la exploración presenta signos piramidales izquierdos y edema de papila. Se le realiza RM cerebral que muestra una masa hemisférica derecha con edema, desviación de la línea media y signos de herniación tentorial. Refiere que desde hace una semana sufre dolor de cabeza que ha ido progresando en intensidad.', '¿Cuál de las siguientes características asociadas a la cefalea le parece más probable en esta paciente?:', '[{"position": 1, "text": "Predominio matutino."}, {"position": 2, "text": "No cambia con esfuerzos."}, {"position": 3, "text": "Fotofobia."}, {"position": 4, "text": "Sonofobia."}]'::jsonb, 4, 1, 'definitiva', 'Nos describen un reciente diagnóstico de LOE cerebral con signos de hipertensión intracraneal (edema, desviación de línea media, papiledema). La cefalea asociada es típicamente matutina, al aumentar por la noche los valores de PIC.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-211c648cc302', 'b4af59221cf9147c501c761b73a28135b3ebe609', NULL, NULL, NULL, false, false, 'Pediatría', 'Niño de 28 días de vida, nacido a término. Antecedentes de embarazo y parto normales. Ha sido alimentado con lactancia materna desde el nacimiento. Consulta porque hace 8 días comenzó con vómitos, inicialmente esporádicos y desde hace 5 días, después de todas las tomas. Está permanentemente hambriento. Los vómitos son de contenido alimentario “a chorro”. El abdomen, en la palpación, es blando y depresible, sin visceromegalias. En los análisis destacaban en la gasometría pH 7,49, bicarbonato 30 mEq/l, pCO2 53 mmHg, exceso de base +8 mEq/l. Iones: Na 137 mEq/l, K 3,1 mEq/l, Cl 94 mEq/l.', 'Teniendo en cuenta el diagnóstico más probable en el cuadro clínico descrito. ¿Cuál es la prueba complementaria de elección para confirmar ese diagnóstico clínico?', '[{"position": 1, "text": "Radiografía simple de abdomen."}, {"position": 2, "text": "pHmetría."}, {"position": 3, "text": "Ecografía abdominal."}, {"position": 4, "text": "Determinación de electrolitos en sudor."}, {"position": 5, "text": "Esofagogastroscopia."}]'::jsonb, 5, 3, 'definitiva', 'La respuesta correcta es la 3. Pregunta fácil si se sospecha la patología, que también creo que es sencillo porque la descripción clínica es de libro de una estenosis hipertrófica de píloro.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4fcd1b422b9d', '1f07de99535c8a72403e0df4f27eb61287a5d1bf', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Hombre de 36 años sin AP de interés que acude al servicio de urgencias por un cuadro de aparición brusca de intenso dolor en la cara posterior del miembro inferior derecho que llega hasta el pie. En la exploración presenta: Lasège derecho positivo a 10º, disminución de la fuerza en la flexión plantar del pie derecho, hipoestesia en el borde externo del pie derecho y ausencia de reflejo aquíleo derecho. La Rx simple de columna lumbar no muestra alteraciones significativas.', '¿Cuál de los siguientes es el diagnóstico más probable?:', '[{"position": 1, "text": "Hernia discal L1/L2."}, {"position": 2, "text": "Síndrome de cola de caballo."}, {"position": 3, "text": "Hernia discal L4/L5."}, {"position": 4, "text": "Hernia discal L5/S1."}]'::jsonb, 4, 4, 'definitiva', 'Cuadro de cíatica aguda probablemente por extrusión discal. Tanto la distribución sensitiva, como la paresia para la flexión plantar (puntillas) como la ausencia de reflejo aquíleo son típicas de compromiso de la raíz S1, que se afecta típicamente con la hernia discal L5/S1 (posterolateral). Una hernia (posterolateral) L1/L2 afectaría a la raíz L2, una hernia L4/L5 a la L5 y la cola de caballo implicaría más sintomatología que una simple afectación S1.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-2e57576bf143', 'f363de0a1810b8d84f3f796681bf726c860f2fa2', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', NULL, 'En una mujer con una crisis epiléptica que presenta las siguientes características clínicas: aura epigástrica, olor desagradable, desconexión del medio, automatismos motores (chupeteo, deglución, apertura y cierre de una mano) y amnesia postcritica, ¿cual es su sospecha diagnóstica?', '[{"position": 1, "text": "Crisis generalizada no convulsiva o ausencia tipica."}, {"position": 2, "text": "Epilepsia parcial continua."}, {"position": 3, "text": "Crisis amiotónica."}, {"position": 4, "text": "Crisis parcial compleja del lóbulo temporal."}]'::jsonb, 4, 4, 'definitiva', 'Claramente la respuesta es la 4, con una clínica muy característica de crisis temporales.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d4b2bc3ec37f', '9e326fca0c345584c8c777051a3485cbc8c5de05', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Un hombre de 25 años consulta por temblor. La exploración objetiva disartria y distonia. Tiene una historia familiar de enfermedad psiquiátrica y trastornos del movimiento.', '¿Qué prueba diagnóstica considera mas acertada?', '[{"position": 1, "text": "DATS CAN."}, {"position": 2, "text": "Estudio de conducción nerviosa."}, {"position": 3, "text": "Electroencefalograma."}, {"position": 4, "text": "Cobre en orina de 24."}]'::jsonb, 4, 4, 'definitiva', 'Si hablan de un hombre joven de 20-30 años, con temblor y distonía, tenga o no antecedentes familiares, y sobre todo si una de las opciones me habla de cobre en orina, me están indicando que piense en una enfermedad de Wilson. No pienso en un Parkinson juvenil, ni en una clínica epiléptica. Por esto la respuesta correcta es la 4.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-08f57cfc7ba2', '416def80f7d1e6ff083391f744f9210a0ecfdf21', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', NULL, 'En un hombre de 70 años, hipertenso, con una hemiplejia derecha de instauración brusca con una leve disartria, sin alteraciones en la evocación ni en la comprensión del lenguaje, ¿qué tipo de ictus cree que es mas probable que haya sufrido?', '[{"position": 1, "text": "Un infarto lacunar capsular izquierdo."}, {"position": 2, "text": "Un infarto silviano cortico – subcortical fronto-temporal izquierdo."}, {"position": 3, "text": "Un infarto de tronco cerebral."}, {"position": 4, "text": "Una hemorragia lenticular izquierda."}]'::jsonb, 4, 1, 'definitiva', 'La respuesta más cercana es la 1. Si somos estrictos estaríamos hablando de un infarto lacunar motor puro (con una disartria leve). Ya que las otras 3 opciones no nos dan una clínica como la del enunciado. Tanto la opción 2 como la 3 nos dan una clínica mucho más florida y más extensa.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c0c30263b7d9', 'e80ebbf77477f1be58517149935fadb098b2e0ce', NULL, NULL, NULL, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', 'Hombre de 47 años, con antecedente de un adenoma pleomorfo parotídeo derecho, tratado con cirugía (parotidectomía extrafacial) hace 6 meses, que acude a nuestra consulta por presentar durante la masticación dolor con sudoración y enrojecimiento de la piel de la región preauricular.', '¿Qué tratamiento sería de elección?', '[{"position": 1, "text": "Parotidectomía total ampliada ante la sospecha de recidiva tumoral."}, {"position": 2, "text": "Pregabalina."}, {"position": 3, "text": "Inyección de toxina botulínica intradérmica."}, {"position": 4, "text": "Antibioterapia de amplio espectro."}]'::jsonb, 4, 3, 'definitiva', 'Este cuadro clínico se llama síndrome de Frey y consiste en una reinervación anómala de estructuras regionales tras una parotidectomía por lesión del nervio aurículotemporal, de modo que durante la masticación, se produce eritema y sudoración preauricular. El tratamiento es la inyección de toxina botulínica intradérmica.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c38f088b2f66', '66eeee2a44de5e7d759a17636c40cdf1df01221c', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Hombre de 36 años de edad sin antecedentes de interés que tras un traumatismo de alta energía al caer de una motocicleta presenta una fractura diafisaria media de tibia, abierta, grado II de Gustilo.', '¿Cuál de las siguientes maniobras o terapias es más efectiva para la prevención de la infección?', '[{"position": 1, "text": "Antibioterapia inmediata intravenosa de amplio espectro."}, {"position": 2, "text": "Desbridamiento-lavado exhaustivo de la herida en quirófano con al menos 10 litros de suero fisiológico."}, {"position": 3, "text": "Estabilización urgente de la fractura mediante fijación externa y cierre precoz de la herida."}, {"position": 4, "text": "Cierre precoz de la herida con antisépticos y oxigenoterapia a dos litros por minuto."}]'::jsonb, 4, 2, 'definitiva', 'Creo que la más correcta es la 2, ya que en las fracturas Gustilo II se cubren sobre todo Gram (+) mediante una Cefa de 1º generación, y tampoco se trata de prevenir sino de tratar (se da por contaminado).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4ca28a0c4ed5', 'd90c8b6b7d5d01850701f41d9aa23a75970cc62c', NULL, NULL, NULL, false, false, 'Oftalmología', 'Mujer de 59 años con crisis epilépticas de reciente instauración que acude a urgencias. En la exploración presenta signos piramidales izquierdos y edema de papila. Se le realiza una RM cerebral que muestra una masa hemisférica derecha con edema, desviación de la línea media y signos de herniación tentorial. refiere que desde hace una semana subre dolor de cabeza que ha ido progresando en intensidad.', '¿Cuál de las siguientes características asociadas a la cefalea le parece más probable a esta paciente?', '[{"position": 1, "text": "Predominio matutino."}, {"position": 2, "text": "No cambia con esfuerzos."}, {"position": 3, "text": "Fotofobia."}, {"position": 4, "text": "Sonofobia."}]'::jsonb, 4, 1, 'definitiva', 'Se trata de una cefalea en el contexto de un papiledema. En este caso el papiledema es debido a un aumento de presión intracraneal por un tumor. La cefalea por incremento de presión intracraneal es de tipo posicional (aumenta con las maniobras de Valsalva y al agacharse), así que la opción 2 no es correcta. Además es de predominio matutino (opción 1 correcta) porque por las mañanas de forma natural la presión intracraneal sube. Las cefaleas de tipo migraña pueden asociar fotofobia o sonofibia (respuestas 3 y 4). Pero esta cefalea no es de tipo migrañoso.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-dde48f57cd47', 'efe7769feb2d1778486b2aff896234c9911c445d', NULL, NULL, NULL, false, false, 'Oftalmología', 'Un niño de 13 años presenta un cuadro subagudo de cefalea y diplopia. La exploración neurológica muestra una parálisis de la mirada vertical y la resonancia magnética una lesión captante de contraste en la región pineal que obstruye el acueducto de silvio.', 'El diagnóstico más probable es:', '[{"position": 1, "text": "Glioblastoma."}, {"position": 2, "text": "Meduloblastoma."}, {"position": 3, "text": "Tumor de células germinales."}, {"position": 4, "text": "Meningioma."}]'::jsonb, 4, 3, 'definitiva', 'La diplopia habitualmente está causada por un estrabismo agudo o secundario. La parálisis de la mirada vertical se debe a una lesión en el mesencéfalo. En este caso la resonancia magnética ya nos sitúa el origen de los síntomas en la glándula pineal. El tumor más frecuente de esta región es el de células germinales (respuesta 3).', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d67ea61f1f9e', '1d8ca5ae745446a7756ed6f93776ef66f0f5c259', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Mujer con hipotensión e hipoperfusión tisular en la que se objetivan los siguientes parámetros tras la inserción de un catéter de Swan-Ganz: índice cardiaco 1,4 L/min/m2, presión de enclavamiento capilar pulmonar 25 mmHg y resistencias vasculares sistémicas 2000 dinas/m2.', 'El tipo de shock que presenta la paciente es:', '[{"position": 1, "text": "Cardiogénico."}, {"position": 2, "text": "Séptico."}, {"position": 3, "text": "Hipovolémico."}, {"position": 4, "text": "Anafíláctico."}]'::jsonb, 4, 1, 'definitiva', 'No nos dan más datos de la paciente salvo que se encuentra en situación de shock (hipoperfusión tisular) y al introducir un catéter de Swan-Ganz nos encontramos un índice cardíaco bajo (<2), una PCP elevada (25mmHg) y unas resistencias sistémicas elevadas (normal: 600-1200 dinas/m2). Estos datos son compatibles con origen cardiogénico del shock.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8a04d5044886', '215e57e0e4764fbff8f38c004b8f776bc0c08bad', NULL, NULL, NULL, false, false, 'Bioestadística', 'En un sujeto mayor de 65 años una prueba de tuberculina ha mostrado una induración de 3 mm. La induración en una segunda prueba, realizada 10 días después, es de 13 mm.', 'Señale la respuesta correcta:', '[{"position": 1, "text": "La primera reacción es un falso positivo."}, {"position": 2, "text": "La segunda reacción es un verdadero positivo."}, {"position": 3, "text": "La primera reacción es un verdadero negativo."}, {"position": 4, "text": "La segunda reacción es un falso positivo."}]'::jsonb, 4, 3, 'definitiva', 'Veamos, si ese sujeto no estaba dentro de ningún grupo de riesgo, el positivo está en los 15mm, por lo tanto las dos pruebas dan negativo, y como solo una respuesta refiere a negativos, ya está. Pero podrían ser las dos falsos negativos.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-cf64d7d6ff60', 'c6ed36a661dffb3127a752f917788a9035e6da96', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Un hombre de 70 años consulta por dolor lumbar no irradiado de 1 semana de duración, de intensidad progresiva, acompañado de marcada limitación de la movilidad del raquis y febrícula. La radiografía de columna lumbar no muestra alteraciones.', '¿Qué diagnóstico deberíamos descartar en primer lugar y con qué técnica?:', '[{"position": 1, "text": "Aplastamiento vertebral con tomografía computarizada (TC)."}, {"position": 2, "text": "Metástasis óseas con gammagrafía ósea con tecnecio."}, {"position": 3, "text": "Hiperostosis anquilosante vertebral con radiografía de columna dorsolumbar."}, {"position": 4, "text": "Espondilodiscitis piógena con resonancia mangética (RM)."}]'::jsonb, 4, 4, 'definitiva', 'Sospechamos una espondilodiscitis – la febrícula y la limtación de movilidad del raquis con el curso agudo dan la clave-, y la prueba indicada es la RM. “La prueba más demostrativa es la resonancia magnética (RM), que es positiva incluso en las primeras 2 semanas del cuadro, lo que facilita el diagnóstico precoz, con una sensibilidad del 90%”. EL aplastamiento vertebral se vería en la Rx simple, como también la hipertostosis anquilosante vertebral y muchas metástasis. Además, no hay datos en la historia que apunten hacia metástasis óseas (antecedentes oncológicos, pérdida ponderal etc).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f2d1a0203f0f', '9cdb962824031e3a00125b161f63ed78b16e81db', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Mujer de 93 años con antecedentes de EPOC, HTA, dislipemia, fibrilación auricular y cardiopatía isquémica. Vive sola. Presenta fracción de eyección ventricular 53%, creatinina 1,5 mg/dL, coagulación normal. Recibe tratamiento con broncodilatadores inhalados y AAS 100 mg al día. Sufre una caída en la calle, tras la cual le resulta imposible la bipedestación y sedestación, con dolor intenso en la cadera derecha a las movilizaciones, gran acortamiento y rotación externa de la pierna.', '¿Cuándo y cómo debe tratarse?', '[{"position": 1, "text": "Ingreso para ecografía transtorácica, valoración por Cardiología y después reducción cerrada y fijación con tornillo placa."}, {"position": 2, "text": "Ingreso para valoración por Nefrología y Cardiología, y después decidirá Traumatología si usa una artroplastia o un clavo trocantérico."}, {"position": 3, "text": "Ingreso en Medicina Interna / Geriatría, estabilización progresiva de las comorbilidades, tratamiento ortopédico conservador."}, {"position": 4, "text": "Reducción cerrada y fijación de la fractura antes de 48 horas, sedestación muy precoz, manejo ortogeriátrico."}]'::jsonb, 4, 4, 'definitiva', '“Actualmente se está desarrollando un nuevo enfoque para el tratamiento de estos pacientes, el cual trata de coordinar desde el principio la actividad de los diferentes sectores implicados evitando que el traslado del paciente de uno a otro se produzca al finalizar el tratamiento de cada parte. Con esta idea nacen las denominadas «unidades de ortogeriatría», que combinan la actividad quirúrgica del cirujano con la de la rehabilitación del paciente de forma inmediata y los controles y el seguimiento de medicina interna. Ya desde el inicio del proceso se pone en marcha la actividad de los asistentes sociales y las diferentes ayudas vitales y de soporte, para que la recuperación sea lo más rápida y completa posible.… En la mayoría de los casos, la intervención quirúrgica debe realizarse lo antes posible, en cuanto el enfermo esté estabilizado desde el punto de vista médico. Existe contraindicación¡ de intervenir a pacientes con comorbilidad médica inestable, pero en varios estudios se ha visto que la demora de la intervención quirúrgica más allá de 48 h tras el ingreso aumenta la mortalidad. Es por ello que el momento ideal para intervenir a estos pacientes es tras conseguir la estabilización de sus patologías médicas, procurando que esto tenga lugar antes de que transcurran 48 h.” No hay ningún dato que sugiera que tenga alguna comorbilidad inestable en el momento actual, por lo que interesa la cirugía en menos de 48 horas y el manejo ortogeriátrico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-a22c726109ba', 'ec7f9e769273d15531adad8b52a0c36aba410d74', NULL, NULL, NULL, false, false, 'Pediatría', 'Niño de un año de edad cuya madre acaba de ser diagnosticada de tuberculosis pulmonar bacilífera, habiendo iniciado tratamiento correcto. El niño está asintomático con una exploración normal, prueba de tuberculina (PT) negativa y Rx tórax normal.', '¿Cuál sería la actitud a adoptar en el niño?', '[{"position": 1, "text": "Solo separarlo de la madre hasta que ésta concluya su tratamiento (al menos 6 meses)."}, {"position": 2, "text": "Realizar una TC de alta resolución pulmonar, y si es normal, repetir la PT a las 8-12 semanas."}, {"position": 3, "text": "Quimiprofilaxis con isoniacida (INH) hasta que la baciloscopia de la madre sea negativa."}, {"position": 4, "text": "Quimioprofilaxis con INH 6-9 meses. Nueva PT y Rx tórax al finalizarlo, para decidir si concluir o no, el tratamiento."}, {"position": 5, "text": "Quimioprofilaxis con INH, 8-12 semanas. Repetir PT. Si negativa cesar el tratamiento. Si positiva, realizar Rx tórax para decidir si hay o no enfermedad."}]'::jsonb, 5, 5, 'definitiva', 'La respuesta correcta es la 5. La madre debería estar aislada durante las 2-4 primeras semanas de tratamiento, tras las cuales dejaría de ser contagiosa. Si al repetir la PT el resultado sigue siendo negativo, al niño no hay que hacerle nada más. Si es positiva, hay que repetir la radiografía (o TC pulmonar en los niños más pequeños).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-390607f92e67', '234b86d59cf56abbf44a392f8a348a9e1acc51e5', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Mujer de 65 años, obesa, que sufre una caída sobre la mano con el codo en extensión. Presenta dolor en el brazo con tumefacción e impotencia funcional del mismo y con imposibilidad para realizar la extensión de la muñeca y dedos.', 'Lo más probable es que presente:', '[{"position": 1, "text": "Fractura luxación de húmero proximal."}, {"position": 2, "text": "Luxación de codo."}, {"position": 3, "text": "Fractura diafisaria de húmero asociada a fractura doble de antebrazo."}, {"position": 4, "text": "Fractura diafisaria de húmero con lesión del nervio radial."}]'::jsonb, 4, 4, 'definitiva', 'Hay que tener en cuenta todos los datos clínicos que nos aportan: después de traumatismo tenemos dolor en el brazo con afectación de partes blandas y la imposibilidad para la extensión de muñeca y dedos. La única opción que engloba todos los datos es la 4. La 1 no explica la afectación de muñeca y dedos. La luxación de codo no explica la falta de movilidad de los dedos así como la fractura diafisaria de húmero y doble de antebrazo. “El mecanismo directo es posible, así como también lo es la transmisión indirecta de fuerzas desde el codo y la mano… la afectación del nervio radial es extremadamente frecuente, alcanzando una incidencia del 10-18% de los casos.” La fractura-luxación de húmero proximal tendría mayor afectación en el hombro, la luxación de codo en el codo, y no hay ningún dato que sugiera fractura doble del antebrazo.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9e585cbc91c0', 'b1972e540ebf08e7055842eb22373e33e1cb4419', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Un hombre de 46 años con trastorno bipolar es llevado a urgencias tras una sobreingesta de carbonato de litio. En la exploración destaca temblor intenso, ataxia, disartria, mioclonías y fasciculaciones. La litemia es de 4,1 mEq/L (toxicidad > 1,6 mEq/L).', '¿Cuál de las siguientes opciones terapéutica estaría más indicada?:', '[{"position": 1, "text": "Aminofilina asociado a un catártico."}, {"position": 2, "text": "Carbón activado."}, {"position": 3, "text": "Hemodiálisis."}, {"position": 4, "text": "Diuresis forzada."}]'::jsonb, 4, 3, 'definitiva', 'Estamos ante un caso de intoxicación grave por litio (litemia > 3,5 mEq/L amenaza la vida), por tanto, la opción terapéutica de elección es el inicio de hemodiálisis de forma urgente. Recordad que el carbón activado NO está indicado en la intoxicación por litio.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9968f003de59', 'e75c864cbb720709dd41fb5405c09c5ab3cad497', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Un hombre de 58 años, hipertenso, acude a urgencias por un síncope de 30 segundos mientras corre, con recuperación espontánea y sin secuelas. La tensión arterial es 135/65 mmHg. En la auscultación cardiaca presenta un soplo sistólico rudo, intenso, que se reduce con maniobras de Valsalva y un segundo tono atenuado. El ECG muestra un ritmo sinusal a 72 lpm, con criterios de hipertrofia ventricular izquierda y ondas T invertidas en cara anterior.', 'Señale la afirmación correcta:', '[{"position": 1, "text": "El cuadro clínico sugiere un tromboembolismo pulmonar."}, {"position": 2, "text": "Los datos aportados indican miocardiopatía hipertrófica con obstrucción grave del tracto de salida de ventrículo izquierdo."}, {"position": 3, "text": "Estos datos corresponden a estenosis aórtica grave."}, {"position": 4, "text": "Debe excluirse una disección de aorta mediante una tomografía computarizada con contraste."}]'::jsonb, 4, 3, 'definitiva', 'Los datos aportados sobre las características del soplo (DISMINUYE con el Valsalva) y los datos de hipertrofia ventricular izquierda, nos orientan al diagnóstico de estenosis aórtica grave.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9dc1b4c1c525', '424ae86f97b0d4e1b26f23ae3f8669fae1404e82', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Varón de 35 años, trasladado a urgencias tras un accidente de tráfico. A su ingreso se observa una puntuación en la escala de Glasgow de 15, tensión arterial de 140/90 mmHg, frecuencia respiratoria de 35 rpm y frecuencia cardiaca de 110 lpm, con una saturación de oxígeno basal del 91%.:', 'En la exploración hay hipofonesis torácica derecha y timpanismo a la percusión.¿Cuál es el diagnóstico de presunción?', '[{"position": 1, "text": "Taponamiento cardíaco traumático."}, {"position": 2, "text": "Neumotórax a tensión derecho."}, {"position": 3, "text": "Hemotórax masivo derecho."}, {"position": 4, "text": "Contusión pulmonar."}]'::jsonb, 4, 2, 'definitiva', 'Pregunta fácil y clásica que además podéis aplicar a la práctica clínica diaria. Hipofonesis en un hemitórax + timpanismo = neumotórax. Si hubiera matidez a la percusión: hemotórax. En cualquiera de los dos casos, ante hipofonesis de un hemitórax en un politraumatizado grave e inestable: drenaje torácico (a ser posible, de gran calibre si se coloca en medio hospitalario, puesto que aunque la lesión predominante sea el neumotórax, puede encontrarse un componente de hemotórax que en caso de colocar un drenaje fino, podría obstruir el mismo).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e0ddd1cca626', 'a83704124f85f0f3e53dfd3b232f5e0666c1f664', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Hombre de 72 años que presenta desde hace 48 horas fiebre de 38,7°C, tos, expectoración purulenta y disnea. Constantes: TA 85/60 mmHg, frecuencia cardiaca 100 lpm, frecuencia respiratoria 35 rpm, SatO2 80%. Destaca la presencia de confusión y de crepitantes en campo pulmonar inferior izquierdo. La radiografía de tórax confirma la existencia de una neumonía de la língula y del lóbulo inferior izquierdo.', '¿Cuál sería el lugar de atención adecuado?:', '[{"position": 1, "text": "Tratamiento ambulatorio en su domicilio."}, {"position": 2, "text": "Ingreso en una unidad de observación de urgencias."}, {"position": 3, "text": "Ingreso hospitalario en planta."}, {"position": 4, "text": "Ingreso en la Unidad de Cuidados Intensivos."}]'::jsonb, 4, 4, 'definitiva', 'Aplicando la escala de gravedad CURB-65 (una de las más utilizadas en urgencias para la estratificación de la gravedad de la neumonía, aunque en este caso simplemente aplicando el sentido común, el paciente debe ingresar en UCI), tendríamos una puntuación de al menos 4 puntos (nos faltaría el dato de la urea sérica), lo cual nos da criterios de gravedad. Al no darnos ningún criterio que contraindique su admisión en UCI estaría indicado el ingreso en la unidad.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-63c7ad781647', 'b576b483c303d50041fd87c838f9f74f06dae7c6', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Un paciente es traído a urgencias desde un incendio producido dentro de una nave cerrada donde había espumas de poliuretano. Está consciente, pero presenta creciente torpeza mental, cefalea e intensa disnea. La saturación de oxígeno mediante pulsoximetría es del 92% y el ácido láctico capilar es de 8 mEq/l.', '¿Qué tratamiento específico considera más adecuado?:', '[{"position": 1, "text": "Administración de oxígeno mediante mascarilla tipo Venturi al 50%."}, {"position": 2, "text": "Administración de hidroxicobalamina intravenosa."}, {"position": 3, "text": "Ventilación con cámara hiperbárica."}, {"position": 4, "text": "Fluidoterapia con infusión de solución salina fisiológica a 21 ml/h."}]'::jsonb, 4, 2, 'definitiva', 'Lo primero que tenemos que saber es que la combustión del poliuretano a alta temperatura produce la liberación de cianuro (muy intuitivo, sí). Sabiendo esto, y que nos enfrentamos a una intoxicación por cianuro, es más fácil responder la pregunta. Entre las medidas básicas de tratamiento inicial estaría la administración de oxigenoterapia con FiO2 1 (no 0.5 como se plantea en la opción 1), y un antídoto, en este caso nos plantean la hidroxicobalamina (esto se preguntó de forma similar el año pasado). La ventilación con cámara hiperbárica sólo estaría indicada en caso de que coexistiera la intoxicación por monóxido de carbono (CO). Lo que se plantea en la opción 4 acerca de la fluidoterapia no está indicado; en caso de shock asociado se administraría volumen, pero en cualquier caso no a esa velocidad, sino en bolus rápidos.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-2967e1b5ebc6', '95b7ffaa48d996846f5e8721fafecd8f6d8a5734', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Una mujer de 22 años presenta una parada cardiaca súbita con un ritmo que se considera susceptible de desfibrilación. Se están realizando compresiones torácicas y ventilaciones, se ha dado una descarga con el desfibrilador y se ha canalizado una vía venosa periférica.', '¿Cuál de las siguientes actuaciones sería correcta a continuación?:', '[{"position": 1, "text": "Administrar 150 mg de amiodarona intravenosa."}, {"position": 2, "text": "Administrar 300 mg de amiodarona intravenosa."}, {"position": 3, "text": "Administrar 1 mg de atropina intravenosa."}, {"position": 4, "text": "Administrar 2 mg de atropina intravenosa."}]'::jsonb, 4, 2, 'definitiva', 'Pregunta controvertida, puesto que la amiodarona (la dosis sí es la correcta, 300mg), se administra tras la tercera descarga, y no tras la primera desfibrilación, que es lo que nos dicen en el enunciado. Aunque, ojo, eso es lo que dicen las guías. Estoy segura de que más de uno y una hemos administrado amiodarona en cuanto hemos tenido un acceso venoso disponible en caso de ritmo desfibrilable. Las demás opciones son incorrectas.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f68db188ac51', '16779b0f6f4c438e0b716a400d96aadc977833c1', NULL, NULL, NULL, false, false, 'Dermatología', 'Hombre de 60 años en tratamiento con carbamazepina por epilepsia y que presenta fiebre (38.8º C), odinofagia, conjuntivitis, lesiones cutáneas parduzcas extendidas en una gran superficie corporal, de aspecto similar a una diana y que se acompañan de desprendimiento epidérmico (superior al 30%) al menor roce.', 'Es muy probable que esté presentando un cuadro clínico de:', '[{"position": 1, "text": "Urticaria aguda de causa farmacológica."}, {"position": 2, "text": "Eritema exudativo minor secundario a fármacos."}, {"position": 3, "text": "Síndrome de Stevens-Johnson farmacológico."}, {"position": 4, "text": "Necrolisis tóxica epidérmica."}]'::jsonb, 4, 4, 'definitiva', 'Estamos ante un paciente grave, con lesiones en diana y signo de Nikolsky en > 30% de la superficie corporal. Junto con el antecedente del tratamiento con carbamazepina la sospecha será de necrolisis epidérmica tóxica (respuesta 4). En el caso de que el despegamiento epidérmico fuera de menos del 10% entonces estaríamos ante un Stevens-Johnson (y los casos intermedios se habla de overlap, ya que es todo un espectro). Por cierto, recomendaremos ingreso inmediato en una Unidad de Grandes Quemados.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-6333c1a18040', 'cd516520ce6e05aa9fed8d94faa8895fbe5beae8', NULL, NULL, NULL, false, false, 'Genética e Inmunología', 'Señale la respuesta correcta:', '¿Qué consejo genético y reproductivo indicaría a una mujer de 30 años que consulta por ser portadora de una premutación en el gen FMR1, responsable del síndrome del cromosoma X frágil, y que desea tener descendencia?.', '[{"position": 1, "text": "Todos sus hijos varones serán portadores y, por tanto, manifestarán la enfermedad."}, {"position": 2, "text": "Existe un fenómeno de anticipación genética, por lo que su descendencia presentará síntomas más graves y más precoces."}, {"position": 3, "text": "El diagnóstico genético preimplantacional para la selección de sexo de los embriones mediante hibridación in situ fluorescente (FISH) es la mejor opción para tener descendencia sana."}, {"position": 4, "text": "El 50% de sus hijas serán portadoras, pero no presentarán manifestaciones clínicas de la enfermedad."}]'::jsonb, 4, 2, 'definitiva', 'Otro clásico del MIR, preguntado en 2019 y en 2017, el síndrrome de X-frágil. Además, sobre el mismo concepto de la pregunta 44, el fenómeno de anticipación genética. Las enfermedades por expansión de tripletes, como ésta, puede presentar el fenómeno de anticipación por el que mujeres con premutaciones (entre 55-200 repeticiones) pueden tener hijos con mutaciones completas (más de 200 repeticiones del triplete) y clínica más evidente, más grave y/o más precoz, tanto en hombres como en mujeres (síndrome de X-frágil, fallo ovárico precoz, temblor/ataxia asociado al X-frágil).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-b91b7d2328db', '30e927e3d628461b9e7dba453c654221c6085b77', NULL, NULL, NULL, false, false, 'Hematología', 'Paciente de 67 años que en los últimos 6 meses, en dos analíticas de rutina, presenta linfocitosis progresiva. En la última, hemoglobina 15,4 g/dl; leucocitos 18,5 x103/μL con 82% de linfocitos maduros que por citometría de flujo expresan los antígenos CD5/CD19/CD23 y plaquetas 240 x103/μL.', '¿Qué actitud le parece correcta?:', '[{"position": 1, "text": "Estudio de mutaciones de TP53 para establecer el pronóstico."}, {"position": 2, "text": "Aspirado/biopsia ósea para confirmar el diagnóstico."}, {"position": 3, "text": "PET/CT para establecer la actitud terapéutica."}, {"position": 4, "text": "Nuevo control clínico y analítico en 6 meses."}]'::jsonb, 4, 4, 'definitiva', 'Pregunta que creo que puede ser complicada para un opositor MIR. Nos hablan de una leucocitosis a expensas de linfocitos con fenotipo de LLC-B. Parece que no hay otros datos de alarma. No nos dan datos de clínica (así que suponemos que el paciente está asintomático). No hay citopenias… Conclusión: SEGUIMIENTO. La principal duda con la respuesta debería ser con la opción 1. ¿Por qué considero que es incorrecta? Porque la mutación TP53, aunque establece pronóstico, no está indicada hacerla al diagnóstico, sino cuando se va a iniciar tratamiento (en primera línea y previo a sucesivas líneas en caso de necesitarlas). Se podría rizar mucho el rizo en esta pregunta en la que el porcentaje que nos da, no se refiere directamente a linfocitos clonales, con lo que incluso podría tratarse de una linfocitosis B monoclonal. Pero esto es excedernos.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-41739b008dc4', '2272c9dfe74016c1a6755739062632134d47320c', NULL, NULL, NULL, false, false, 'Pediatría', 'Un niño de 10 años es traído a Urgencias porque desde hace 2 horas se le gira involuntariamente el cuello a la derecha asociado a marcado dolor cervical en cada giro.', 'La abuela, posteriormente, nos dice que está vomitando desde ayer, por lo que le dio un jarabe; ¿cuál sería la actitud terapéutica más acertada?', '[{"position": 1, "text": "Inyectar un anticolinérgico endovenoso."}, {"position": 2, "text": "No tratar hasta no realizar en los días próximos un electroencefalograma."}, {"position": 3, "text": "No tratar hasta no saber en días próximos el resultado del cultivo del líquido cefalorraquídeo."}, {"position": 4, "text": "Llamar al psiquiatra de guardia."}, {"position": 5, "text": "Poner un antibiótico intravenoso tras obtener muestra del exudado faríngeo."}]'::jsonb, 5, 1, 'definitiva', 'La respuesta correcta es la 1. El anticolinérgico se puede administrar por vía endovenosa y también intramuscular si no me equivoco. La aparición de la distonía como efecto secundario es frecuente en niños y es uno de los principales motivos por los que los pediatras no solemos recetar algunos antieméticos en los niños.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8a26b6738df9', '6c3e30830fe62c65b48dc7ad2f696496969884d6', NULL, NULL, NULL, false, false, 'Hematología', 'Mujer de 65 años derivada a urgencias por fiebre y alteraciones en la analítica: Hemoglobina 11,4 g/dL, leucocitos 0,86 x103/μL,(neutrófilos 41,9%, linfocitos 55,8%),plaquetas 48,0 x103/μL, fibrinógeno 118 mg/dL,dímero D 20,2 μg/mL. Se realiza examen de médula ósea con la que se le diagnostica una leucemia aguda con t(15;17) en el 60% de lascélulas.', '¿Cuál de las siguientes respuestas es correcta?:', '[{"position": 1, "text": "Si está asintomática se iniciará ácido transretinoico (ATRA) y se recomendarán controles en hospital de día."}, {"position": 2, "text": "Se iniciará tratamiento con trióxido de arsénico, ATRA y terapia de soporte."}, {"position": 3, "text": "Es una leucemia mieloblástica tipo M3, por lo que se iniciara tratamiento quimioterápico y heparina para controlar la coagulación intravascular diseminada."}, {"position": 4, "text": "Se debe iniciar tratamiento antibiótico. Cuando desaparezca la fiebre se iniciará el tratamiento de la leucemia."}]'::jsonb, 4, 2, 'definitiva', 'Se trata de una leucemia promielocítica definitoria con la t(15;17), y como es bien sabido por todos vosotros el tratamiento es con trióxido de arsénico + ATRA. La opción 1 queda incompleto el tratamiento solo hay ATRA y hay que tratarla siempre que las condiciones del enfermo lo permitan, haya o no síntomas. La opción 3 hace 3 años sería la opción correcta pero hoy en dia ni se trata con quimioterapia ni se pone heparina. Y la opción 4 es falsa porque esa fiebre se debe a la propia leucemia y lo prioritario es iniciar el tratamiento específico de la leucemia.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-dfb480ca51ef', 'd44fd73b8de5d95a3edb5fefc917a33fa7ca922f', NULL, NULL, NULL, false, false, 'Hematología', 'Paciente de 18 años que acude a urgencias con epistaxis de varios días de evolución, sin antecedentes personales ni familiares de interés. En la exploración está afebril, se observan equimosis múltiples, no se palpa esplenomegalia. Analítica: Leucocitos 7,2 x103/μL, Hb 12,3 g/dL, Plaquetas 6,0 x103/μL. La trombocitopenia se confirma en el frotis, donde se observan plaquetas de tamaño aumentado. Estudio de coagulación y bioquímica normales.', '¿Cuál considera el diagnóstico más probable?:', '[{"position": 1, "text": "Púrpura trombótica trombocitopénica."}, {"position": 2, "text": "Coagulación intravascular diseminada."}, {"position": 3, "text": "Trombocitopenia inducida por infección."}, {"position": 4, "text": "Trombocitopenia inmune primaria."}]'::jsonb, 4, 4, 'definitiva', 'Se trata de un caso clínico fácil sólo presenta trombopenia con clínica, petequias y epistaxis. La 1 es falsa, hablarían de fiebre, datos de hemólisis, clínica neurológica, en el frotis habría esquistocitos. En la 2 debe estar alterada la coagulación y en este caso no se nombra.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-ce612cc0e765', 'de3ef54142d6d71272988b32aa68e540cf023c6b', NULL, NULL, NULL, false, false, 'Oncología', 'Mujer de 65 años sin comorbilidades, operada de cirugía conservadora de mama izquierda con biopsia selectiva del ganglio centinela. La anatomía patológica de la pieza muestra un carcinoma ductal infiltrante grado III de 11 mm, dos ganglios centinelas negativos, receptores de estrógenos: 0%, receptores de progesterona: 0%, Ki 67: 70%, HER2: negativo. El estudio de extensión es negativo.', 'El tratamiento adyuvante sería:', '[{"position": 1, "text": "Quimioterapia basada en antraciclinas y taxanos, radioterapia y trastuzumab."}, {"position": 2, "text": "Quimioterapia basada en antraciclinas y taxanos, radioterapia y tamoxifeno."}, {"position": 3, "text": "Quimioterapia basada en antraciclinas y taxanos, y radioterapia."}, {"position": 4, "text": "Quimioterapia basada en antraciclinas y taxanos, radioterapia e inhibidores de la aromatasa, dado que es postmenopáusica."}]'::jsonb, 4, 3, 'definitiva', 'Pregunta típica, cirugía conservadora implica radiar, seguro. Alto grado, y no tiene receptores hormonales ni her2 (la temida triple negativa). Yo estuve cuando no había ni taxanos ni herceptin y estuve en los ensayos que demostraron que se curan cada vez más, por desgracia aún no todas. Por eso hoy en día, antraciclinas (no sufre del corazón) y taxanos antes de la RT. Mi especialidad es bonita, y lo será más en los próximos años.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-94645307bd7e', '16356d3bbfa2d582dbe6f16161d9ef8a68f2d662', NULL, NULL, NULL, false, false, 'Oncología', 'Paciente de 40 años, con exploración física normal, en el que se ha puesto en evidencia en la tomografía computarizada una masa mediastínica y un nódulo hepático, y en la analítica una elevación sérica de lácticodeshidrogenasa (LDH), betagonadotropina coriónica humana (beta-GCH) y alfafetoproteína.', '¿Cuál es su sospecha diagnóstica?:', '[{"position": 1, "text": "Hepatocarcinoma metastásico."}, {"position": 2, "text": "Seminoma extragonadal metastásico."}, {"position": 3, "text": "Linfoma mediastínico."}, {"position": 4, "text": "Cáncer de células germinales no seminomatoso extragonadal metastásico."}]'::jsonb, 4, 4, 'definitiva', 'Muy típica también. En urgencias se puede diagnosticar con un test de embarazo (en varones), porque detecta esa HCG beta en orina. El hepatocarcinoma puede elevar (solo) alfafeto, el seminoma LDH, el linfoma también LDH.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-a2461b788af8', '2a871a84378d4d16b8155bbbccf361ec9fef5002', NULL, NULL, NULL, false, false, 'Oncología', 'Hombre de 60 años, fumador de 40 paquetes/año, que consulta por dolor en borde cubital del brazo izquierdo y ptosis palpebral izquierda desde hace un mes. La radiografía de tórax muestra una masa en el lóbulo superior izquierdo y la TC confirma la lesión con invasión de la segunda costilla.', 'En relación con el diagnóstico de sospecha, el tratamiento más adecuado es:', '[{"position": 1, "text": "Quimioterapia neoadyuvante con quimiorradioterapia combinada, seguida de cirugía."}, {"position": 2, "text": "Quimioterapia neoadyuvante sin cirugía, seguida de radioterapia."}, {"position": 3, "text": "Cirugía seguida de quimiorradioterapia combinada."}, {"position": 4, "text": "Radioterapia sin quimioterapia, seguida de cirugía."}]'::jsonb, 4, 1, 'definitiva', 'Pancoast típico de fumador, probablemente un epidermoide, con sdr de Horner. Lo mejor sería quimiorradio seguido de rescate quirúrgico. Antiguamente era solo RT y cirugía. Quizá no muy lejos entre la inmunoterapia en primera línea. Cada vez hay más cosas nuevas.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7dd51aa5d7db', '6df71881332e4acb953d8b420ad091f97a7792f5', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Un hombre presenta se forma brusca astenia e ictericia detectándose unas transaminasas superiores a 2000 UI/L Los marcadores serológicos muestran el siguiente patrón: Anti VHA IgM negativo, HBsAg negativo AntiHBc IgM positivo, anti VHC negativo.', '¿Cuál es el diagnóstico?', '[{"position": 1, "text": "Hepatitis crónica B."}, {"position": 2, "text": "Hepatitis aguda no viral."}, {"position": 3, "text": "Hepatitis aguda B."}, {"position": 4, "text": "Sobreinfección por virus D (delta)."}, {"position": 5, "text": "Hepatitis aguda A y B."}]'::jsonb, 5, 3, 'definitiva', 'Una interesante de algo que en general hay que estudiarse. Por la forma de presentación, es claramente una hepatitis aguda con lo que la 1 se descarta. La IgM de VHA negativa descarta la 5 y el HBs Ag negativo la 4 (para tener virus delta necesitas antígeno de superficie B). Al tener IgM anti HBc hablamos de una hepatitis aguda B (3), ya que hay un periodo ventana de negativización del antígeno.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-09350868902f', 'ec7bbc8fca60b2f3eb1e52041df32773af39d6a6', NULL, NULL, NULL, false, false, 'Pediatría', 'Mujer de 15 años que presenta un retraso en la menarquia y una talla baja. No tiene discapacidad intelectual.', '¿Cuál de las siguientes pruebas genéticas se utilizaría habitualmente para el diagnóstico de esta paciente?:', '[{"position": 1, "text": "Secuenciación masiva (NGS)."}, {"position": 2, "text": "FISH."}, {"position": 3, "text": "Microarrays de ADN y/o de ARN."}, {"position": 4, "text": "Cariotipo."}]'::jsonb, 4, 4, 'definitiva', 'En una mujer con pubertad retrasada y talla baja debemos pensar y descartar siempre el Síndrome de Turner, cuyo diagnóstico se realiza mediante cariotipo (45X0).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-53a691c162d6', '474c439af6c570b5935f24969f840af5fdc66c6d', NULL, NULL, NULL, false, false, 'Pediatría', 'Niño de 5 años diagnosticado de insuficiencia renal crónica. Acude a urgencias por vómitos, malestar general y palpitaciones. Se realiza un electrocardiograma donde destaca elevación de ondas T y analítica sanguínea con niveles de potasio de 5,9 mEq/L. Se decide la administración inmediata de gluconato cálcico.', '¿Cuál es el objetivo de este tratamiento?:', '[{"position": 1, "text": "Favorecer el desplazamiento de potasio desde el espacio plasmático al espacio intracelular."}, {"position": 2, "text": "Quelar el potasio circulante para favorecer su eliminación hepática."}, {"position": 3, "text": "Quelar el potasio circulante para favorecer su eliminación renal."}, {"position": 4, "text": "Antagonizar la acción del potasio sobre la membrana de la célula miocárdica."}]'::jsonb, 4, 4, 'definitiva', 'El gluconato cálcico no tiene efecto sobre los niveles de potasio en sangre (por tanto se descartan las opciones 1, 2 y 3). Su función es disminuir la excitabilidad de los miocitos cardiacos para disminuir la probabilidad de desarrollar trastornos del ritmo cardíaco.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-a4c7d943dd63', '216def21b0edc0397a67b491c172d98d3a8af6b2', NULL, NULL, NULL, false, false, 'Pediatría', 'Niño de 8 años que consulta por la aparición de vello púbico en la base del pene desde hace 12 meses. El testículo no ha aumentado de volumen y el pene no ha aumentado de tamaño. No se aprecia un aumento de la velocidad de crecimiento en el último año. La edad ósea es un año mayor que la cronológica.', '¿Cuál sería el diagnóstico más probable?:', '[{"position": 1, "text": "Pubertad precoz central."}, {"position": 2, "text": "Pubertad precoz periférica."}, {"position": 3, "text": "Adrenarquia precoz."}, {"position": 4, "text": "Tumor suprarrenal."}]'::jsonb, 4, 3, 'definitiva', 'En el varón, se considera normal la aparición de pubarquia a partir de los 9 años de edad, por tanto en este caso es una pubarquia prematura. El comienzo de pubertad se define como aumento de volumen testicular (mayor o igual a 4cc); al especificarnos que el tamaño testicular no ha aumentado, podemos descartar la opción 1 y 2. La secreción excesiva de andrógenos que produce un tumor suprarrenal originaría mayor cantidad de vello y aumento de tamaño peneano, que nuestro paciente no presenta. Por tanto, la opción correcta es adrenarquia precoz.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c8706a05ffb0', 'c134927a25ec258c8c2a72ef0c53d214ca8865bb', NULL, NULL, NULL, false, false, 'Psiquiatría', 'Un paciente de 79 años es traído a urgencias a las 7 de la tarde desde una residencia, pero no disponemos del informe de derivación y por tanto desconocemos sus antecedentes. Está desorientado en tiempo y espacio. Tiene problemas para recordar información sencilla. En ocasiones se pone muy nervioso y agitado, porque ve personas amenazantes, incluso cuando se encuentra a solas. En otras ocasiones aparece somnoliento y desatento.', 'El principal dato que apoya el diagnóstico de delirium frente al de demencia es:', '[{"position": 1, "text": "La presencia de alucinaciones visuales."}, {"position": 2, "text": "Los síntomas cognitivos."}, {"position": 3, "text": "La agitación psicomotriz."}, {"position": 4, "text": "La fluctuación del nivel de alerta."}]'::jsonb, 4, 4, 'definitiva', 'Poco que comentar… es la definición de delirium. Alteración del estado de conciencia.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-32875c49cdde', 'c0b27a312e4d5a5037bff7c709dd44c78d2aa4e6', NULL, NULL, NULL, false, false, 'Psiquiatría', NULL, 'Ante un trastorno obsesivo-compulsivo (TOC) de inicio súbito en un niño de 9 años que además presenta tics y corea como manifestaciones neurológicas se debería descartar una infección por:', '[{"position": 1, "text": "Estreptococo viridans."}, {"position": 2, "text": "Estreptococo alfa-hemolítico."}, {"position": 3, "text": "Estreptococo beta-hemolítico, grupo A."}, {"position": 4, "text": "Enterococo."}]'::jsonb, 4, 3, 'definitiva', 'Hay numerosa bibliografía al respecto. No dejan de asombrarnos los extraños caminos de la biología y que el axioma “la más larga es la correcta” se cumpla en este caso.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8de88c58c92a', '024766e85f44d53aafde8b8655a65b340f6298e6', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Varón de 83 años que consulta por un cuadro recurrente de dolor abdominal en fosa iliaca izquierda, acompañado de diarrea de hasta 6 deposiciones al día sin productos patológicos, de 10-15 días de evolución. No refiere fiebre ni afectación del estado general. En una analítica reciente no se observa leucocitosis y presenta una sangre oculta en heces negativa. En la exploración se observa leve dolor a la palpación de fosa iliaca izquierda sin irritación peritoneal. Tiene realizada una colonoscopia hace tres años en la que se informa de divertículos a lo largo de todo el colon, más numerosos en colon izquierdo, sin otras lesiones asociadas.', 'De las siguientes, ¿cuál sería la mejor actitud a seguir?:', '[{"position": 1, "text": "Realizar un tratamiento empírico con antibióticos."}, {"position": 2, "text": "Solicitar una colonoscopia preferente."}, {"position": 3, "text": "Solicitar una ecografía abdominal urgente."}, {"position": 4, "text": "Derivar a cirugía para valorar sigmoidectomía."}]'::jsonb, 4, 1, 'definitiva', 'Hacen referencia a un concepto que ha surgido hace relativamente poco y que no está presente en todas las guías clínicas como es la enfermedad diverticular sintomática no complicada. En estos casos, se recomienda el ensayo terapéutico con rifaximina, siendo la verdadera la número 1. La ausencia de reactantes de fase aguda en la analítica nos orienta a que no presenta una diverticulitis aguda en el momento de la consulta que nos haga solicitar una prueba de imagen para descartarla.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-3cc2cc8d9e22', '0cfe8e6dd9f4379526692640a36599f519446efc', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Varón de 43 años sin antecedentes de interés que consulta por un cuadro de diez días de evolución de ictericia de piel y mucosas, coluria y acolia. No refiere dolor abdominal, pérdida de peso ni otra clínica, salvo prurito generalizado. Niega consumo de alcohol. No toma medicación salvo ibuprofeno ocasional por dolores musculares tras actividad deportiva. La analítica muestra una bilirrubina aumentada a expensas de directa. Una ecografía urgente muestra un hígado normal, colesterolosis vesicular y ausencia de dilatación de vía biliar, sin otras alteraciones de interés.', '¿Cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Colangitis aguda por barro biliar."}, {"position": 2, "text": "Hepatitis tóxica por ibuprofeno."}, {"position": 3, "text": "Colangiocarcinoma."}, {"position": 4, "text": "Síndrome de Gilbert."}]'::jsonb, 4, 2, 'definitiva', 'Creemos que esta pregunta es impugnable. La hepatitis por ibuprofeno es un efecto adverso raro con una prevalencia de alrededor 3.7/100.000 usuarios y de 1.1/100.000 prescripciones. Parece que puede estar relacionado con la dosis y con la duración del tratamiento, pero existe poca evidencia sobre ello. Dentro de los AINEs que mayor riesgo presentan están el diclofenaco y el sulindac. Atendiendo a términos de frecuencia, la prevalencia de colangiocarcinoma es de 2/100.000 pacientes, siendo una frecuencia muy equiparable. La ausencia de dilatación de la vía biliar en colangiocarcinomas puede verse en casos de colangiocarcinomas intrahepáticos o en aquellos con histología mixta con hepatocarcinoma. Es cierto que el curso agudo y la ausencia de síndrome constitucional puede hacernos pensar en contra de esta opción e inclinar la balanza hacia la hepatitis por ibuprofeno. Respecto a las otras opciones: una colangitis aguda se caracteriza por la tríada ictericia, dolor abdominal y fiebre; el síndrome de Gilbert es un aumento de bilirrubina a expensas de indirecta.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-56a71c2ecfab', 'ae513310fe0b5424c665d168184593fff7194871', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Mujer de 79 años hipertensa en tratamiento con olmesartán que acude a consulta por diarrea acuosa de 4 a 6 deposiciones al día desde hace dos meses. Hace tres meses recibió tratamiento con antiinflamatorios no esteroideos durante 3 semanas por lumbociática. Se realizó gastroscopia y colonoscopia, ambas sin alteraciones macroscópicas. Las biopsias duodenales fueron normales, mientras que en las biopsias de colon se observa un infiltrado inflamatorio crónico de la lámina propia con una banda irregular de colágeno inmediatamente por debajo del epitelio de superficie de la mucosa con un grosor mayor a 10 mm y un número de linfocitos intraepiteliales >20 por cada 100 células epiteliales.', '¿Cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Colitis microscópica."}, {"position": 2, "text": "Enteropatía por AINEs."}, {"position": 3, "text": "Enteropatía asociada a olmesartán."}, {"position": 4, "text": "Síndrome de intestino irritable."}]'::jsonb, 4, 1, 'definitiva', 'Los criterios diagnósticos de la colitis microscópica son: a)Diarrea acuosa sin sangre, crónica o intermitenteb)Mucosa de colon valorada por colonoscopia macroscópicamente normal o casi normal c)Hallazgos histopatológicos característicos. En nuestro caso, la paciente presenta hallazgos compatibles con colitis colágena (banda de colágeno subyacente al epitelio mayor de 10 micras) y linfocítica (más de 20 linfocitos intraepiteliales). El tratamiento de esta patología son corticoides tópicos con baja biodisponibilidad oral (budesonida principalmente). La enteropatía por olmesartán produce un cuadro similar a la celiaquía y se caracteriza por biopsia duodenal con atrofia vellositaria, inflamación mucosa con incremento de linfocitos intraepiteliales y criptitis. En este caso nos describen una biopsia duodenal normal, pero sería interesante quedarnos con el concepto de cara a futuros exámenes.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8e96797357fd', 'b46bf29be92c313bfb46338b5c02cb13077164f8', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Paciente de 72 años de edad que acude a urgencias por presentar aparatoso e importante angioedema lingual. No presenta urticaria asociada ni refiere antecedentes de alergia a fármacos o alimentos. Entre sus antecedentes personales destacan diabetes mellitus tipo 2, dislipemia, hipertensión arterial, hipotiroidismo y enfermedad de Parkinson. En tratamiento habitual con metformina, simvastatina, enalapril, tiroxina y levodopa.', '¿Cuál de los siguientes fármacos es con mayor probabilidad el fármaco causal del cuadro clínico descrito?:', '[{"position": 1, "text": "Enalapril."}, {"position": 2, "text": "Simvastatina."}, {"position": 3, "text": "Metformina o levodopa por igual."}, {"position": 4, "text": "Levodopa."}]'::jsonb, 4, 1, 'definitiva', 'De los fármacos propuestos, las opciones menos probables serían la 3, ya que la metformina muy raramente causa angioedema lingual (en marzo de 2020 sólo había un caso descrito en todo el mundo) y la 4, ya que, entre las reacciones adversas de la levodopa, el angioedema se clasifica entre las muy raras (frecuencia menor al 0,1%). De las dos opciones que quedan, los fármacos que con más frecuencia y más clásicamente se han asociado a angioedema lingual son los IECAs (frecuencia en torno al 0.2%), siendo su relación con la simvastatina también menor al 0.1%.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-153cb9c54d75', 'fd8fc23978003a3dc5ab6289d1a281fb0d0450a4', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Tras un accidente de tráfico usted atiende a un herido. El paciente abre los ojos a la llamada, pero únicamente emite palabras que son inapropiadas. En la exploración motora localiza el dolor en extremidades derechas, pero extiende al estimular las extremidades izquierdas.', '¿Cómo describiría su situación según la escala de coma de Glasgow?:', '[{"position": 1, "text": "E3V2M4."}, {"position": 2, "text": "E3V3M5."}, {"position": 3, "text": "E2V3M4."}, {"position": 4, "text": "E2V4M5."}]'::jsonb, 4, 2, 'definitiva', 'Lo primero que debemos saber al aplicar la escala de coma de Glasgow en un paciente es que siempre debemos quedarnos con el mejor valor en cada esfera (respuesta ocular, respuesta motora y respuesta verbal). En este caso, tenemos un paciente que tiene apertura ocular a la llamada (respuesta ocular 3 sobre 4), emite palabras inapropiadas (respuesta verbal 3 sobre 5) y localiza al dolor con extremidades derechas (respuesta motora 5 sobre 6). La puntuación en la escala de coma de Glasgow sería de 11 (sobre 15). Se toma el mejor valor de la exploración porque en muchos casos (valoración de paciente politraumatizado, ictus isquémico o sangrado cerebral agudo espontáneo), la exploración motora puede estar artefactada por otros elementos. Por ejemplo: en un paciente politraumatizado (como el que nos atañe), la respuesta que presenta con extremidades izquierdas puede ser debida a traumatismo localizado en dicha zona, y no propiamente a una lesión cerebral traumática subyacente. Igualmente, en ocasiones se puede infraestimar la respuesta verbal en el paciente politraumatizado por obstrucción de la vía aérea (por ejemplo, por retroceso de la lengua hacia la orofaringe). Al valorar siempre la mejor respuesta, tendremos una visión más real del estado del paciente.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e3b856f8f392', 'de794109f8d37468b44cf2200f13a6e029248674', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Varón de 15 años de edad, ingresado tras haber sido atropellado en la vía pública, resultando despedido. Ingresa consciente y orientado, con intenso dolor en hemitórax izquierdo y disnea. En la exploración física se halla tensión arterial 90/60 mmHg, frecuencia cardiaca 130 lpm, saturación basal de oxígeno 90%, frecuencia respiratoria 35 rpm. Hay hipofonesis completa en el hemitórax izquierdo y matidez a la percusión. En la radiografía de tórax se ven múltiples fracturas costales izquierdas y derrame pleural ipsilateral masivo. Se indica la colocación de un drenaje pleural, con salida de 1700 cc de líquido hemático.', '¿Cuál es la decisión que se debe tomar?:', '[{"position": 1, "text": "Instaurar ventilación mecánica no invasiva y solicitar transfusión sanguínea."}, {"position": 2, "text": "Analgesia, oxigenoterapia, solicitar transfusión sanguínea e indicar una intervención quirúrgica urgente."}, {"position": 3, "text": "Intubación orotraqueal, solicitar transfusión sanguínea y observación para, en caso de empeoramiento, indicar la intervención quirúrgica."}, {"position": 4, "text": "Intubación orotraqueal y realización de una TC urgente para valoración exacta de las lesiones."}]'::jsonb, 4, 2, 'definitiva', 'Hay dos respuestas que podemos descartar inmediatamente si nos atenemos al manejo inicial del traumatismo torácico grave: la 1 (la ventilación no invasiva no está indicada porque no asegura la vía aérea) y la 3 (la observación en estos casos, esperando el empeoramiento, sólo conlleva un aumento de la morbimortalidad). Entre la opción 2 y la 4 podría haber controversia entre la literatura y la práctica clínica habitual, en la que normalmente tenemos que enfrentar en un delicado equilibrio la estabilidad clínica del paciente (y lo que podemos llegar a “maquillar” dicha estabilidad con nuestras terapias de soporte vital) y las actuaciones que deriven en una mejor atención al paciente para el tratamiento definitivo de las lesiones. Nos encontramos ante un paciente politraumatizado grave. Con los datos que nos aporta la pregunta, un paciente que impresiona de encontrarse en shock (taquicardia, hipoxemia, taquipnea… aunque no nos dan datos, por ejemplo, de lactacidemia), y en el que tenemos hasta donde sabemos un traumatismo torácico izquierdo, que no sólo implica lesión ósea, sino que puede enmascarar otras lesiones de elevada gravedad y que no se diagnostican con una radiografía de tórax: contusión miocárdica, derrame pericárdico, lesión esplénica, lesión diafragmática… Al paciente le colocamos un drenaje pleural izquierdo y obtenemos un débito de 1700cc de líquido hemático. Si seguimos las guías de atención al politraumatizado grave de la ATLS (ATLS-Advanced Trauma Life Support 10th edition), nos dicen que un sangrado inmediato de más de 1500cc de sangre, es indicación de toracotomía urgente, y que incluso en pacientes con un sangrado menor a 1500cc, si el débito persiste a razón de 200mL/h durante 2 a 4h, igualmente existiría esta indicación. Por tanto, el que ha hecho la pregunta del MIR quiere que respondamos la opción 2. Ahora bien, en la vida real, la pauta de actuación va a depender de la estabilidad del paciente cuando hayamos aplicado los tratamientos que se indican en la opción 2: adecuada analgesia, oxigenoterapia e inicio de trasfusión sanguínea. Si optimizando al paciente conseguimos estabilizarlo y valoramos que es seguro trasladarlo, la realización de un bodyTC va a definir con muchísimo más detalle las lesiones que tiene, y va a ayudar a que la cirugía a la que probablemente se acabe sometiendo, sea una cirugía definitiva y no únicamente cirugía de control de daños. En este caso, surgiría la duda con la opción 4, aunque, como digo, todo dependerá de la estabilidad clínica del paciente y el tiempo que tengamos antes de conseguir el control definitivo del foco hemorrágico (que es, al fin y al cabo, lo que perseguimos en esta situación).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-3a20afee46b2', '0b54767cb158abc44cc22f62d611aae19f69a954', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Un paciente de 56 años es encontrado en coma en su domicilio. Tiene antecedentes de hipertensión arterial y diabetes mellitus. No tiene hábitos tóxicos ni ninguna otra enfermedad crónica. Está en tratamiento con irbesartan y empaglifozina. No presenta signos de desnutrición. Presenta una presión arterial de 110/60 mmHg, una frecuencia cardiaca de 110 lpm, una SatO2 del 90%, una glucosa capilar de 120 mg/dl y una frecuencia respiratoria de 7 rpm.', '¿Qué actitud terapéutica inicial le parece la más correcta?:', '[{"position": 1, "text": "Administrar naloxona, flumazenilo y tiamina."}, {"position": 2, "text": "Administrar naloxona, flumazenilo y glucosa hipertónica."}, {"position": 3, "text": "Administrar naloxona y flumazenilo."}, {"position": 4, "text": "Administrar tiamina y glucosa hipertónica."}]'::jsonb, 4, 3, 'definitiva', 'Nos encontramos un paciente con hipoventilación. La glucemia es correcta (descartamos coma hiperosmolar e hipoglucemia, opción 2 y 4), por lo que, aunque no tenga antecedentes de consumo de tóxicos, tenemos que ir a lo más frecuente y que podemos antagonizar con antídotos: benzodiacepinas (flumazenilo) y opiáceos (naloxona). Si la sospecha fuera de intoxación por etilenglicol, administraríamos tiamina, pero no nos dan datos que nos haga sospechar.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-752b4feb3bcb', 'af7d19b3db75aa87b2757a38ba801f6c27375853', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Un varón de 34 años sufre un accidente de tráfico y es atendido en el lugar del accidente. El personal sanitario objetiva que está pálido, sudoroso, tiene pulso filiforme con una presión arterial de 90/50 mmHg, una frecuencia cardiaca de 127 lpm, una frecuencia respiratoria de 28 rpm y una saturación de oxígeno de 92%. Se le infunden 20 ml/kg de cristaloides. Durante su traslado al hospital los signos vitales mejoran transitoriamente y después se deterioran a su llegada al hospital.', 'Señale la respuesta correcta:', '[{"position": 1, "text": "Requiere transfusión de sangre tipo-específica."}, {"position": 2, "text": "Requiere transfusión de sangre de emergencia (O Rh negativo)."}, {"position": 3, "text": "Debe prepararse una posible transfusión de sangre con pruebas cruzadas."}, {"position": 4, "text": "Debe probarse la infusión de nuevo de otros 20 ml/kg de cristaloides."}]'::jsonb, 4, 2, 'definitiva', 'En un paciente politraumatizado, la primera causa del shock es la pérdida hemática (shock hemorrágico). Las pautas a seguir siempre deben contemplar la reposición de la volemia (a ser posible, con hemoderivados lo más precozmente posible) y el control del foco. En este caso, ante el compromiso vital, la necesidad de trasfusión es muy urgente, por lo que la indicación es la trasfusión de sangre de emergencia (O Rh negativo).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-ecc616c442ce', 'd3a7e5f1ead723452d539b5174f1b7557ec665bc', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Una mujer de 24 años con antecedentes de migraña, en tratamiento con propranolol y anticonceptivos orales, que acude por disnea intensa, ronquera, erupción cutánea, náuseas y vómitos 30 minutos después de la toma de metamizol. Presenta una presión arterial de 90/40 mmHg y una SatO2 de 90%.', 'El tratamiento inicial más correcto sería administrar:', '[{"position": 1, "text": "Adrenalina."}, {"position": 2, "text": "Adrenalina y dexclorfeniramina."}, {"position": 3, "text": "Adrenalina, dexclorfeniramina y metilprednisolona."}, {"position": 4, "text": "Adrenalina, dexclorfeniramina y glucagón."}]'::jsonb, 4, 4, 'definitiva', 'Nos encontramos ante una reacción anafiláctica por metamizol, en la que hay que actuar rápidamente o la paciente podría evolucionar a parada cardíaca. Es importante evaluar la gravedad de las reacciones alérgicas, ya que, en este caso, el tratamiento precoz es fundamental para prevenir la elevada mortalidad si no se aplica. El tratamiento de elección es la adrenalina IM (sólo pasar a IV si anafilaxia refractaria), que ha demostrado el aumento de la supervivencia, pudiéndose repetir la administración cada 5-15 minutos si los síntomas no ceden. Como tratamiento adyuvante, se podría administrar la dexclorfeniramina. En este caso concreto, al tomar la paciente tratamiento previo con propranolol, nos está indicando que la respuesta correcta es la 4, que es la que incluye la administración de glucagón, que se administra porque los pacientes que toman betabloqueantes pueden ser resistentes al tratamiento con adrenalina y desarrollar hipotensión refractaria y bradicardia prolongada. La dosis en adultos es de 1 a 2mg, por vía IV o IM, pudiendo ser repetida en 5 minutos o seguida de una infusión a 5-15mcg/min.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-1f66e2cdeee1', '76403ca2b123ef1a09051481dcc3b1b688c13544', NULL, NULL, NULL, false, false, 'Pediatría', 'Embarazada de 37 semanas con antígeno de superficie del virus de la hepatitis B positivo. Consulta sobre la pauta a seguir con el recién nacido y si puede lactar.', '¿Qué consejo le parece más adecuado?', '[{"position": 1, "text": "Administrar vacuna frente a hepatitis B nada más nacer. Lactancia artificial."}, {"position": 2, "text": "Administrar vacuna e inmunoglobulinas al nacer. Lactancia materna a partir del mes."}, {"position": 3, "text": "Inmunoglobulinas al nacer y lactancia artificial."}, {"position": 4, "text": "Vacuna e inmunoglobulinas al nacer. Alimentación materna."}, {"position": 5, "text": "Alimentación artificial y aislamiento durante 4 semanas."}]'::jsonb, 5, 4, 'definitiva', 'La respuesta correcta es la 4. A los niños hijos de madres portadoras del VHB se les debe administrar en las primeras 24 horas de vida la vacuna antihepatitisB y la inmunoglobulina en diferentes lugares de punción. Aunque el virus se excreta en la leche materna, el riesgo de contagio por esta vía es muy bajo por lo que actualmente no es una contraindicación para la lactancia materna.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4e16987c2821', '7410da335d7224b5bf649e62fae4e0ffc16ab845', NULL, NULL, NULL, false, false, 'Dermatología', 'Niña de 7 años que acude a consulta porque los padres le notan la cara roja desde el día anterior y en las últimas horas le han notado manchas rojas en el cuerpo. En la exploración está afebril, con amígdalas y oídos sin alteraciones, auscultación cardiopulmonar normal. Presenta un exantema maculo papuloso confluyente en ambas mejillas, respetando el labio superior, semejando cara de “bofetón”. En el tórax presenta un exantema reticular, en encaje, no pruriginoso.', '¿Cuál es el diagnóstico clínico más probable?:', '[{"position": 1, "text": "Varicela."}, {"position": 2, "text": "Rubeola."}, {"position": 3, "text": "Eritema infeccioso o 5ª enfermedad."}, {"position": 4, "text": "Exantema súbito o 6ª enfermedad."}]'::jsonb, 4, 3, 'definitiva', 'Aunque esta pregunta está a caballo entre derma y pediatría, queremos aportar nuestro granito de arena. Nos están hablando del eritema súbito o quinta enfermedad (también llamado megaloeritema), producido por el parvovirus B19. Es típico que después de un episodio de fiebre alta aparezca un eritema en ambas mejillas en forma de “bofetón” que suele tener una extensión cráneo-caudal en los días siguientes.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d3413953c3f0', '08e73c681b4ccfa44dde293fe48747dda80fcd8b', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Un paciente de 45 años fue diagnosticado de infección VIH hace tres meses, presentando en ese momento CD4 45 linfocitos/µl y una carga viral de VIH-1 de 500.000 copias/ml. En ese momento presentaba un Mantoux negativo. Comenzó tratamiento con un inhibidor de integrasa y dos inhibidores de transcriptasa inversa, y al mes presentaba 25.000 copias y los CD4 habían subido a 80/µl. Consulta por presentar un cuadro de adenopatías cervicales y fiebre de dos semanas de evolución.', 'La punción de una de las adenopatías muestra bacilos ácido-alcohol resistentes aislados y granulomas epitelioides:', '[{"position": 1, "text": "Se trata de una tuberculosis ganglionar relacionada con una incompleta recuperación inmunológica."}, {"position": 2, "text": "Presenta fracaso al tratamiento y se trata de una infección oportunista."}, {"position": 3, "text": "Se trata de una infección oportunista desenmascarada en el seno de un cuadro de reconstitución inmune."}, {"position": 4, "text": "El hecho de presentar una prueba de Mantoux negativa descarta la tuberculosis."}]'::jsonb, 4, 3, 'definitiva', 'Estamos ante un paciente con infección por VIH en situación de inmunosupresión grave (<50 CD4+) y una carga viral muy elevada, que ha seguido la evolución esperable desde el punto de vista inmunovirológico tras el inicio de tratamiento (después de 12 semanas, la carga viral ha disminuido ostensiblemente – la respuesta 2 no sería correcta, recordemos que lo deseable es que negativice a las 24 semanas tras inicio de tratamiento, aunque en pacientes con CV mas elevadas como el nuestro, podría demorarse mas- y ha iniciado el ascenso del recuento de CD4+). El Mantoux negativo no descarta la tuberculosis (respuesta 4 incorrecta), ya que en pacientes con inmunodepresión grave puede dar falsos negativos. El diagnóstico de tuberculosis ganglionar es inmediato al detectar “bacilos ácido-alcohol resistentes aislados y granulomas epitelioides” en la punción de una de las adenopatías, ahora bien: considerando el perfil de enfermo, dicho proceso habrá sido desenmascarado clínicamente durante la reconstitución inmunológica no siendo la infección consecuencia de una incompleta recuperación inmunológica (respuesta correcta la número 3).', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos')
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('casimedicos-ea7c7675e796', '5725ff76805189c5f1972e48af9b77a5af939ee7', NULL, NULL, NULL, false, false, 'Bioestadística', 'Mujer de 86 años de edad en quien se ha detectado una fibrilación auricular no valvular. Tiene una puntuación CHADS2 de 3 puntos. En la bibliografía, pacientes similares en tratamiento con warfarina tienen un riesgo de ictus del 2,2% frente al 5,2% en los pacientes sin warfarina.', '¿Cuál sería el número necesario a tratar (NNT) para prevenir un ictus embolígeno con el tratamiento anticoagulante?:', '[{"position": 1, "text": "3."}, {"position": 2, "text": "19,2."}, {"position": 3, "text": "33,3."}, {"position": 4, "text": "49,5."}]'::jsonb, 4, 3, 'definitiva', 'De media, si se tratan 100 pacientes como esta mujer con warfarina, se reduce en 3 el número de ictus (pasa de 5.2 sin tratar a 3.2 tratando). Por lo tanto, si se tratan 33.3 pacientes como esta mujer con warfarina, se reduce en 1 el número de ictus: el NNT es 33.3', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-765ef2404c8a', 'a0e1111a8642fd7dbb8167519077814633c0c9c7', NULL, NULL, NULL, false, false, 'Nefrología', 'El resultado de la gasometría arterial de un paciente es: pH: 7,40, PaCO2 60 mmHg; bicarbonato 36 mM/L.', '¿Cuál es la alteración que presenta?:', '[{"position": 1, "text": "Ninguna, el pH es normal."}, {"position": 2, "text": "Acidosis respiratoria."}, {"position": 3, "text": "Acidosis respiratoria y alcalosis metabólica."}, {"position": 4, "text": "Alcalosis metabólica."}]'::jsonb, 4, 3, 'definitiva', 'Las gasometrías pueden ser engañosas ya que un pH normal puede sugerir que no hay ningún trastorno del equilibrio ácido-base, en cambio está enmascarando un doble trastorno en direcciones opuestas como en este caso. El paciente presenta acidosis respiratoria (PaCO2 60 mmHg; normal hasta 50) y alcalosis metabólica compensatoria (bicarbonato 36 mmol/l; normal hasta 28). Es la típica gasometría del paciente con EPOC e insuficiencia respiratoria crónica compensada.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-fc049159af6e', '8395bc7fa3d102270205d4fd968dda311385cd89', NULL, NULL, NULL, false, false, 'Nefrología', 'Mujer de 53 años de edad con antecedentes personales de obesidad y migraña. En repetidas ocasiones se le ha tomado la presión arterial en la consulta médica y de enfermería presentando cifras inferiores a 140/90 mmHg. Sin embargo, se ha comprado un aparato homologado para la toma de la presión arterial y se le ha enseñado a utilizarlo correctamente. Acude mostrando registros de presión arterial tomados en su domicilio a lo largo de varias semanas con valores superiores a 140/90 mmHg.', 'Señale la respuesta correcta:', '[{"position": 1, "text": "Presenta una hipertensión arterial secundaria."}, {"position": 2, "text": "Presenta una hipertensión arterial enmascarada."}, {"position": 3, "text": "Presenta una hipertensión clínica aislada."}, {"position": 4, "text": "Presenta una hipertensión arterial refractaria."}]'::jsonb, 4, 2, 'definitiva', 'La paciente descrita es la definición de HTA enmascarada, cifras normales en consulta y elevadas al hacer un AMPA o MAPA (opción 2 correcta). No es una HTA secundaria porque no se ha hecho estudio para confirmarlo (opción 1 incorrecta). No es una HTA aislada porque las cifras elevadas se mantienen durante varias semanas (opción 3 incorrecta). No es una HTA refractaria porque aún no ha recibido tratamiento (opción 4 incorrecta).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-710658558afc', 'c3f9791221411165cc2e308e488481dc770d703f', NULL, NULL, NULL, false, false, 'Nefrología', 'Paciente de 18 años que consulta por edemas. Se realiza analítica completa que muestra proteinuria de 8 g/día sin microhematuria, hipoalbuminemia e hipercolesterolemia con función renal normal. Se le administran de forma empírica corticoides. Al cabo de un mes, el cuadro clínico ha desaparecido completamente.', '¿Cuál es su hipótesis diagnóstica?:', '[{"position": 1, "text": "Amiloidosis."}, {"position": 2, "text": "Nefropatía IgA o enfermedad de Berger."}, {"position": 3, "text": "Síndrome de Alport."}, {"position": 4, "text": "Nefropatía con cambios mínimos."}]'::jsonb, 4, 4, 'definitiva', 'Nos describen a una paciente joven con criterios de síndrome nefrótico con excelente respuesta a corticoides. Sin biopsia, la presentación y evolución clínica sugieren una nefropatía con cambios mínimos, que habitualmente cursa con función renal normal o discretamente alterada junto con síndrome nefrótico, y que en el 85-90% de los casos se resuelve con el tratamiento esteroideo. La edad es el único dato que chirría un poco, ya que aunque es la causa más frecuente de síndrome nefrótico idiopático en niños y adolescentes, habitualmente se recomienda realizar biopsia previa al tratamiento en los mayores de 16 años, en cualquier caso no admite mucha discusión.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-151d83899e6c', 'edabd98f8a9e745b03fe3ab7722e358b2d2e0601', NULL, NULL, NULL, false, false, 'Oncología', 'Mujer de 32 años con síndrome de neoplasia endocrina múltiple de tipo 2A (MEN-2A) y portadora de una mutación en RET. En una ecografía de cuello se identifica un nódulo hipoecogénico de 6 mm con calcificaciones en su interior. Se decide tiroidectomía total y vaciamiento ganglionar cervical. En el estudio macroscópico se identifican un total de tres nódulos, dos en el lóbulo derecho de 5 y 6 mm, y uno en el lóbulo izquierdo de 4 mm. En el estudio microscópico las tres lesiones están constituidas por una proliferación uniforme de células redondeadas que se disponen con un patrón sólido y se acompañan de calcificaciones y de depósitos de amiloide. Los núcleos no son claros, ni muestran hendiduras, ni pseudoinclusiones. La tinción inmunohistoquímica para sinaptofisina es positiva. En el vaciamiento ganglionar cervical se identifican metástasis.', '¿Cuál es el diagnóstico anatomopatológico de las lesiones identificadas en la tiroidectomía total?:', '[{"position": 1, "text": "Carcinoma medular multifocal."}, {"position": 2, "text": "Carcinoma papilar multifocal."}, {"position": 3, "text": "Carcinoma folicular."}, {"position": 4, "text": "Hiperplasia de células parafoliculares."}]'::jsonb, 4, 1, 'definitiva', 'RET típico de medular de tiroides (células C, calcitonina elevada, heredado MEN-2ª, típica pregunta MIR).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d9ed76043513', '94289ad9c9b210e3768868b412707d9ed778eb06', NULL, NULL, NULL, false, false, 'Reumatología', 'Mujer de 27 años de raza negra que consulta por la aparición de edemas en miembros inferiores, disminución de diuresis, fiebre y un rash malar en alas de mariposa de 20 días de evolución. Analíticamente destaca creatinina 3 mg/dl, leucopenia, hemoglobina 10,5 g/dl (normocítica normocrómica), PCR 9 mg/dl y VSG 60 mm.', 'Respecto a la patología que presenta esta paciente, señale la respuesta correcta:', '[{"position": 1, "text": "Los anti-Sm no son específicos de esta patología."}, {"position": 2, "text": "Los anticuerpos anticentrómero se detectan en el 90% de los casos."}, {"position": 3, "text": "Los ANA (anticuerpos antinucleares) se detectan en el 50% de los casos."}, {"position": 4, "text": "Los anti-ADN bicatenario o nativo se correlacionan con el riesgo de nefritis."}]'::jsonb, 4, 4, 'definitiva', 'Otra pregunta sobre los anticuerpos del LES. Caso clínico de LES con afectación renal, en el que los anti-ADN bicatenario positivos aumentan el riesgo de nefritis. En cuanto al resto, los anti-Sm son específicos del LES, los ANA se detectan en más del 90% de los casos, y los anti-centrómero son típicos de la esclerodermia.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7df81d4c112d', 'ddf4bf7066d59538334f17a09e9b0375a7523f71', NULL, NULL, NULL, false, false, 'Reumatología', 'Varón de 75 años, hipertenso en tratamiento con enalapril (20 mg/día), que consulta por deterioro del estado general, cefalea bitemporal y claudicación mandibular de 3 semanas de evolución. Además, en las últimas horas, refiere dos episodios de amaurosis fugaz del ojo izquierdo. En la exploración física destaca engrosamiento y ausencia de pulso de la arteria temporal izquierda. Análisis: PCR 6 mg/dl (VN <1); hemoglobina 10,5 g/dl; VSG 92 mm. Radiografía de tórax normal.', 'Teniendo en cuenta el diagnóstico más probable, marque la opción correcta en cuanto al tratamiento:', '[{"position": 1, "text": "Debe administrarse rituximab, puesto que los glucocorticoides han quedado relegados a un tratamiento de segunda línea debido a sus efectos secundarios."}, {"position": 2, "text": "El tocilizumab se ha mostrado eficaz en reducir las recidivas y la dosis acumulada de prednisona en más del 50% de los pacientes."}, {"position": 3, "text": "En presencia de clínica isquémica, y para no empeorar el riesgo vascular del paciente, se debe evitar el uso de glucocorticoides a dosis superiores a 30 mg/día."}, {"position": 4, "text": "Junto con bolos de glucocorticoides de 1 g/día, el infliximab debe utilizarse como fármaco de primera línea para la inducción a la remisión."}]'::jsonb, 4, 2, 'definitiva', 'Caso clínico de arteritis de células gigantes. El tratamiento con corticoides sigue siendo la primera elección (respuesta 1 incorrecta), que se administrará en forma de pulsos (difieren las dosis según la bibliografía, pero al menos 125 mg/d) en caso de afectación ocular (respuesta 3 incorrecta). El tratamiento de elección actual para ahorrar corticoides es el Tocilizumab (respuesta 4 incorrecta), que además ha demostrado reducir las recidivas (respuesta 2 correcta).', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-b798835b5fb9', '9ba7b10b30b78f72c6baf7dab01267e146d79f1f', NULL, NULL, NULL, false, false, 'Psiquiatría', 'Hombre de 31 años sin antecedentes psiquiatricos acude a urgencias refiriendo… síntomas de ansiedad)¨. Hace dos días experimento otro cuadro igual….', 'Hace 1 semana ha roto su relación de pareja… Descartada cualquier patología orgánica…:', '[{"position": 1, "text": "Reacción de estres postraumatico."}, {"position": 2, "text": "Trastorno «agudo» de personalidad dependiente."}, {"position": 3, "text": "Trastorno depresivo."}, {"position": 4, "text": "Agorafobia."}, {"position": 5, "text": "Crisis de angustia."}]'::jsonb, 5, 5, 'definitiva', 'Aquí esta bien que te comenten sus antecedentes (todos tenemos antecedentes porque todos tenemos una vida) y que descarten patología orgánica. Eso es fundamental. No olvidemos que también los hipocondríacos tienen cuerpo. Eliminamos primero lo más llamativo trastorno «agudo» de personalidad. La personalidad nos acompaña toda la vida. No hay características «agudas» en nuestra personalidad. ¿Trastorno depresivo? Existe un criterio temporal que no se cumple, puede que este triste, pero triste no es depresión (1). ¿agorafobia? si fuese algo de eso nos habrían comentado el contexto ¿reacción de estres postraumatico? Esa es buena. El término correcto sería trastorno de estrés postraumatico o reacción a estres agudo, y según CIE 10: «El agente estresante puede ser una experiencia traumática devastadora que implica una amenaza seria a la seguridad o integridad física del enfermo o de persona o personas queridas (por ejemplo, catástrofes naturales, accidentes, batallas, atracos, violaciones) o un cambio brusco y amenazador del rango o del entorno social del individuo (por ejemplo, pérdidas de varios seres queridos, incendio de la vivienda, etc.)» o más brevemente: «naturaleza excepcionalmente amenazante o catastrófica» Romper con la pareja entiendo que es duro, pero no excepcional. Así que por eliminación 5. Crisis de angustia. Es una pregunta útil, habitual en la practica diaria, y así vemos que hay que evitar dar un diagnóstico de larga evolución por una reaccion natural. Los diagnósticos del 1 al 4 sería como llamar diabético al que tiene hiperglucemia tras comer tres magdalenas. Pregunta útil y realista.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-efb4590f5c05', 'c7858e5cde2f36edab74604098d82acbdddc387a', NULL, NULL, NULL, false, false, 'Alergología', 'Mujer de 25 años con antecedentes de asma bronquial alérgica por sensibilización a pólenes de gramíneas y dermatitis atópica. Presenta de forma brusca hipotensión, taquicardia, urticaria y broncoespasmo tras ingerir cacahuetes y es trasladada a urgencias.', '¿Cuál sería el orden de los fármacos a administrar y qué prueba de laboratorio podría solicitarse para ser evaluada posteriormente?:', '[{"position": 1, "text": "Adrenalina intramuscular, seguida de un broncodilatador inhalado tipo SABA y dexclorfeniramina intramuscular. A continuación solicitar triptasa sérica."}, {"position": 2, "text": "Un broncodilatador inhalado tipo SABA, seguido de dexclorfeniramina intramuscular y adrenalina intramuscular. A continuación solicitar triptasa sérica."}, {"position": 3, "text": "Dexclorfeniramina intramuscular, seguida de un broncodilatador inhalado tipo SABA y adrenalina intramuscular. A continuación solicitar proteína catiónica del eosinófilo."}, {"position": 4, "text": "Adrenalina intramuscular, seguida de un broncodilatador inhalado tipo SABA y dexclorfeniramina intramuscular. A continuación solicitar proteína catiónica del eosinófilo."}]'::jsonb, 4, 1, 'definitiva', 'La paciente está sufriendo un shock anafiláctico secundario a la ingesta de cacahuetes. El tratamiento de la anafilaxia y el shock anafiláctico de primera elección es la adrenalina intramuscular 1mg/ml (dosis de 0,01 mg/kg, en adultos 0,5 mg máximo). Seguido de tratamiento sintomático para estabilizar la vía respiratoria con O2 100% alto flujo, asegurar accesos venosos de grueso calibre, reposición de fluidos y monitorización continua (FC, TA, SatO2, diuresis). Como tratamiento adyuvante se puede administrar un broncodilatador inhalado tipo SABA, dexclorfeniramina intramuscular o corticoides como Hidrocortisona IV o Metilprednisolona IV. La adrenalina se puede repetir a las mismas dosis cada 5 minutos un máximo de 3 veces y si a los 15 minutos no responde se debería iniciar perfusión adrenalina IV, plantear Glucagón (si tratamiento con bloqueantes beta), Atropina (si bradicardia prolongada) o Vasopresores (si hipotensión refractaria). El marcador de laboratorio que se debe solicitar si se sospecha una anafilaxia es la Triptasa sérica en la primera hora para una determinación basal y otra a las 4-6 horas para observar su curva de elevación. No es un marcador de urgencias pero es muy útil de cara al estudio alergológico futuro.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-05fbcd53077f', '92407971da23b6ebabf2ae6facc8e0c44414138d', NULL, NULL, NULL, false, false, 'Alergología', 'Paciente de 35 años de edad que consulta para confirmar una sospecha de alergia a Anisakis simplex. Ha sufrido previamente un cuadro clínico de anisakiasis gastrointestinal tras ingerir pescado. En las pruebas efectuadas se evidencian niveles de IgE específica de 10 KU/l frente a Anisakis simplex.', 'De las siguientes ¿Cuál sería la recomendación dietética para este paciente?:', '[{"position": 1, "text": "No puede comer ningún pescado, crustáceo, molusco ni cefalópodo."}, {"position": 2, "text": "Puede comer pescado fresco cocinado a la plancha."}, {"position": 3, "text": "Puede comer pescado ultracongelado comercialmente."}, {"position": 4, "text": "Puede comer pescado fresco marinado o ahumado en frío."}]'::jsonb, 4, 3, 'definitiva', 'El Anisakis simplex es un parásito que se encuentra de forma frecuente en el pescado. Para evitar reacciones con dicho parásito realizará una dieta exenta de pescado fresco y crudo (boquerones en vinagre, ahumados, salazones, sushi, etc.). Podrá consumir pescado ultracongelado o pescado fresco previamente congelado a -20ºC al menos 5 días antes de cocinarlo, siempre y cuando lo cocine a altas temperaturas >60ºC (asado, frito, etc.), evitando preparaciones crudas, a la plancha o cocciones en microondas. Se recomienda consumir preferentemente las colas porque las larvas del parásito suelen estar cerca de las vísceras de la cabeza.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-6dd677a2f7b2', '2b8a10aa65c4115310a112697967d4f38e4cc554', NULL, NULL, NULL, false, false, 'Alergología', 'Mujer de 16 años diagnosticada de rinoconjuntivitis alérgica por sensibilización a pólenes de gramíneas desde los 10 años, que no controla totalmente la sintomatología en época de polinización con antihistamínicos orales y corticoides tópicos nasales.', '¿Qué opción terapéutica etiológica estaría indicada?:', '[{"position": 1, "text": "Inmunoterapia específica vía sublingual o vía subcutánea durante un periodo mínimo de 3 años."}, {"position": 2, "text": "Inmunoterapia específica vía sublingual o vía subcutánea durante un periodo máximo de 1 año."}, {"position": 3, "text": "Omalizumab vía subcutánea cada 4 semanas durante un período máximo de 1 año."}, {"position": 4, "text": "Omalizumab vía subcutánea cada 4 semanas durante un período mínimo de 6 meses."}]'::jsonb, 4, 1, 'definitiva', 'Actualmente el único tratamiento eficaz y capaz de modificar el curso natural de la alergia respiratoria es la inmunoterapia específica con alérgenos durante un mínimo de 3 años consecutivos. En este paciente el tratamiento convencional no ha funcionado por lo que se puede escalar a la inmunoterapia específica con alérgenos. Si que es verdad que no es necesario esperar 10 años para iniciarla dado que está indicada y se permite su uso si existe una relevancia clínica en mayores de 5 años. Omalizumab es un tratamiento biológico que solo estaría indicado en caso de asma bronquial moderada grave secundaria a alergia respiratoria.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-2122f4f3b1c1', 'e3309eb9d876d2a79a9cd6f5ddbaac4cd9c16f39', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Varón de 23 años diagnosticado de síndrome de Wolff-Parkinson-White que acude a urgencias por palpitaciones. El ECG muestra una taquicardia irregular de QRS ancho, con una frecuencia cardiaca de 205 lpm, compatible con fibrilación auricular preexcitada.', '¿Cuál de los siguientes fármacos considera adecuado administrar para detener la taquicardia?:', '[{"position": 1, "text": "Verapamilo."}, {"position": 2, "text": "Digoxina."}, {"position": 3, "text": "Adenosina."}, {"position": 4, "text": "Procainamida."}]'::jsonb, 4, 4, 'definitiva', 'Procainamida. El tratamiento de elección para el síndrome de Wolff-Parkinson-White es la cardioversión con corriente continua. Los fármacos que reducen la frecuencia cardíaca, empleados en forma habitual en la fibrilación auricular, no resultan eficaces, y la digoxina y los bloqueantes de los canales de calcio no dihidropiridinas (p. ej., verapamilo, diltiazem) están contraindicados porque podrían aumentar la frecuencia ventricular y causar fibrilación ventricular. Si no es posible la cardioversión, se deben usar fármacos que prolongan el periodo refractario de la conexión de los accesorios. Se prefiere procainamida IV o amiodarona, pero cualquier fármaco antiarrítmico de clase Ia, Ic o III se puede utilizar.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-36d41c0b3cdc', '6c46ac829abd2d5f784db481629a4b74d4c6eb2e', NULL, NULL, NULL, false, false, 'Endocrinología', 'Una estudiante de 22 años sin antecedentes patológicos ni uso de medicamentos salvo anovulatorios acude a Urgencias por deterioro del estado general y necesidad de respirar profundamente. Refiere haber perdido peso en los 2-3 últimos días, polidipsia, poliuria y náuseas. No tos ni sensación febril. Exploración: aspecto de gravedad, presión arterial 100/60 mmHg, respiración profunda y rápida (28rpm), nivel de conciencia conservado, sequedad de mucosas. No fiebre.', 'Analítica: glucemia 420 mg/dL, Na+ 131 mEq/L, K+ normal, pH 7,08, bicarbonato 8 mEq/L y cetonuria (+++) ¿Qué respuesta le parece más correcta?', '[{"position": 1, "text": "Debut de una diabetes mellitus tipo 2, con disnea probablemente por neumonía o tromboembolismo, ya que toma anovulatorios."}, {"position": 2, "text": "Es una cetoacidosis diabética. Hay que tratar con insulina endovenosa, sueroterapia, medidas generales y buscar causa precipitante."}, {"position": 3, "text": "Debut de diabetes tipo 1 con cetoacidosis. Tratar con bicarbonato y tras corregir la acidosis, añadir insulina endovenosa."}, {"position": 4, "text": "Parece una cetoacidosis diabética, pero podría ser alcohólica. Se debe determinar la alcoholemia antes de iniciar tratamiento con insulina."}, {"position": 5, "text": "Tratar con insulina rápida subcutánea, sueroterapia y pedirle que beba líquidos en abundancia."}]'::jsonb, 5, 2, 'definitiva', 'Debut de DM con cetoacidosis. La prioridad es la administración de insulina iv y sueroterapia. Bicarbonato si pH < 7. Nunca debe retrasarse la administración de la insulina.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-99981cead047', '4e8b6d57366091e0c036613f792017f1334ffe39', NULL, NULL, NULL, false, false, 'Dermatología', 'Paciente de 33 años, residente en Valencia, que consulta por presentar en la mejilla derecha una placa eritemato-anaranjada tras picadura de insecto que ha ido creciendo lentamente hasta alcanzar 1,5 cm y que en las últimas semanas se ha ulcerado y cubierto de una escamocostra. La lesión solo le origina discretas molestias si se rasca. Entre sus antecedentes destaca psoriasis en placas en tratamiento con adalimumab subcutáneo. Tiene buen estado general y no toma otros fármacos ni refiere alergias a medicamentos.', 'Indique el tratamiento que emplearía:', '[{"position": 1, "text": "Isotretinoina oral."}, {"position": 2, "text": "Antimoniato de meglumina intralesional."}, {"position": 3, "text": "Corticoesteroides sistémicos."}, {"position": 4, "text": "Amoxicilina oral."}]'::jsonb, 4, 2, 'definitiva', 'El hecho que nos comenten el lugar de residencia ya nos da muchas pistas. Una “picadura” que se transforma en una lesión en una zona descubierta con superficie costrosa y que molesta poco o nada… pues eso en la cuenca mediterránea es una leishmaniasis cutánea o botón de Oriente. Y si bien es cierto que la lesión es de < 4 cm y única, nos dicen que la paciente está en tratamiento con adalimumab, un anticuerpo monoclonal anti-TNF. A excepción del antimoniato de meglumina, ninguno de los otros tratamientos propuestos en las diferentes opciones está indicado en la leishmaniasis, así que está claro. Lo único que es más discutible es que, al tratarse de una paciente inmunodeprimida, probablemente el tratamiento sistémico sería más adecuado. No sé si por ello impugnable, pero al menos, discutible.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-91b6656a2d45', '114952a6d2fd5baa140546ab904eb1acd7f788ba', NULL, NULL, NULL, false, false, 'Endocrinología', 'Varón de 58 años que acude a control programado de una diabetes mellitus tipo 2 diagnosticada hace 6 años. Tiene antecedentes personales de HTA, dislipidemia, cardiopatía isquémica y pancreatitis de origen biliar. Su medicación incluye lisinopril, metoprolol, metformina, AAS y atorvastatina. En la exploración física presenta tensión arterial 151/93 mmHg, IMC 27,1 kg/m2. La hemoglobina glicada es de 8,3%.', '¿Cuál de los siguientes es el tratamiento más adecuado para este paciente?:', '[{"position": 1, "text": "Empaglifozina."}, {"position": 2, "text": "Glipizida."}, {"position": 3, "text": "Acarbosa."}, {"position": 4, "text": "Sitagliptina."}]'::jsonb, 4, 1, 'definitiva', 'Paciente con obesidad, HTA y aumento de HbA1C. En estudios recientes, Empaglifozina, inhibidor altamente selectivo del SGLT210, reduce de forma significativa la TA, la HbA1C y el IMC. La glipizida es del grupo de las sulfonilureas. Se debe evitar su uso en pacientes con cardiopatía. La acarbosa puede interaccionar con betabloqueantes, como los que toma nuestro paciente. La sitagliptina ha demostrado disminuir HbA1C pero no HTA ni IMC.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-982a85756577', 'baa7dde27f9170aaba14352442278dc39edf381e', NULL, NULL, NULL, false, false, 'Endocrinología', NULL, 'Paciente diabético de 63 años a quien su médico de familia ha solicitado una analítica para determinar los niveles de vitamina B12. ¿Cuál es el fármaco antidiabético que toma que justifica dicha solicitud?:', '[{"position": 1, "text": "Gliclazida."}, {"position": 2, "text": "Metformina."}, {"position": 3, "text": "Repaglinida."}, {"position": 4, "text": "Pioglitazona."}]'::jsonb, 4, 2, 'definitiva', 'La metformina es un antidiabético oral de uso extendido en el tratamiento de la diabetes mellitus tipo 2. Los efectos secundarios más conocidos son los gastrointestinales y la acidosis láctica; sin embargo, la malabsorción de vitamina B 12, es menos conocida. Se observa una disminución de los niveles de vitamina B 12, en pacientes tratados con metformina. El mecanismo por el cual sucede este déficit no está claro y se sabe que es reversible al interrumpir el tratamiento.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5e0a320fd62e', '0ff21cd803361585272ea324a2961521e583e39d', NULL, NULL, NULL, false, false, 'Endocrinología', 'Varón de 58 años, obeso, asintomático, bebedor moderado, que presenta una primera glucemia basal de 153 mg/d con glucosuria negativa. En las semanas siguientes ha tenido otras dos cifras de glucemias basales de 118 y 136 mg/dl.', '¿Cuál de las siguientes es la actitud más apropiada para confirmar el diagnóstico de diabetes mellitus?:', '[{"position": 1, "text": "Practicar una curva de glucemia con 75 g de glucosa."}, {"position": 2, "text": "Reúne ya criterios diagnósticos de diabetes mellitus."}, {"position": 3, "text": "Solicitar una determinación de insulinemia basal o péptido C."}, {"position": 4, "text": "Solicitar una determinación de hemoglobina glicosilada."}]'::jsonb, 4, 2, 'definitiva', 'Criterios de Diagnóstico de DM según ISPAD 2018 *Síntomas clásicos de diabetes con glucemia > 200mgr/dl o: * Glucemia en ayunas ≥ 126mgr/dl (ayunas al menos 8h) o * Glucemia a las 2h de SOG ≥ 200mgr/dl (en 2 ocasiones) o * HbA1C ≥ 6,5%.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-ce8f5cc170de', '68e7cd4784f222319d66ac946a6b326b3f3a99f4', NULL, NULL, NULL, false, false, 'Hematología', 'Mujer de 35 años, que toma anticonceptivos, acude a urgencias con síndrome febril y parestesias en hemicuerpo izquierdo. En la analítica de sangre se observa Hb 7,5 g/dl, plaquetas 7.000/microl, leucocitos normales con recuento diferencial normal, LDH 1.200 UI/l, reticulocitos 10% (normal 0,5-2%), haptoglobina en suero indetectable, test de Coombs directo negativo y frotis de sangre periférica con esquistocitos. Coagulación (tiempo de protrombina y APTT) normal.', '¿Cuál de los siguientes es el diagnóstico más probable?:', '[{"position": 1, "text": "Anemia hemolítica autoinmune."}, {"position": 2, "text": "Púrpura trombótica trombocitopénica."}, {"position": 3, "text": "Síndrome de Evans (anemia hemolítica y trombopenia inmunes)."}, {"position": 4, "text": "Trombocitopenia inmune idiopática."}]'::jsonb, 4, 2, 'definitiva', 'La paciente presenta criterios para Púrpura trombótica Trombocitopénica (PTT): 1. Alteración neurológica. 2. Sindrome febril (fiebre). 3. Anemia hemolítica coombs negativo migroangiopática (presencia de esquistocitos). 4. Trombopenia.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4b444e0aafb1', '98a426b7d49cc627447a8a14f2b26eca7a6cf14a', NULL, NULL, NULL, false, false, 'Endocrinología', 'Diez días después de practicarle una hemitiroidectomía a una paciente con un nódulo tiroideo de 1,5 cm recibe el siguiente informe definitivo por parte del anatomopatólogo: «patrón folicular muy celular sin invasión capsular que invade los vasos sanguíneos y nervios adyacentes».', 'Señale la respuesta correcta:', '[{"position": 1, "text": "Como no existe invasión capsular no es conveniente realizar más cirugía."}, {"position": 2, "text": "El patrón folicular es indicación de vaciamiento ganglionar cervical profiláctico."}, {"position": 3, "text": "Se trata de un carcinoma folicular y requiere completar la tiroidectomía."}, {"position": 4, "text": "El informe permite descartar un carcinoma papilar con total seguridad en el tiroides remanente."}, {"position": 5, "text": "La medición de la calcitonina plasmática nos permitirá diferenciar entre un carcinoma papilar y folicular."}]'::jsonb, 5, 3, 'definitiva', 'Me parece una pregunta un poco más difícil ya que hay que tener conceptos claros de anatomía patológica. De todas formas, se podría sacar por exclusión y por la forma en la que se expresan las respuestas: Respuesta 2: el vaciamiento profiláctico está indicado en el medular. Respuesta 4: simplemente por la forma de expresarla ya se debería haber descartado. Respuesta 5: ya sabéis que la calcitonina se utiliza en el carcinoma medular y no en el diferenciado. Las respuestas 1 y 3 son contrarias, una recomienda completar la tiroidectomía y otra no. En los únicos que no se recomienda tiroidectomía completa son los microcarcinomas que midan menos de 1 cm.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c5f28241abcf', 'f67c7d0fbfd6c23622685f469d2ce73bbab49153', NULL, NULL, NULL, false, false, 'Hematología', 'Mujer de 26 años diagnosticada de lupus eritematoso sistémico, en tratamiento con hidroxicloroquina, que consulta por sensación de debilidad generalizada que se ha instaurado progresivamente en los últimos 15 días. En la exploración física se aprecia palidez cutánea y en la analítica destaca Hb 7,4 gr/dL, Hcto 31%,VCM 108.', '¿Cuál de las siguientes determinaciones será más útil para decidir la actuación?:', '[{"position": 1, "text": "Haptoglobina."}, {"position": 2, "text": "Test de Coombs."}, {"position": 3, "text": "Vitamina B12."}, {"position": 4, "text": "Anticuerpos antinucleares."}]'::jsonb, 4, 2, 'definitiva', 'Dan a conocer de una paciente con LES en tratamiento con Hidroxicloroquina. Cuenta con hb en 7,4 y un VCM más de 100, añadiendo la palidez y debilidad, estaríamos frente a una anemia macrocitica. En mi opinión, la más idónea seria la alteranativa 2, ya que al estar recibiendo tratamiento farmacológico, se ha reportado que la hidroxiloroquina disminuye la absorción del ácido fólico. Al tener una complicación de LES, en este caso, podríamos estar frente a una Anemia hemolítica autoinmune con consumo de ácido fólico. Y para ello sería primero determinar con el coombs directo.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-0dc683557b33', '90008b2142826e4332b277e8daffc692016c4226', NULL, NULL, NULL, false, false, 'Hematología', 'Mujer de 45 años sin antecedentes de interés que consulta por presentar sensación disneica de unos 4 días de evolución. La exploración muestra taquicardia rítmica, sin soplos y la auscultación pulmonar es normal. La gasometría arterial muestra una pO2 de 70 mmHg y una pCO2 32 mmHg. El hemograma, la función renal y hepática son normales. Tiempo de protrombina 90%, tiempo de tromboplastina parcial activada (TTPA) con ratio de 2 respecto al control (N <1,2).', '¿De los siguientes diagnósticos cuál es el más probable?:', '[{"position": 1, "text": "Síndrome antifosfolípido."}, {"position": 2, "text": "Factor V de Leiden."}, {"position": 3, "text": "Hemofilia."}, {"position": 4, "text": "Pericarditis aguda."}]'::jsonb, 4, 1, 'definitiva', 'En esta pregunta lo que asumen es que se trata de una mujer de 45 años a la que se le diagnostica un tromboembolismo pulmonar (TEP). Con este diagnóstico, se excluyen directamente las opciones 3 y 4 (además, es mujer, así que no tendríamos que pensar en la hemofilia) Como dato analítico, dice que hay un alargamiento del TTPA. Por lo tanto, quieren que sepas, que tiene ac lúpico positivo y que lo relaciones directamente con el síndrome antifosfolípido (SAF). Un Leiden no altera la coagulación, así que se descarta tambíen. De todos modos, aunque no entra dentro de las posibles respuestas, la positividad a lúpicos se pueden relacionar con un sinfín de situaciones clínicas, síndromes y patologías. Asumir que un TEP + lúpico es un SAF, me parece un tanto exagerado, pero es lo más probable con los datos que se aportan.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-0b789d8f1d9f', '9e856aa9aa8fd7cb9bc458b8b4f7961fcede4046', NULL, NULL, NULL, false, false, 'Medicina Preventiva y Epidemiología', 'Paciente de 62 años que consulta por haber estado en contacto cercano en las últimas semanas con una persona con una tuberculosis activa. El Mantoux es positivo (12 mm). Entre sus antecedentes destaca estar en tratamiento con anticoagulantes orales (acenocumarol) por una trombosis venosa profunda hace unos meses. No refiere fiebre ni tos y se encuentra asintomático. La Rx de tórax es normal.', '¿Cuál de los siguientes tratamientos es el más recomendable?:', '[{"position": 1, "text": "Isoniacida, durante nueve meses."}, {"position": 2, "text": "Rifampicina, durante cuatro meses."}, {"position": 3, "text": "Isoniacida y rifampicina, durante tres meses."}, {"position": 4, "text": "Isoniacida y rifapentina, durante tres meses."}]'::jsonb, 4, 4, 'definitiva', 'A partir del 2018, hay cuatro esquemas posológicos para el tratamiento de la infección de tuberculosis latente recomendados por los CDC que usan isoniacida (INH), rifapentina (RPT) o rifampina (RIF). Todos los tratamientos son eficaces. Los proveedores de atención médica deberían recetar los tratamientos más cortos, que son más convenientes, siempre que sea posible. La combinación más corta sería la de Isoniacida + Rifapentina, durante tres meses o la Rifampicina durante cuatro meses. Sin embargo, el hecho de tomar acenocumarol hace que la indicación para este paciente sea la Isoniacida durante 9 meses, ya que hay interacción entre los derivados de la rifamicina (rifapentina y rifampicina).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-471e652d8f44', '69f90193ffff2a20f65d24877bea2a533a3c74df', NULL, NULL, NULL, false, false, 'Nefrología', 'Mujer de 47 años que consulta por síndrome miccional. Se le diagnostica de infección urinaria no complicada y se le trata con ciprofloxacino durante 5 días. A la semana vuelve a consultar por mal estado general, artralgias y aparición de un rash cutáneo. En la analítica destaca un filtrado glomerular de 45 ml/min (CKD-EPI), siendo el de hace 6 meses de 100 ml/min. En el sedimento se identifican leucocitos, siendo negativo para nitritos.', '¿De las siguientes, cuál es la causa más probable de su insuficiencia renal?:', '[{"position": 1, "text": "Glomerulonefritis postinfecciosa."}, {"position": 2, "text": "Nefrotoxicidad por ciprofloxacino."}, {"position": 3, "text": "Pielonefritis aguda."}, {"position": 4, "text": "Nefritis intersticial aguda."}]'::jsonb, 4, 4, 'definitiva', 'El cuadro de malestar general, artralgias, rash cutáneo, fracaso renal agudo y sedimento activo con leucocituria estéril siguiendo a la toma de un fármaco es altamente sugestivo de NIA (opción 4 correcta). Dentro de los fármacos, los antibióticos son la causa más frecuente, y el ciprofloxacino uno de los habituales. La nefrotoxicidad directa es muy rara y se caracteriza por la cristalización en los túbulos renales (opción 2 incorrecta). La glomerulonefritis postinfecciosa es más propia de niños y adultos mayores de 60 años, y suele manifestarse con hematuria tras infecciones estreptocócicas (opción 1 incorrecta). La pielonefritis aguda nos la habrían presentado con fiebre alta y dolor en fosa renal (opción 3 incorrecta).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-22212dd49386', '9c478d9edfb75d620dea449ebb60038d9aabd9dd', NULL, NULL, NULL, false, false, 'Nefrología', 'Varón de 22 años que acude a urgencias por presentar orina “casi negra” desde hace 12 horas. No tiene antecedentes de interés ni toma medicamentos. Refiere un cuadro catarral de vías altas desde hace 4-5 días para el que ha tomado paracetamol. Exploración: temperatura 37,3 ºC, PA 150/95, FC 85 lpm, ligero eritema faríngeo, resto normal. En analítica destaca: Hb 12,8 g/dl, Hcto 39%, leucocitos 10.500/mm3 con fórmula normal, plaquetas 250.000/mm3, coagulación normal, urea 25 mg/dl, creatinina 0,8 mg/dl, iones, perfil hepático, lipídico, albúmina y proteínas totales normales. Estudio de autoinmunidad normal y serología vírica negativa. Orina de 24 h con proteinuria de 0,75 g/24 h, sedimento con 10 eritrocitos por campo (90% dismórficos), no leucocituria. Ecografía renal normal.', '¿Qué diagnóstico le parece más probable?:', '[{"position": 1, "text": "Nefropatía con cambios mínimos."}, {"position": 2, "text": "Glomerulonefritis postinfecciosa."}, {"position": 3, "text": "Nefropatía IgA."}, {"position": 4, "text": "Nefritis intersticial aguda."}]'::jsonb, 4, 3, 'definitiva', 'Un cuadro de hematuria macroscópica y proteinuria leve con niveles normales de creatinina, acompañando a un cuadro catarral de vías altas, es muy sugestivo de nefropatía IgA (opción 3 correcta).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c3bffaf41f3b', '28c7ad476e49d66a14c1627fdaa5930aaae3dbbf', NULL, NULL, NULL, false, false, 'Nefrología', 'Varón de 24 años que presenta microhematuria dismórfica, proteinuria de 3 g/24 h, FGe (CKD-EPI) 85 ml/min e hipoacusia neurosensorial. Refiere que su abuela materna precisó diálisis a los 70 años y tanto su madre como su hermana pequeña presentan microhematuria aislada.', '¿Cuál de las siguientes enfermedades es más probable?:', '[{"position": 1, "text": "Síndrome de Alport."}, {"position": 2, "text": "Nefropatía IgA."}, {"position": 3, "text": "Enfermedad de Fabry."}, {"position": 4, "text": "Poliquistosis renal autosómica dominante."}]'::jsonb, 4, 1, 'definitiva', 'Caso de libro, poco que añadir. Microhematuria, proteinuria e hipoacusia neurosensorial en varón joven, con antecedentes familiares de mujeres con hematuria = síndrome de Alport.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c88712d58768', '0f4985c2d0a9ef66db9847f8f2b8f6811b2d6e5a', NULL, NULL, NULL, false, false, 'Nefrología', 'Varón de 19 años sin antecedentes de interés que acude a urgencias porque después de una infección respiratoria presenta astenia, malestar general, oliguria y cefalea. Exploración física: TA 210/120 mmHg, fondo de ojo con retinopatía hipertensiva grado III. Analítica: Hb 7,4 g/dl, plaquetas 85.000/mm3, 2-3 esquistocitos en la extensión de sangre periférica, LDH 950 UI/ml, creatinina sérica 8,75 mg/dl. Sistemático de orina: proteinuria 300 mg/dl, sedimento 15 hematíes por campo. Niveles de ADAMTS-13 normales.', 'Ante estos hallazgos ¿cuál sería su principal sospecha diagnóstica?:', '[{"position": 1, "text": "Púrpura trombótica trombocitopénica."}, {"position": 2, "text": "Síndrome hemolítico urémico atípico."}, {"position": 3, "text": "Coagulación intravascular diseminada."}, {"position": 4, "text": "Síndrome hemolítico urémico típico."}]'::jsonb, 4, 2, 'definitiva', 'Pregunta difícil. El paciente presenta una microangiopatía trombótica (MAT) con fracaso renal agudo. Esto orienta hacia SHU, PTT, MAT inducida por fármacos, o MAT mediada por complemento, coagulación o metabolismo. Los niveles normales de ADAMTS-13 descartan la PTT (opción 1 incorrecta). La ausencia de clínica gastrointestinal descarta el SHU típico por toxina Shiga (opción 4 incorrecta). Las infecciones por neumococo también pueden causar SHU, aunque es raro y más en adultos. El antecedente de infección respiratoria (no especificada, podría ser una neumonía neumocócica) junto con la ausencia de datos de CID (no mencionan hemorragias ni pruebas de coagulación alteradas) me hace pensar en un SHU atípico (opción 2 correcta).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-675e60e57c71', 'c01cf1c7b778c6e157f630ee49bed24e584a7bd3', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Mujer de 80 años con antecedentes de hipertensión arterial y diabetes mellitus que presenta de forma brusca una alteración del lenguaje. A su llegada al hospital se objetiva una fibrilación auricular no conocida y en la exploración presenta habla fluente con tendencia a la jergafasia, mala compresión del lenguaje, incapacidad para la repetición y disnomia.', 'Semiológicamente presenta un cuadro compatible con:', '[{"position": 1, "text": "Afasia de Broca."}, {"position": 2, "text": "Afasia de conducción."}, {"position": 3, "text": "Afasia transcortical sensitiva."}, {"position": 4, "text": "Afasia de Wernicke."}]'::jsonb, 4, 4, 'definitiva', 'Es una pregunta de semiología que nos ayuda a recordar los tipos de afasia. Hay que tener en cuenta los siguientes aspectos: emisión del lenguaje (fluente, no fluente, no emisión), comprensión (sí o no), repetición (sí o no) y nominación. La afasia de Wernicke o sensitiva tiene un lenguaje fluente, no comprende, no repite y no nomina, tal y como la paciente de la pregunta. La afasia transcortical sensitiva se diferencia de la sensitiva en que los pacientes son capaces de repetir. La afasia de conducción se diferencia de la sensitiva en que la comprensión está conservada, el resto es igual. Por último, en la afasia de broca el lenguaje es no fluente, la comprensión esta preservada, no repite y no nomina.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-1df70e846581', 'c617fab342a94606fae15dba90f46a5759d863c4', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Mujer de 29 años con antecedentes de crisis febriles y fumadora importante. Consulta por presentar desde hace unos 2 años episodios frecuentes, estereotipados, que comienzan con una sensación epigástrica ascendente y un olor desagradable, seguidos de desconexión del medio. Los familiares que están con ella observan que hace movimientos de chupeteo y de apertura y cierre repetidos de la mano izquierda. Pasados dos minutos los movimientos ceden, pero le cuesta responder adecuadamente y solo recuerda parcialmente lo ocurrido.', 'De los siguientes ¿cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Crisis focales complejas del lóbulo temporal."}, {"position": 2, "text": "Accidentes isquémicos transitorios en territorio carotídeo derecho."}, {"position": 3, "text": "Crisis focales simples motoras."}, {"position": 4, "text": "Episodios de amnesia global transitoria."}]'::jsonb, 4, 1, 'definitiva', 'El caso clínico hace una descripción de libro de una crisis temporal medial. El aura de la sensación epigástrica ascendente y la alteración olfativa y la posterior descripción de la crisis con la alteración del nivel de conciencia (desconexión del medio) con automatismos bucales y manuales. La clasificación vigente es la de la ILAE de 2017 que describiría esta crisis como crisis focal con alteración del nivel de conciencia, pero en el MIR siguen usando la terminología antigua (compleja es como se llamaba a la alteración del nivel de conciencia).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-6f7c2bcb4c34', 'd5c1d84ac472ba2574b88b895a41e40df42910d0', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Varón de 55 años que sufre una hemorragia subaracnoidea por rotura de un aneurisma de arteria cerebral media. Es tratado de forma quirúrgica. Tras una buena evolución en la que recupera la capacidad de caminar, un mes después de sufrir la hemorragia presenta un deterioro progresivo, llegando a encontrarse obnubilado y con dificultad para obedecer órdenes.', 'Señale la afirmación correcta:', '[{"position": 1, "text": "Se encuentra en el momento de la evolución en el que es más frecuente el vasoespasmo."}, {"position": 2, "text": "Probablemente este deterioro progresivo sea secundario al resangrado del aneurisma."}, {"position": 3, "text": "El deterioro subagudo que presenta con mayor probabilidad se debe a hidrocefalia."}, {"position": 4, "text": "La técnica diagnóstica de elección es la angiografía cerebral."}]'::jsonb, 4, 3, 'definitiva', 'El vasoespasmo como complicación de la hemorragia subaracnoidea suele producirse de una forma precoz, en la semana posterior a la hemorragia. El deterioro progresivo con alteración del nivel de conciencia nos hace sospechar en una de las complicaciones que puede producirse en este cuadro: la hidrocefalia. La técnica diagnóstica de elección en este caso es la neuroimagen con TC craneal.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7ca6f8bcd075', 'a07dba6ad83a638a995240715d9bc86f965eb237', NULL, NULL, NULL, false, false, 'Endocrinología', 'En una mujer obesa de 42 años se le realiza determinación del cortisol en sangre, orina y saliva y en todas las determinaciones está elevado.', 'Tras la realización del test de supresión nocturna con dexametasona, los niveles de cortisol en sangre permanecen elevados, por lo que se sospecha síndrome de Cushing ACTH independiente, ¿qué prueba adicional solicitaría para confirmar el diagnóstico en este momento?', '[{"position": 1, "text": "Un cateterismo de senos petrosos."}, {"position": 2, "text": "Una gammagrafía con somatostatina marcada (Octreoscan)."}, {"position": 3, "text": "Una gammagrafía con Sesta-MIBI."}, {"position": 4, "text": "Una ecografía abdominal."}, {"position": 5, "text": "Una TC de suprarrenales."}]'::jsonb, 5, 5, 'definitiva', 'De todas formas creo que está mal planteado el caso clínico, ya que antes de hacer el TAC se debería medir la ACTH y, una vez que la ACTH esté suprimida hacer el TAC. Pero como la pregunta es «qué haría para confirmar el diagnóstico de sospecha de un síndrome Cushing ACTH independiente», la respuesta es el TAC.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-893691bf59ab', '5ebe854813592ee48c864cbef837c86434d2f596', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Mujer de 35 años, remitida a urgencias por traumatismo craneoencefálico por caída en patinete, sin pérdida de conciencia ni amnesia. En la exploración se trata de un traumatismo craneoencefálico cerrado con conmoción y cefalea leve sin presencia de náuseas y vómitos. La exploración neurológica es normal y presenta un índice de Glasgow de 15.', 'Ante esta situación ¿qué prueba de imagen está indicada en primer lugar?:', '[{"position": 1, "text": "TC craneal sin contraste."}, {"position": 2, "text": "TC craneal con contraste."}, {"position": 3, "text": "Ninguna prueba de imagen."}, {"position": 4, "text": "Radiografía simple de cráneo."}]'::jsonb, 4, 3, 'definitiva', 'Tras un TCE en un paciente no anticoagulado ni antiagregado, sin factores de riesgo conocidos para hemorragia, que no presenta datos de alarma ni en anamnesis ni en exploración física no es necesario realizar prueba de imagen craneal.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-ef1d41bb3b90', '2ad79b0237683d3bc5dab89537fc99b71578c912', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Varón de 53 años sin antecedentes de interés que tras un mal movimiento en el gimnasio nota un dolor lumbar que al pasar las horas se irradia hacia la pierna derecha por la parte posterior y llega al borde lateral del pie. Presenta en la exploración maniobra de Lasègue positiva a 40o, reflejo aquíleo abolido y no se puede poner de puntillas.', 'El diagnóstico etiológico más probable es:', '[{"position": 1, "text": "Hernia discal L2-L3 derecha."}, {"position": 2, "text": "Hernia discal L3-L4 derecha."}, {"position": 3, "text": "Hernia discal L4-L5 derecha."}, {"position": 4, "text": "Hernia discal L5-S1 derecha."}]'::jsonb, 4, 4, 'definitiva', 'Describe afectación de raíz S1 por la incapacidad para andar de puntillas y la ausencia de reflejo aquíleo, además de la distribución del dolor por la pierna. De nuestras opciones, la causa que puede producir un daño en S1 es la hernia discal L5-S1.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-2e9824355c48', 'd43b7c23e98329a868cc951749a73e8e7bf490e5', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Mujer de 43 años portadora de dispositivo intrauterino de levonorgestrel que consulta por falta de descanso nocturno con aparición de calor y palpitaciones. En la analítica destaca T4 libre 10,5 pmol/L (9-19), tirotropina 2,1 mUI/L (0,30-5,00), FSH 95,6 UI/L (1,38-16,7), LH 21 UI/L (2,4-9,3), estradiol < 0,07 nmol/L (0,07 – 1,14).', '¿Cuál es el tratamiento más adecuado?:', '[{"position": 1, "text": "Benzodiacepinas."}, {"position": 2, "text": "Estrógenos vaginales."}, {"position": 3, "text": "Estrógenos y progestágenos orales en pauta continua."}, {"position": 4, "text": "Estrógenos transdérmicos en pauta continua."}]'::jsonb, 4, 4, 'definitiva', 'El perfil hormonal que nos cuentan está en rango menopáusico (FSH >20; estradiol <5) y la paciente tiene síntomas vasomotores sistémicos. Por todo ello, sería más adecuado administrar estrógenos sistémicos. Para compensar, ya tiene a nivel local uterino un progestágeno (DIU levonorgestrel).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-fb1bd121d799', 'a509857fbbc536ecf8750d6bfec8c9a665323795', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Mujer de 51 años, menopaúsica desde hace un año y medio, que consulta por manchado vaginal de 2 semanas de evolución. Refiere que el manchado es menor que una regla. En la ecografía se objetiva un endometrio de 7 mm.', 'Señale la opción correcta:', '[{"position": 1, "text": "El endometrio está engrosado y ante la clínica de la paciente, toma una biopsia endometrial con cánula de Cornier."}, {"position": 2, "text": "El endometrio no está engrosado por lo que le pauta ácido tranexámico y seguimiento ambulatorio."}, {"position": 3, "text": "Tiene indicación de histeroscopia diagnóstica sin necesidad de toma de biopsia endometrial."}, {"position": 4, "text": "El endometrio no está engrosado, pero como tiene clínica de metrorragia está indicada la realización de una biopsia endometrial."}]'::jsonb, 4, 1, 'definitiva', 'El endometrio está engrosado para ser una mujer menopáusica (algunas guías ponen el límite en 5 y otras en 3mm). Y la primera prueba complementaria a realizar sería una biopsia endometrial. Si ya ésta no es determinante, se valorará realizar histeroscopia como 2ª opción.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-415545ea7cc2', 'e91b11084bff00c0b73985a7bf97d4715f141691', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Primigesta de 34 semanas que presenta cifras tensionales de 165/95 y cefalea de dos días de evolución. Analítica: hemoglobina 10,5 g/dL, plaquetas 98.000/mm3, AST 356 UI/L (0-31), ALT 234 UI/L (0-31), LDH 878 UI/L (125-243). Llaman del laboratorio por presencia de esquistocitos en el frotis de sangre periférica. Ha recibido la segunda dosis de corticoides para maduración fetal hace 24 h. En la ecografía obstétrica el peso fetal estimado está en el percentil 1 para la edad gestacional y el Doppler de arteria umbilical presenta ausencia del flujo telediastólico.', '¿Cuál de las siguientes es la actitud clínica más indicada?:', '[{"position": 1, "text": "Actitud expectante con antihipertensivos y sulfato de magnesio hasta la mejora de las plaquetas maternas."}, {"position": 2, "text": "Actitud expectante con tratamiento antihipertensivo a domicilio y controles cada 48 h."}, {"position": 3, "text": "Finalización de la gestación cuando complete la maduración pulmonar fetal."}, {"position": 4, "text": "Finalización inmediata de la gestación."}]'::jsonb, 4, 4, 'definitiva', 'Nos están describiendo un Sd de HELLP. Con esas semanas de gestación y con el feto recién madurado (ya tiene administrada las dos dosis de corticoides), la actitud es la finalización inmediata.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-617f53b2b8bc', 'c560998422d26df203d1e6c4f5d54b86f4b00170', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Mujer de 30 años que solicita un método anticonceptivo. Como antecedentes tiene una cesárea urgente hace 7 meses, naciendo una niña de 3.550 g. Está dando lactancia materna exclusiva.', 'Señale la afirmación correcta:', '[{"position": 1, "text": "Le explica que, si está en amenorrea, no requiere de otro método anticonceptivo puesto que la lactancia materna es suficiente como método anticonceptivo."}, {"position": 2, "text": "Le informa que el DIU de levonogestrel está contraindicado por haber tenido una cesárea hace menos de un año."}, {"position": 3, "text": "Le explica que podría usar un método hormonal de sólo gestágenos."}, {"position": 4, "text": "Le ofrece anticoncepción hormonal combinada."}]'::jsonb, 4, 3, 'definitiva', 'Dadas sus circunstancias y valorando ante todo que está en lactancia materna exclusiva, lo mejor sería pautarle sólo gestágenos.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-99a57f3a5def', '43f6ae62f96815656e575157364c83589ff9043c', NULL, NULL, NULL, false, false, 'Genética e Inmunología', 'Una mujer (Consultante) de 31 años de edad y asintomática, presenta gestación de 10 semanas según estudio ecográfico (primípara). Su hermano menor (caso índice) de 26 años está afecto de ataxia y diagnosticado genéticamente como portador heterocigoto de una mutación expansiva de 70 repeticiones CAG en el gen SCA3 (cromosoma 14). La Consultante se deriva a la consulta de consejo genético donde se valora una posible biopsia de corion para estudiar el genotipo fetal.', '¿está indicado este procedimiento invasivo como diagnóstico pre-natal (DPN) en este caso?', '[{"position": 1, "text": "Está indicado tras estudiar el genotipo de la Consultante y únicamente si éste es heterocigoto."}, {"position": 2, "text": "No está indicado, puesto que la ataxia SCA3 es de penetrancia completa y la Consultante está asintomática y por tanto no ha heredado la mutación."}, {"position": 3, "text": "Puede estar indicado en el siguiente embarazo, tras estudiar el genotipo del primer hijo y detectar la mutación en el mismo."}, {"position": 4, "text": "La ataxia SCA3 es de herencia recesiva, por lo que no existe riesgo apreciable de transmisión de la enfermedad y el DPN no está indicado."}, {"position": 5, "text": "Está indicado sea cual fuere el genotipo de la Consultante, pues la ataxia SCA3 es de herencia materna (transmitida por las mujeres)."}]'::jsonb, 5, 1, 'definitiva', 'La SCA3 es la Ataxia espinocerebelar tipo 3 también llamada enfermedad de Machado-Joseph. Se produce por mutaciones en el gen ATXN3 por el mecanismo de expansión de repetición de tripletes CAG. Los afectos tienen entre 52 y 86 repeticiones del triplete CAG en heterocigosis con penetrancia completa. El que tiene la mutación en heterocigosis padece la enfermedad pues su patrón de herecia es autosómico dominante. En este caso clínico el que padece la enfermedad y tiene el gen mutado en heterocigosis es el hermano (de 26 años) de la gestante. Pienso que antes de hacer la biopsia de corion habría que hacerle el estudio a la mujer gestante para conocer cual es su estatus en cuanto al gen ATXN3. Ella tiene un 50% por ciento de posibilidades de portar la mutación y de padecer la enfermedad, pero al tener 31 años pienso que ya debía haber tenido síntomas. No obstante, yo le haría el test genético a la gestante para curarme en salud. Si saliera sin mutación, no habría más que hacer porque ya no se transmitiría la enfermedad. Si saliera portadora de la mutación, entonces le haría la biopsia de corion. La respuestas 1 y 2 son ambas ciertas, pero creo que la respuesta 1 es más cierta que la 2.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4451ed181abf', '79ab7cf99695563e9829a31e1fa61dfea0f0a1ef', NULL, NULL, NULL, false, false, 'Oftalmología', 'Mujer de 68 años que utiliza para visión lejana gafas de +4,00 dioptrías en ambos ojos. Consulta porque desde hace unas semanas tiene dolor ocular con cefalea y visión borrosa por la noche cuando está viendo la televisión en penumbra.', '¿Cuál de las siguientes patologías es más probable que presente?', '[{"position": 1, "text": "Glaucoma por cierre angular primario."}, {"position": 2, "text": "Migraña."}, {"position": 3, "text": "Queratitis actínica."}, {"position": 4, "text": "Síndrome de ojo seco."}]'::jsonb, 4, 1, 'definitiva', 'Nos presentan una paciente de 68 años. A esa edad el cristalino, aunque normalmente no tiene una catarata que haya que operar, sí suele haber aumentado de grosor. Lo que implica que proyecta el iris hacia adelante y reduce la profundidad de la cámara anterior. En un ojo con una cámara anterior de profundidad normal no suele ser un problema. Pero las personas hipermétropes ya tienen de por sí una cámara estrecha. Esta es la combinación habitual que encontramos en el cierre angular primario: hipermetropía y una edad mayor de 50-60 años. Los hipermétropes jóvenes no suelen tener todavía este problema. Y las personas mayores emétropes, miopes u operados de catarata tampoco. Con este ángulo estrecho, lo que desencadena el cierre angulas es la midriasis. Es decir, cuando uno está en penumbra, la pupila se dilata y el iris se engruesa en la parte periférica, donde ya de por sí está muy cerca del endotelio corneal en caso de cámara estrecha. Entonces la midriasis desencadena el cierre angular, que cursa con dolor ocular que se puede irradiar hacia atrás (cefalea). Y el aumento de presión intraocular produce un edema corneal que causa visión borrosa. Por lo tanto, la opción 1 es la correcta. La migraña no tiene que tener relación con la penumbra, y el dolor ocular y la visión borrosa no es especialmente típico. La queratitis actínica se produce por exposición a radiación ultravioleta (como la solar), no tiene relación ni con la hipermetropía, ni con estar en penumbra. Además el antecedente de exposición suele ser claro. Y por último el ojo seco tampoco producen esos síntomas: se trata más de quemazón, sensación de cuerpo extraño, pesadez, etc. Y tampoco tiene relación con los demás elementos: la penumbra, la hipermetropía, etc. Como detalle menor, yo hubiera redactado un poco mejor la pregunta. Se sobreentiende que nos preguntan qué patología es la más probable en relación a los síntomas y la anamnesis. Pero tal como está redactado, nos preguntan por cuál de las patologías es más probable que presente, sin más. Realmente una mujer de 68 años es muy probable que tenga un ojo seco, al margen de que eso no le cause los síntomas por los que acude.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-af14585162e7', 'd751a2690be223f8187449237abf3613d32bbeba', NULL, NULL, NULL, false, false, 'Reumatología', 'Mujer de 79 años que ingresa por una fractura osteoporótica de cadera.', 'Respecto a la prevención secundaria de las fracturas por fragilidad, señale la respuesta INCORRECTA:', '[{"position": 1, "text": "La baja adherencia al tratamiento se asocia a un incremento del riesgo de fractura."}, {"position": 2, "text": "Los marcadores de remodelado óseo pueden ser útiles para monitorizar de forma precoz la respuesta al tratamiento."}, {"position": 3, "text": "La vitamina D en monoterapia es eficaz en la reducción de dichas fracturas en personas mayores no institucionalizadas."}, {"position": 4, "text": "El aumento de calcio dietético o tomar suplementos de calcio de forma aislada no protegen frente a la aparición de fracturas."}]'::jsonb, 4, 3, 'definitiva', 'Esta pregunta corresponde al apartado de traumatología, no obstante se podría contestar con los conocimientos de reumatología y con las recomendaciones de osteoporosis de la Sociedad Española de Reumatología. En la osteoporosis, uno de los principales riesgos asociados al incremento de riesgo de fractura es la baja adherencia al tratamiento, por lo que la respuesta 1 es correcta. La respuesta 2 se encuentra en la guía de la SER, en la que se confirma que algunos estudios concluyen que los marcadores de remodelado óseo pueden ser útiles para monitorizar de forma precoz el cumplimiento y la respuesta al tratamiento. La respuesta 4 es correcta ya que nuevamente en la guía de la SER 2019 citan textualmente: “La evidencia científica actual permite afirmar que ni aumentar el calcio dietético ni tomar suplementos de calcio de forma aislada protege frente a la aparición de fracturas”. Por ello la respuesta correcta a esta pregunta es la opción 3. Los pacientes en tratamiento farmacológico para la OP se deben utilizar suplementos de calcio y vitamina D porque prácticamente todos los ensayos clínicos que han demostrado eficacia de los fármacos antiosteoporóticos incluyen de forma rutinaria suplementos de calcio y colecalciferol (vitamina D3), pero no en monoterapia.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4497933e68d4', 'ab9e4908e17d527ad1a108aab9da22c0f1a875fa', NULL, NULL, NULL, false, false, 'Anestesiología y Reanimación', NULL, 'Paciente de 47 años de edad que consulta en el servicio de Urgencias por pérdida brusca de conciencia ¿Cuál de entre los siguientes tiene un mayor rendimiento diagnóstico?', '[{"position": 1, "text": "Historia clínica."}, {"position": 2, "text": "Electrocardiograma."}, {"position": 3, "text": "Registro Holter."}, {"position": 4, "text": "EEG."}, {"position": 5, "text": "TC de cráneo."}]'::jsonb, 5, 1, 'definitiva', 'Evidentemente, es la única respuesta que engloba todas las causas de pérdida de conciencia brusca y que nos permite filiar de alguna forma el diagnóstico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-a671c4d97a77', 'e8141594b342075eb9efe16f20d7197ee1c2e0b8', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Un hombre de 66 años de edad, refiere pirosis diaria desde la juventud que trata con alcalinos. Se le practica una endoscopia digestiva alta que muestra esofagitis erosiva leve y la unión escamosa columnar desplazada aproximadamente 7 cm. Respecto a la porción más proximal de los pliegues gástricos.', 'Las biopsias del esófago distal revelan que el epitelio escamoso normal ha sido reemplazado por epitelio columnar de tipo intestinal con displasia de bajo grado ¿Cuál es la opción más apropiada para el manejo de este paciente?', '[{"position": 1, "text": "Dado que la esofagitis es leve y la displasia de bajo grado, se aconseja continuar tratamiento con alcalinos."}, {"position": 2, "text": "Tratamiento indefinido con dosis altas de IBP ya que se ha demostrado que así se evita la progresión del esófago de Barrett a adenocarcinoma haciendo innecesaria la vigilancia endoscópica."}, {"position": 3, "text": "Endoscopias de vigilancia periódicas y tratamiento con IBP durante menos de 12 semanas ya que tratamientos prolongados se asocian a un alto riesgo de desarrollo de gastrinoma."}, {"position": 4, "text": "Endoscopias de vigilancia periódicas y tratamiento indefinido con IBP."}, {"position": 5, "text": "Esofaguectomía."}]'::jsonb, 5, 4, 'definitiva', 'Este paciente presenta un esófago de Barrett con displasia de bajo grado. No me gusta la pregunta, ya que al no estar con inhibición de producción ácida la displasia puede estar condicionada por la inflamación y no ser real. De todas formas, el esófago de Barrett debe seguir vigilancia endoscópica y tratamiento con IBP de por vida o cirugía antirreflujo para evitar evolución. La respuesta correcta es la 4.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7921b831c1e7', 'f140b025bb9302d1034477e9c6d1edd5da898081', NULL, NULL, NULL, false, false, 'Reumatología', 'Mujer de 70 años que refiere desde hace 1 mes dolor y rigidez en cinturas escapular y pelviana, que predomina al levantarse y mejora con la movilización, sin fiebre, cefalea ni afectación del estado general. En la exploración física se observa rigidez y dolor a la movilización de hombros y caderas. La analítica muestra una elevación de la VSG y la proteína C reactiva.', '¿Qué diagnóstico es más probable y qué tratamiento prescribiría?:', '[{"position": 1, "text": "Artritis reumatoide, iniciaría tratamiento con metotrexato."}, {"position": 2, "text": "Fibromialgia, iniciaría tratamiento con duloxetina."}, {"position": 3, "text": "Polimialgia reumática, iniciaría tratamiento con corticoides."}, {"position": 4, "text": "Espondilitis anquilosante, iniciaría tratamiento con antiinflamatorios no esteroideos."}]'::jsonb, 4, 3, 'definitiva', 'En este caso, nos esta describiendo los síntomas cardinales de la polimialgia reumática. Paciente mayor, por encima de los 50 años, que presenta dolor y rigidez en ambas cinturas, asociado a una elevación de los reactantes de fase aguda. Presenta los todos los criterios indispensables: edad igual o mayor a 50 años, omalgia bilateral y aumento de reactantes de fase aguda. De los criterios opcionales, presenta rigidez, dolor o limitación en cadera. El tratamiento inicial son corticoides a dosis medias.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-2f7d550ba680', '413f474263d9a1751d0930adbf466efc782cf70d', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Mujer de 61 años, administrativa, con antecedentes de sobrepeso, hipertensión, dislipemia y síndrome metabólico, que consulta por dolor en ambas nalgas, región trocantérea izquierda, cara lateral del muslo izquierdo hasta la rodilla y pierna izquierda hasta el tercio medio. El dolor aparece cuando levantamos el miembro inferior con la rodilla extendida, pero se alivia al flexionar la rodilla.', '¿Cuál es la primera sospecha clínica?:', '[{"position": 1, "text": "Artritis gotosa de cadera izquierda."}, {"position": 2, "text": "Artrosis coxofemoral izquierda."}, {"position": 3, "text": "Lumbalgia irradiada / lumbociatalgia."}, {"position": 4, "text": "Claudicación por estenosis de canal."}]'::jsonb, 4, 3, 'definitiva', 'Signo de Lasegue positivo, reaparición de la clínica al ejecutar la maniobra de extensión del miembro afectado, compatible con afectación de raíces nerviosas a nivel de columna lumbosacra.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-b675c815c02f', '85c7535577f0ced1b47521cd9dc9eaa8d23578b9', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Varón de 35 años, cartero, sin antecedentes de interés, que acude a urgencias por un dolor agudo cervical de 24 horas de evolución, sin traumatismo previo, que irradia a brazo izquierdo hasta la mano y se acompaña de parestesias en el borde radial del antebrazo. No presenta pérdida de fuerza objetivable, conserva la movilidad del cuello aunque es dolorosa y se aprecia contractura de la musculatura paravertebral.', 'La primera actitud será:', '[{"position": 1, "text": "Tratamiento conservador con antiinflamatorios no esteroideos, calor local y reposo relativo."}, {"position": 2, "text": "Llamada urgente al neurocirujano para valoración quirúrgica."}, {"position": 3, "text": "Solicitud preferente de resonancia magnética y electromiograma."}, {"position": 4, "text": "Derivación preferente a consultas externas de traumatología."}]'::jsonb, 4, 1, 'definitiva', 'Cervicalgia sin signos de alarma. Tratamiento conservador con un éxito entre el 75%-90%.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-a2b72e8f9968', '9c3efc7403318666afff64086515c9e9b526e3ef', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Varón de 27 años, deportista habitual, que refiere dolor en la pierna derecha tras la práctica de carrera continua. Ha acudido en varias ocasiones a un fisioterapeuta, siendo diagnosticado de una sobrecarga en gemelos. Han transcurrido varios meses, no ha mejorado y refiere dolor intenso tras la actividad física que cede con el reposo en las siguientes horas del ejercicio.', '¿Qué prueba puede ayudar en el diagnóstico?:', '[{"position": 1, "text": "Tomografía de emisión de positrones con 18 FDG."}, {"position": 2, "text": "Determinación de la presión del compartimento posterior inmediatamente tras actividad."}, {"position": 3, "text": "Ecografía-Doppler para descartar un trastorno circulatorio de la extremidad inferior."}, {"position": 4, "text": "Espectrometría por resonancia magnética."}]'::jsonb, 4, 2, 'definitiva', 'Nos presentan un caso de síndrome compartimental crónico. Para su diagnostica es necesario medir la presión de los compartimentos afectos en reposo y tras la actividad (respuesta 2 correcta).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f929b818115a', 'bd80ba8f3ff00d8ab0b1457dc1c32563ccbc30ce', NULL, NULL, NULL, false, false, 'Anestesiología y Reanimación', 'Un varón de 40 años, turista extranjero, es remitido a un Servicio de Urgencias por bajo nivel de conciencia, temperatura de 37.7ºC y disnea. No tiene traumatismos. Se realizan varias pruebas.', 'La más inmediata es una EAB sin oxígeno que muestra PH 7.33, PCO2 50, PO2 65, HCO3 27:', '[{"position": 1, "text": "TEP."}, {"position": 2, "text": "Neumonía lobar."}, {"position": 3, "text": "EAP."}, {"position": 4, "text": "Hipoventilación alveolar."}, {"position": 5, "text": "Bronconeumonía."}]'::jsonb, 5, 5, 'definitiva', 'Realmente, pueden ser todas, pero la causa más frecuente de una acidosis aguda respiratoria no compensada en una persona joven es la bronconeumonía.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-072d84c9d4de', '975c3a5e1776be8bbd611c960536354779da0840', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Mujer de 95 años que vive en una residencia, independiente para sus actividades básicas de la vida diaria, sale al jardín a pasear. Tiene antecedentes de HTA, dislipidemia, osteoporosis y deterioro cognitivo leve. Sufre una caída al levantarse por la noche al baño. La radiografía muestra una fractura subcapital desplazada de cadera derecha.', '¿Cuál es el tratamiento recomendado?:', '[{"position": 1, "text": "Hemiartroplastia de cadera."}, {"position": 2, "text": "Fijación con clavo trocantérico."}, {"position": 3, "text": "Fijación con tornillos canulados."}, {"position": 4, "text": "Conservador: vida cama-sillón."}]'::jsonb, 4, 1, 'definitiva', 'Nos hablan de un caso de una paciente de 95 años con fractura de cadera intracapsular (subcapital) desplazada. En este caso, las opciones quirúrgicas pueden ser el uso de tornillos canulados o artroplastia de cadera. Los tornillos canulados se reservan para casos de fracturas no desplazadas (Respuesta 2 incorrecta) por o que la opción más indicada sería la artoplastia, en este caso hemiartrioplastia (Respuesta 1 correcta). Las clavos trocantéricos se reservan para las fracturas extracapsulares (Respuesta 2 falsa) y el tratamiento conservador únicamente se plantea en pacientes con muy baja demanda funcional o contraindicación quirúrgica (Respuesta 4 incorrecta).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-ea4536088fac', 'a90604b545088a089bc8cf2c30e9433fda418774', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Varón de 41 años que consulta por gonalgia de varios días de evolución. En la exploración se realiza el test de Thessaly (dolor con los movimientos de rotación interna y externa con la rodilla flexionada) que resulta positivo.', '¿Cuál de las siguientes lesiones es más probable?:', '[{"position": 1, "text": "Lesión meniscal."}, {"position": 2, "text": "Lesión por rotura del ligamento cruzado anterior."}, {"position": 3, "text": "Lesión por rotura del ligamento cruzado posterior."}, {"position": 4, "text": "Lesión por artropatía degenerativa."}]'::jsonb, 4, 1, 'definitiva', 'Test de Thessaly. Test de provocación realizado en sospecha de lesión meniscal.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-aa26ed4ca7d5', '73f4e70cec6282320189435a9d6ea4e238cb2faa', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Mujer de 13 años, sin antecedentes relevantes, con menarquia hace 3 meses, seguida desde los 10 años por escoliosis idiopática que ha empeorado.', 'En la exploración física presenta una giba de 7 grados en el test de Adams y en el escoliograma una curva toracolumbar T4-L1 de 35 grados de Cobb y un Risser 0:', '[{"position": 1, "text": "Recomendar natación y revisión en tres meses."}, {"position": 2, "text": "Prescribir una ortesis tipo corsé."}, {"position": 3, "text": "Derivar a fisioterapia para elastificación del raquis."}, {"position": 4, "text": "Revisar en 6 meses con una nueva radiografía."}]'::jsonb, 4, 2, 'definitiva', 'Se puede plantear tratamiento con ortesis en Risser de 0 a 2 dado que aún queda crecimiento por darse y puede producirse la corrección. Su uso se plantea para curvas entre 30-40º.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4b19a3957d54', 'a630bbc7be445bdfc2a6a352c24c1d362f363143', NULL, NULL, NULL, false, false, 'Ciencias Básicas', 'Un albañil de 31 años acude al servicio de urgencias con una tenosinovitis producida por una herida penetrante. En la exploración se objetiva que la bolsa cubital está infectada con la consiguiente necrosis tendinosa.', '¿Qué tendón se verá afectado?', '[{"position": 1, "text": "Tendón del flexor cubital del carpo."}, {"position": 2, "text": "Tendón del abductor largo del pulgar."}, {"position": 3, "text": "Tendón del flexor profundo de los dedos."}, {"position": 4, "text": "Tendón del flexor radial del carpo."}, {"position": 5, "text": "Tendón del palmar largo."}]'::jsonb, 5, 1, 'definitiva', 'Tanto el flexor radial del carpo como el abductor largo del pulgar están anatómicamente lejos del cubital. El palmar largo es medial, así como el flexor profundo de los dedos. El tendón que va junto al nervio cubital, insertándose en el pisiforme, es el flexor cubital del carpo, por tanto respuesta 1.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos')
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('casimedicos-c92e805abaeb', '05f9a94d4d85aceed1a52e406cd0466dd3a24c5f', NULL, NULL, NULL, false, false, 'Anestesiología y Reanimación', 'Anciana que llevan sus vecinos a Urgencias porque la ven algo atontada y con manchas de deposición enla ropa. TA 100/60 mmHg, FC 100 lpm, sentada 70/30, FC 105 lpm. PVY normal. Respiración de Kussmaul. No focalidad neurológica. Peso de 50 kgrs. Lab: PH 7.25, PCO2 14, Bicarbonato 5, Na 133, K 2.5, Cl 118, Creat 3.4, NUS 60, Prot 8.', '¿Cuál de las siguientes respuestas es correcta?', '[{"position": 1, "text": "El trastorno ácido-base que presenta es una acidosis respiratoria."}, {"position": 2, "text": "La compensación para corregir la acidosis no es la adecuada."}, {"position": 3, "text": "Con esta exploración, descartamos que esté deshidratada."}, {"position": 4, "text": "En ningún caso, debemos ponerle bicarbonato."}, {"position": 5, "text": "Tiene una insuficiencia renal aguda de causa prerrenal."}]'::jsonb, 5, 5, 'definitiva', 'Estamos ante un caso de acidosis metabólica hiperclorémica con anión gap normal. La acidosis metabólica grave causa depresión contráctil del miocardio, reducción de la efectividad de las catecolaminas, mayor incidencia de arritmias, vasodilatación y aumento de la permeabilidad capilar, con la consiguiente reducción de flujo tisular, a nivel cerebral (que lleva a estados de confusión e, incluso, coma), a nivel renal, a nivel hepático… Es frecuente que estos pacientes presenten una taquipnea intensa (respiración de Kussmaul) en un intento de compensar la ACM mediante hiperventilación. Tenemos que tener en cuenta que, en este caso, el potasio está disminuido, por lo que la causa más frecuente (apoyada por las manchas del vestido) sería la diarrea, con lo que lo más probable es que su insuficiencia renal (a pesar de que no nos dan datos de iones en orina para poder confirmarlo)sea de tipo prerrenal. El tratamiento sería la reposición hidroelectrolítica y, en principio, salvo en el caso de que la paciente empeorase y el PH fuera menor de 7.10, no deberíamos administrar bicarbonato Con lo que la respuesta correcta es la 5.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-eb5292ff724f', '4f3a466f6a88ae6912dd80f4dd0b31b42f4b0bb7', NULL, NULL, NULL, false, false, 'Anestesiología y Reanimación', 'Un paciente varón de 45 años de edad con antecedentes de litiasis úrica con cólicos nefríticos expulsivos de repetición desde hace 25 años, acude a Urgencias refiriendo palpitaciones y dolor lumbar derecho intenso desde hace 2 horas antes. El análisis de orina muestra un PH de 5.5 y leucocituria sin proteinuria. El electrocardiograma confirma una FA no conocida previamente. En la bioquímica sanguínea destaca una Creat de 0.9, un Ca de 11 y una LDH de 950.', '¿Cuál es la maniobra diagnóstica más útil a realizar?', '[{"position": 1, "text": "Radiografía simple de abdomen."}, {"position": 2, "text": "Urografía intravenosa."}, {"position": 3, "text": "TC espiral con contraste."}, {"position": 4, "text": "Ecografía abdominal."}, {"position": 5, "text": "Ecografía doppler."}]'::jsonb, 5, 3, 'definitiva', 'En principio, lo que nos cuenta no cuaja con un cólico nefrítico. La orina es normal (sin hematuria, ocasionada por la litiasis al progresar), la Creat es normal (puede elevarse hasta 1.9 en cólicos nefríticos). El aumento de la LDH es inespecífico y lo podemos encontrar tanto en lesiones parenquimatosas hepáticas, como en IAM o en embolias pulmonares, además de en otros muchos casos menos frecuentes (tumores, miopatías, etc). En este caso, tenemos un factor de riesgo importante de embolismo, que es la fibrilación auricular, que, además, al ser un varón de 45 años, sin antecedentes, parece que no responde a una cardiopatía estructural de base unido a un dolor lumbar derecho, que podría corresponder a una irritación de la pleura a nivel. El TC espiral con contraste ha adquirido gran valor en el diagnóstico del TEP, debido a su rapidez y buena sensibilidad, superior al 83 – 92% en la mayor parte de los trabajos, y que según algunos puede llegar al 100% para trombos centrales, situados en arterias pulmonares principales, lobares o segmentarias. Su especificidad es mayor del 90%. Los ganglios pueden producir falsos positivos. Además puede proporcionar un diagnóstico alternativo en caso de no confirmarse el TEP, por lo que sería una prueba muy útil. El eco-doppler sería la prueba más útil para diagnosticar la fuente de los émbolos, así que también podría ser una respuesta válida dependiendo de lo que quieran decir con “útil”. Es una técnica no invasiva que ha demostrado su buena sensibilidad y especificidad en el diagnóstico de la TVP encomparación con la flebografía. Además permite diagnosticar otras patologías quepodrían justificar la clínica del paciente. Sus limitaciones son la valoración de trombosinfrapoplíteos y, en muchos casos, en pacientes que no son delgados, de las venas ilíacas y cava.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-563e67702c95', '2fd969c75b40027ef99997c5c69c33c0c4520089', NULL, NULL, NULL, false, false, 'Anestesiología y Reanimación', 'Un hombre de 64 años de edad con antecedentes de HTA y cardiopatía isquémica acude a Urgencias por aparición de dolor torácico opresivo mientras veía la televisión.', 'En la consulta de clasificación (triage) de Urgencias, se detectan cifras de T. art de 155/95 mmHg y una saturación capilar de O2 de 95% ¿Cuál es la conducta más correcta de las que a continuación se citan?', '[{"position": 1, "text": "Indicarle que vaya a la sala de espera. Le avisarán para realización de pruebas."}, {"position": 2, "text": "Este paciente debe ser atendido en el box de emergencia vital (cuarto de shock)."}, {"position": 3, "text": "Avisaremos al cardiólogo de guardia para la valoración del paciente."}, {"position": 4, "text": "Desde la consulta de Triage se le remitirá a la Unidad coronaria."}, {"position": 5, "text": "Le haremos un ECG en menos de 10 minutos."}]'::jsonb, 5, 5, 'definitiva', 'Si el ECG tiene cambios isquémicos, evidentemente, le atenderemos en el box de emergencia y avisaremos al cardiólogo. Si no, se le tratará como si fuera una angina y se observará, seriando enzimas y con tratamiento en el área de observación.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-bf3311965046', '9f008d82650e6a8ab6ab474604fcba19c7fa31df', NULL, NULL, NULL, false, false, 'Anestesiología y Reanimación', 'La hija de una anciana de 82 años nos consulta porque ha encontrado a su madre más confusa de lo normal. La paciente está diagnosticada de enfermedad de Alzheimer en grado moderado. Tiene además FA, depresión y artrosis. Su tratamiento estable desde hace 3 años, incluye digoxina, acenocumarol, fluoxetina desde hace 4 meses e ibuprofeno desde hace un mes por dolores articulares. A la exploración, su tensión es de 130/80, frecuencia cardiaca de 48 lpm y respiratoria de 10 rpm.', '¿Cuál de los siguientes es la causa más probable del aumento de confusión?', '[{"position": 1, "text": "Progresión del Alzheimer."}, {"position": 2, "text": "Empeoramiento de la depresión."}, {"position": 3, "text": "Intoxicación digitálica."}, {"position": 4, "text": "Demencia por cuerpos de Lewy."}, {"position": 5, "text": "Toxicidad por ibuprofeno."}]'::jsonb, 5, 3, 'definitiva', 'La causa más probable es una intoxicación digitálica, que produciría ese enlentecimiento de la conducción, que se ve en la frecuencia cardíaca. Probablemente secundario a una insuficiencia renal por toxicidad con ibuprofeno (pero esto ya es rizar el rizo).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d0f3083ea4c3', '8d2b3aa0a2e0848c2fc062c9037319354d913fef', NULL, NULL, NULL, false, false, 'Anestesiología y Reanimación', 'Una mujer de 30 años con AP de drogadicción en periodo actual de desintoxicación s traída a Urgencias con cuadro de somnolencia profunda, sin otra sintomatología. Logramos averiguar que en su tratamiento se incluye olanzapina y benzodiacepinas.', '¿Qué debemos hacer en primer lugar?', '[{"position": 1, "text": "Proceder a IOT."}, {"position": 2, "text": "Realizar una Rx de cráneo."}, {"position": 3, "text": "Administrar flumazenilo."}, {"position": 4, "text": "Administrar naloxona."}, {"position": 5, "text": "Esperar a que despierte."}]'::jsonb, 5, 3, 'definitiva', 'Se debe sospechar una sobreuso de los fármacos que toma. La olanzapina no tiene antídoto, por lo que,en principio, deberíamos antagonizar el efecto de las benzodiacepinas. Si la paciente continúa con somnolencia y no responde a estímulos, debemos proceder a intubar para asegurar la vía aérea.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-07a4e0f43211', 'd05598fac5343b78e9340c4363dfecf9e43ee8c6', NULL, NULL, NULL, false, false, 'Anestesiología y Reanimación', 'Hombre de 72 años, exfumador, hipertenso y diabético. Antecedentes de ictus con paresia residual en brazo izquierdo hace 4 messes. Acude al servicio de Urgencias de un hospital comarcal con dolor precordial intenso de 2 horas de evolución; en la exploración física presenta piel fría y sudorosa, tensión arterial de 80 mm Hg; electrocardiograma con elevación marcada del segmento ST en las derivaciones V1-V6, I y aVL.', '¿Cuál de los siguientes tratamientos de repercusión coronaria es el mas adecuado?', '[{"position": 1, "text": "Fibrinolisis sistémica de forma inmediata en el hospital comarcal."}, {"position": 2, "text": "Traslado inmediato a un centro terciario para tratamiento con fibrinolisis."}, {"position": 3, "text": "Traslado inmediato a un centro terciario para procedimiento de revascularización coronaria percutánea."}, {"position": 4, "text": "Estabilización hemodinámica y procedimiento de revascularización diferido."}, {"position": 5, "text": "Tratamiento inmediato con fondaparinux y abciximab."}]'::jsonb, 5, 3, 'definitiva', 'En esta pregunta se conjugan varios datos importantes. Para empezar, se trata de un paciente con un IAM anterior y lateral extenso, con shock cardiogénico. Por otro lado dentro de los antecedentes, nos dicen que el paciente tuvo un ictus hace 4 meses. Es evidente por el cuadro clínico del paciente que está indicada una estrategia de reperfusión urgente, esto invalida las opciones 4 y 5. La cuestión basica es si elegir fibrinolisis (la cual puede hacerse en un hospital comarcal) o ICP (para lo cual debe ser derivado a un centro terciario). La opción 2 no tiene mucho sentido, puesto que en el caso de que estuviera indicada la fibrinolisis no sería mas que una pérdida de tiempo realizar el traslado. El antecedente de ictus (se supone que isquémico) hace 4 meses es una contraindicación relativa de fibrinoisis (si el tiempo es menor de 3 meses es contraindicación absoluta), pero lo definitivo que inclina la balanca hacia la ICP es la extensión del IAM y la presencia de shock, que son indicaciones de ICP urgente. Por tanto la respuesta correcta es la 3.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-af42362da937', '7674daaf42aa5a7525e4f2883b78df85040cc974', NULL, NULL, NULL, false, false, 'Anestesiología y Reanimación', 'Un hombre de 37 años sin antecedentes de interés acude a urgencias por haber sufrido un síncope mientras caminaba. Había comenzado dos días antes con disnea de esfuerzo. Exploración: peso 75 Kg, TA 75/50 mm Hg. SatO2 89%. Auscultación pulmonar normal. Auscultación cardiaca: tonos rítmicos taquicárdicos a 130 lpm. Abdomen normal. Extremidades: sin alteraciones. Hemograma normal. Troponina 1,2 ng/ml. ECG: Taquicardia sensual a 130 lpm. T invertida en V1-V4. Angio TC torácico: defecto de repleción en ambas arterias pulmonares principales. Una hora después de su llegada a urgencias persiste TA 70/55 mm Hg.', 'Cual sería el tratamiento inicial mas adecuado?', '[{"position": 1, "text": "Heparina no fraccionada, 10.000U iv ante la sospecha clínica. Fibrinolisis con tPA 100 mg iv una vez confirmado el diagnóstico."}, {"position": 2, "text": "Enoxaparina: 80 mg sc cada 12 horas, comenzando ante la sospecha diagnóstica."}, {"position": 3, "text": "Enoxaparina; 80 mg sc cada 12 horas, comenzando ante la confirmación diagnóstica."}, {"position": 4, "text": "Fondaparinux: 7,5 mg sc diarios."}, {"position": 5, "text": "Tromboendarterectomía pulmonar de urgencia."}]'::jsonb, 5, 1, 'definitiva', 'El caso clínico es un Tromboembolismo Pulmonar típico. En este caso asociado a hipotensión arterial persistente. La opción 2 sería correcta si el paciente no estuviese hipotenso. La opción 3 no es correcta dado que no es necesaria confirmación diagnóstica para iniciar el tratamiento anticoagulante en caso de TEP sin hipotensión. La opción 4 no está indicada. La opción 5 sería correcta solo si el paciente tuviese contraindicación de fibrinolisis. La hipotensión persistente en el TEP es la indicación mas ampliamente aceptada de fibrinolisis, por lo que la opicón correcta es la 1.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-ae01d6c5d9d0', '68e63e19496ee476a2a67f2294cc9fccd025dfcf', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Un muchacho de 17 años de edad con enfermedad de Crohn con afectación colónica de 2 años de evolución, en tratamiento de mantenimiento con azatioprina, consulta por la aparición desde hace 5 días de nódulos subcutáneos rojo violáceos, calientes, dolorosos, de localización pretibial, bilaterales asociada a un incremento del número de deposiciones y dolor abdominal.', 'La actitud más adecuada en este caso es:', '[{"position": 1, "text": "Recomendar reposo relativo y paños calientes en ambas piernas y añadir tratamiento antidepresivo."}, {"position": 2, "text": "Biopsiar zonas de piel alejados de las áreas lesionadas y pautar analgésicos opioides de entrada."}, {"position": 3, "text": "Biopsiar zonas de piel alejados de las áreas lesionadas y pautar analgésicos opioides de entrada."}, {"position": 4, "text": "Sospechar isquemia bilateral de extremidades inferiores de origen medicamentoso."}, {"position": 5, "text": "Ajuste del tratamiento de la enfermedad."}]'::jsonb, 5, 5, 'definitiva', 'Parece que el paciente tiene lesiones de eritema nodoso asociado a un brote de su enfermedad, cosa que es habitual. El tratamiento de la enfermedad y su control suele mejorar las lesiones cutaneas. No se debe biopsiar las lesiones.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7944c182a27a', '57e99485bc35ed35e30db8fc731a3274f7415531', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Una mujer de 55 años, postmenopáusica, consulta por astenia y disnea de esfuerzo. En la anamnesis refería ligera epigastralgia y pirosis ocasional. No metrorragias. En la analítica: Hb6 gr/dL, VCM 69 fl, sideremia 13 microgramos/dL, ferritina 4 ngr/mL. Endoscopia digestiva alata: pequeña hernia hiatal por deslizamiento sin signos de esofagitis.', '¿Cuál es la actitud más correcta?', '[{"position": 1, "text": "Administrar hierro oral y ver evolución de la anemia."}, {"position": 2, "text": "Tratar con inhibidores de la bomba de protones y evaluar a los tres meses."}, {"position": 3, "text": "Recomendar una colonoscopia completa."}, {"position": 4, "text": "Realizar un estudio con cápsula endoscópica."}, {"position": 5, "text": "Solicitar una evaluación ginecológica."}]'::jsonb, 5, 3, 'definitiva', 'Tenemos un caso de anemia ferropénica crónica, sin sangrado evidente. La primera causa de anemia ferropénica es el sangrado oculto de origen digestivo. La existencia de clínica sugestiva de patología del tracto digestivo superior ha hecho que se comience el estudio con endoscopia digestiva alta, pero no presenta patología que justifique la anemia por lo que se debe seguir investigando, lo que descarta las respuestas 1 y 2. Entre la 3 y la 4, las lesiones de intestino grueso son mucho más habituales y deben descartarse antes de las de intestino delgado. De hecho las recomendaciones de cápsula endoscópica en estudio de anemia son restringidos.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-6970e7395ae9', '50848e5cfeae760810d3a2cc54f711055e35e835', NULL, NULL, NULL, false, false, 'Aparato Digestivo', NULL, 'Cuál de los siguientes datos clínicos, registrados durante la realización de la historia clínica de un paciente con diarrea de más de 4 semanas de evolución, puede ser encontrado en personas sin patología orgánica:', '[{"position": 1, "text": "Pérdida de peso con o sin rectorragia."}, {"position": 2, "text": "Persistencia de la diarrea durante la noche."}, {"position": 3, "text": "Inicio de los síntomas después de los 50 años."}, {"position": 4, "text": "Presencia durante la exploración de dermatitis y/o artritis."}, {"position": 5, "text": "Expulsión de moco en más del 25% de las defecaciones."}]'::jsonb, 5, 5, 'definitiva', 'Aunque el moco suele asustar algo más en la consulta, entra dentro de los criterios de Roma II para el diagnóstico de Síndrome de Intestino Irritable. Todos los demás son signos de organicidad típicos, aunque creo que a pregunta está mal enunciada, ya que cualquiera de esos datos (sobre todo la edad) se pueden encontra en pacientes que al final no tienen nada, lo que pasa es que en esos casos hay que buscar organicidad siempre.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c9a33f2ace39', '495982494c216e5ff3cd98e10f68ade7e878655c', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Hombre de 52 años que consulta por una segunda opinión sobre la necesidad de realizarse biopsia hepática para estudio de hipertransaminasemia detectada desde hace dos años en análisis rutinarios de empresa. Entre sus antecedentes familiares destaca el fallecimiento de su padre de una cirrosis epatica de etiologíaa no filiada. Asintomático y realizando vida social y laboral sin límitaciones. Niega consumo de alcohol. En la exploración física destaca pigmentación metálica de piel y mínima hepatomegalia no dolorosa. Resto de la exploración física normal, índice de masa corporal 23. Aporta analítica con los siguientes resultados: billirrubina, albúmina, transaminasas AST y ALT, hemograma y tiempo de protrombina normales: glucemia 150 mg/dl; ferritina sérica 950; saturación de trasferrina >45%.Estudio de virus hepatotropos negativo. Ecografía abdominal normal. Le han realizado estudio genético HFE siendo homocigoto para la mutación C282Y.', '¿Cuál sería la recomendación más acertada con a información disponible?:', '[{"position": 1, "text": "Realizar biopsia hepática."}, {"position": 2, "text": "Realizar resonancia magnética hepática."}, {"position": 3, "text": "Iniciar tratamiento con flebotomías."}, {"position": 4, "text": "Iniciar tratamiento con desferroxamina."}, {"position": 5, "text": "Iniciar tratamiento con Vitamina E."}]'::jsonb, 5, 3, 'definitiva', 'Es un paciente que ya tiene diagnóstico de hemocromatosis, por estudio genético positivo y datos de sobrecarga férrica (IST >45% y ferritina elevada). La biopsia nos serviría si el diagnóstico es incierto o si quisieramos valorar afectación hepática que no se sospecha con esa analítica. El tratamiento de elección son las flebotomías.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c939713b997e', '1f4eff7711a8f892cb4b861ba82765f8ac367e46', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Un hombre de 60 años de edad refiere dolor precordial tras los medianos esfuerzos. La coronariografía muestra estenosis significativa en los segmentos proximales de los tres vasos principales con buen lecho distal. La función ventricular está deprimida (<30%).', '¿Cuál es la mejor opción terapéutica?', '[{"position": 1, "text": "Revascularización percutánea."}, {"position": 2, "text": "Tratamiento médico."}, {"position": 3, "text": "Cirugía de revascularización miocárdica."}, {"position": 4, "text": "Implantar balón de contrapulsación."}, {"position": 5, "text": "Trasplante cardiaco."}]'::jsonb, 5, 3, 'definitiva', 'Nos hablan de un paciente con enfermedad coronaria en 3 vasos y, muy importante, con disfunción ventricular severa. En estas condiciones, el tto. de elección sería quirúrgico (cirugía de revascularización miocárdica o by-pass). En el caso de que nos hubieran hablado de un paciente con función del VI conservada, el elegir el tto. quirúrgico vs. percutáneo sería más cuestionable, pues hoy en día gracias a los stents farmacoactivos las diferencias en términos de morbimortalidad entre la cirugía de by-pass y la angioplastia son mínimas.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7ec22ff4aace', '61ba9b79b822159c86d9f0aab94fe09c838a4466', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, '¿Qué intervención terapéutica consideraría en un paciente de 67 años con miocardiopatía dilatada idiopática, bloqueo de rama izquierda, fracción de eyección del ventrículo izquierdo de 26%, insuficiencia mitral grado II-III/IV, sometido a tratamiento con furosemida, espironolactona, enalapril y bisoprolol y que se mantiene en clase funcional III de la NYHA?', '[{"position": 1, "text": "Revascularización coronaria quirúrgica."}, {"position": 2, "text": "Reemplazo valvular mitral."}, {"position": 3, "text": "Implante de un balón aórtico de contrapulsación."}, {"position": 4, "text": "Implante de un dispositivo de asistencia ventricular."}, {"position": 5, "text": "Implante de un sistema de resincronización cardiaca."}]'::jsonb, 5, 5, 'definitiva', 'Nos están hablando de un paciente con una insuficiencia cardiaca con disfunción VI severa (FE < 35%), BRIHH (QRS ancho), que sigue un tto. médico óptimo y que se mantiene en clase funcional avanzada a pesar de ello. La revascularización coronaria no parece que vaya a aportar mucho en este paciente en este momento. El reemplazo valvular mitral tampoco, primero porque lo más probable es que la insuficiencia mitral sea a consecuencia de la dilatación del anillo mitral, y segundo porque necesitaríamos de una valoración ecocardiográfica de dicha válvula para saber si presenta alguna alteración. El implante del balón de contrapulsación intraaórtico no estaría indicado en este paciente (se utiliza en situaciones de shock cardiogénico, en complicaciones mecánicas post-IAM, como puente al Tx cardiaco…). El dispositivo de asistencia ventricular tampoco estaría indicado en este paciente. Lo que verdaderamente le beneficiaría de todas las respuestas es la 5, el dispositivo de resincronización. Al conseguir una estimulación simultánea de ambos ventrículos, se consigue una sinergia mecánica que mejora la función cardiaca. Las indicaciones de aplicación de una TRC (terapia de resincronización cardiaca) son precisamente las comentadas al principio: Disfunción ventricular severa, asincronía demostrada por la presencia de QRS ancho en el ECG (habitualmente por un BRIHH) y clase funcional avanzada (III-IV) a pesar de un tto. médico óptimo.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-0476fe788011', '287e018691b8b59e84716cd36757d7241f8bb1c2', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Hombre de 75 años, hipertenso y dislipémico con antecedentes de insuficiencia cardiaca por disfunción sistólica del ventrículo izquierdo (FE < 30%). Acude a nuestra consulta por empeoramiento de su disnea habitual en las últimas semanas. Su tensión arterial sistólica es de 160/95 mmHg con frecuencia cardiaca de 65 lpm. En la exploración física no se auscultan crepitantes y su presión venosa yugular es normal. Aporta una determinación de creatinina que es de 3.7 mg/dL con iones dentro de la normalidad.', '¿Cuál de los siguientes fármacos es el más adecuado para mejorar el pronóstico de su insuficiencia cardiaca?', '[{"position": 1, "text": "Enalapril."}, {"position": 2, "text": "Losartán."}, {"position": 3, "text": "Espironolactona."}, {"position": 4, "text": "Bisoprolol."}, {"position": 5, "text": "Eplerenona."}]'::jsonb, 5, 4, 'definitiva', 'Ante un paciente con múltiples FRCV con insuficiencia cardiaca y renal concomitante (presumiblemente de etiología múltiple: hipoperfusión renal, arteriosclerosis…), debemos ser muy cuidadosos a la hora de emplear diuréticos e IECA/ARA-II, pues podemos empeorar la función renal y/o elevar las cifras de potasio (dentro de los diuréticos, la espironolactona y la eplerenona son “ahorradores de potasio”). Por tanto, en este caso utilizaremos el bisoprolol.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-950475133b5c', '1dfc1778d7533b5937c16f24cb598f0a2d702385', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Un paciente con antecedentes de cuadro febril y dolor torácico acude al hospital con disnea y taquipnea. En la exploración física las cifras de presión arterial están bajas, la presión yugular venosa está elevada con un seno “X” descendente profundo y tiene pulso paradójico.', '¿Qué patología debe sospechar?', '[{"position": 1, "text": "Cardiopatía isquémica."}, {"position": 2, "text": "Miocardiopatía dilatada."}, {"position": 3, "text": "Estenosis valvular aórtica severa."}, {"position": 4, "text": "Pericarditis constrictiva."}, {"position": 5, "text": "Derrame pericárdico con taponamiento cardiaco."}]'::jsonb, 5, 5, 'definitiva', 'El pulso paradójico es un descenso de la presión arterial > 10 mmHg durante la inspiración; representa una exageración del fenómeno fisiológico consistente en el descenso inspiratorio de la TA (normal hasta 10 mmHg). En el taponamiento cardiaco, la inspiración, que provoca un incremento del aflujo sanguíneo a las cavidades derechas, aumentando el volumen de las mismas, provoca de forma secundaria un desplazamiento del tabique interventricular hacia la izquierda, de tal modo que el corazón izquierdo aloja y expulsa menos sangre durante la sístole y el pulso, por tanto, disminuye. En un corazón normal no se da este desplazamiento exagerado, provocado por la presión que ejerce el taponamiento sobre la pared libre del VD. El seno X representa el colapso sistólico del pulso venoso, es decir, la caída de presión por la relajación auricular (también en parte por un desplazamiento hacia abajo de la base del VD durante el período de sístole). El seno Y representa el colapso diastólico del pulso venoso, es decir, la caída de presión que tiene lugar desde el momento en que la sangre penetra por la válvula tricúspide hacia el ventrículo. En el taponamiento cardiaco lo característico es el seno X profundo. En la pericarditis constrictiva, el seno Y profundo. Por todas estas razones, la respuesta correcta es la 5.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8a208b9fe5c1', 'bc1ff17bea06d6e2e5bfa81f2dccee8a9773266b', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Un hombre de 26 años sin antecedentes de interés, asintomático, presenta en una revisión un soplo mesosistólico en foco aórtico y borde paraesternal izquierdo que aumenta con la maniobra de Valsalva. La TA y los pulsos periféricos son normales y el ECG muestra signos de marcado crecimiento ventricular izquierdo y ondas T negativas muy profundas en V3, V4, V5 y V6.', '¿Cuál es el diagnóstico más probable?', '[{"position": 1, "text": "Soplo funcional."}, {"position": 2, "text": "Estenosis aórtica."}, {"position": 3, "text": "Insuficiencia aórtica."}, {"position": 4, "text": "Miocardiopatía hipertrófica."}, {"position": 5, "text": "Comunicación interventricular."}]'::jsonb, 5, 4, 'definitiva', 'Un paciente varón, joven, con un soplo sistólico aórtico que aumenta con la maniobra de Valsalva y signos de crecimiento ventricular izquierdo supone prácticamente un “retrato” de los hallazgos típicos que podemos encontrar en la miocardiopatía hipertrófica. Pregunta muy fácil.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8c3d22c38b3d', '671541a4a5f049ae2952d60496a6b64682a1f065', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Una mujer de 78 años con antecedentes de hipertensión arterial en tratamiento con amlodipino ingresó hace 3 meses por debut de insuficiencia cardiaca y fibrilación auricular. Acude a su consulta para revisión cardiológica. El informe de alta muestra el resultado del ecocardiograma que evidencia disfunción ventricular izquierda moderada y el tratamiento al alta: se suspendió el amlodipino y se inició furosemida y enalapril. La paciente refiere encontrarse mejor, sin cansancio y con menos edema de piernas, pero todavía no está bien del todo. A la exploración física comprueba que no existen signos de insuficiencia cardiaca pero llama la atención unas cifras de presión arterial y frecuencia cardiaca de 150/90 mmHg y 120 lpm, respectivamente. El ECG muestra una fibrilación auricular a 110-120 lpm.', '¿Qué tratamiento tiene más probabilidades de mejorar los síntomas y reducir la mortalidad por eventos cardiovasculares?', '[{"position": 1, "text": "Digoxina y ácido acetilsalicílico."}, {"position": 2, "text": "Atenolol y ácido acetilsalicílico."}, {"position": 3, "text": "Verapamilo y acenocumarol."}, {"position": 4, "text": "Carvedilol y acenocumarol."}, {"position": 5, "text": "Carvedilol y clopidogrel."}]'::jsonb, 5, 4, 'definitiva', 'Típica pregunta muy larga y farragosa pero que en realidad no es demasiado complicada… La paciente está en insuficiencia cardiaca con disfunción ventricular moderada y además presenta fibrilación auricular; tiene criterios de anticoagulación, y entre las dos opciones que incluyen el acenocumarol nos inclinamos por la 4, puesto que incluye el carvedilol, un fármaco que ha demostrado aumentar la supervivencia en la insuficiencia cardiaca. El verapamilo (y los calcioantagonistas en general) están contraindicados en la insuficiencia cardiaca sistólica: no aumentan la supervivencia (incluso aumentan la morbimortalidad) y concretamente los no dihidropiridínicos (verapamilo y diltiazem) no se deben asociar a betabloqueantes por el riesgo aumentado de bloqueo del sistema de conducción.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-360603704030', '1eb0b54d7f5492268297dcd0b4796f7c4fc719ae', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Hombre de 64 años que consulta por dolor en la pantorrilla derecha cuando sube cuestas y escaleras y cuando anda en llano durante un tiempo prolongado. Refiere que el dolor se hace tan intenso con el esfuerzo que le obliga a pararse, lo que hace que el dolor mejore en cuestión de minutos. Como antecedentes personales, destaca que el paciente es fumador de 20 cigarrillos al día, diabético en tratamiento con metformina e hipertenso. A la exploración, se objetiva una buena perfusión periférica del pie derecho, pero presenta un pulso pedio disminuido.', '¿Qué prueba complementaria, entre las siguientes, debe solicitar inicialmente para el diagnóstico y valoración de la gravedad de la enfermedad de este paciente?', '[{"position": 1, "text": "Arteriografía de extremidades inferiores."}, {"position": 2, "text": "Índice tobillo-brazo."}, {"position": 3, "text": "Tomografía axial computerizada con reconstrucción vascular de extremidades inferiores."}, {"position": 4, "text": "Prueba de esfuerzo en cinta."}, {"position": 5, "text": "Resonancia magnética."}]'::jsonb, 5, 2, 'definitiva', 'Aunque el diagnóstico de las arteriopatías periféricas es fundamentalmente clínico (en este paciente el cuadro es muy típico), podemos valorar de forma objetiva la gravedad de la enfermedad con el uso de técnicas incruentas. La más importante es el índice tobillo-brazo. Por tanto, respuesta 2 correcta. Las técnicas de imagen (arteriografía, angioTC o angioRM) se utilizan cuando se considera la reparación quirúrgica de la oclusión arterial.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-12a61138ebe5', '8936833875f6c81d2ef466efc36bacb051ea1f66', NULL, NULL, NULL, false, false, 'Cirugía General', 'Una mujer de 35 años es diagnosticada de cáncer de colon localizado en ángulo hepático. Presenta antecedentes familiares de cáncer de colon en madre, una tía a la edad de 45 años y un abuelo.', 'La intervención quirúrgica más aceptada es:', '[{"position": 1, "text": "Hemicolectomía derecha."}, {"position": 2, "text": "Hemicolectomía derecha ampliada."}, {"position": 3, "text": "Colectomía subtotal."}, {"position": 4, "text": "Colectomía total con anatomosis ileorrectal."}, {"position": 5, "text": "Colectomía total con anatomosis ileoanal."}]'::jsonb, 5, 4, 'definitiva', 'El enunciado con los antecedentes familiares indica que se trata de una caso de cáncer colorrectal hereditario no polipósico (Síndrome de Lynch). Los datos de edad y localización derecha nos enfocan a la respuesta 4 colectomía total con anastomosis ileorrectal. Si se realiza una cirugía convencional tipo hemicolectomía derecha las posibilidades de recidiva son superiores al 30%. La extirpación del recto no es necesaria profilácticamente.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7c4372001625', 'cd4f45b62c2a26a2bb1f888cc594f8bf22390e05', NULL, NULL, NULL, false, false, 'Cuidados Paliativos', 'Paciente de 60 años diagnosticada de neoplasia de mama hace 10 años. Realizó tratamiento con radioquimioterapia y posteriormente hormonal durante 5 años. Un estudio con gammagrafía ósea realizado por dolores óseos politópicos demostró la presencia de metástasis óseas. Actualmente está en y tratamiento con opioides menores y AINEs con buen control del dolor. Acude a consulta por cefalea que no cede con la actual analgesia realizando una TC cerebral que muestra imágenes compatibles con metástasis cerebrales.', 'En relación al tratamiento del dolor indique la CORRECTA:', '[{"position": 1, "text": "Se debe cambiar a opioides mayores."}, {"position": 2, "text": "Se deben administrar las dosis extras de opioides que sean necesarias."}, {"position": 3, "text": "Se deben añadir corticoides."}, {"position": 4, "text": "Se debe cambiar a un opioide mayor y mantener los AINEs."}, {"position": 5, "text": "Se debe ingresar al paciente para tratamiento endovenoso con opioide mayor."}]'::jsonb, 5, 3, 'definitiva', 'Las metástasis cerebrales producen dolor por un cuadro de hipertensión craneal. El tratamiento de elección son los corticoides. De elección la dexametasona en dosis oral de 4 a 16 mg/día.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-a35e903c0105', '47fa74291afb1efd903c8c2ec00148fca337fdc8', NULL, NULL, NULL, false, false, 'Dermatología', 'Un muchacho de 17 años de edad con enfermedad de Crohn con afectación colónica de 2 años de evolución, en tratamiento de mantenimiento con azatioprina, consulta por la aparición desde hace 5 días de nódulos subcutáneos rojo violáceos, calientes, dolorosos, de localización pretibial, bilaterales, asociada a un inrcemento del nº de deposiciones y dolor abdominal.', 'La actitud más adecuada en este caso es:', '[{"position": 1, "text": "Recomendar reposo relativo y paños calientes en ambas piernas y añadir tratamiento antidepresivo."}, {"position": 2, "text": "Biopsiar zonas de piel alejados de las áreas lesionadas y pautar analgésicos opioides de entrada."}, {"position": 3, "text": "Sospechar la existencia de una lesión tumoral maligna intestinal como desencadenante del proceso cutáneo."}, {"position": 4, "text": "Sospechar isquemia bilateral de extremidades inferiores de origen medicamentoso."}, {"position": 5, "text": "Ajuste del tratamiento de la enfermedad intestinal."}]'::jsonb, 5, 5, 'definitiva', 'El cuadro que presenta el paciente es, presumiblemente, un eritema nodoso. Alrededor del 10% de casos de eritema nodoso se asocian con enfermedad inflamatoria intestinal, tanto colitis ulcerosa como enfermedad de Crohn. Como se ha mencionado, en la mayoría de casos, el eritema nodoso tiene un curso autolimitado. Cuando se asocia con enfermedad inflamatoria intestinal, el eritema nodoso habitualmente se resuelve con el tratamiento del brote intestinal, y recurre con las recidivas de la enfermedad. Las medidas locales incluyen la elevación de las piernas y el reposo en cama. En casos particularmente intensos, la administración por vía oral de yoduro potásico se ha demostrado útil. Aunque el uso de aspirina y otros AINE es eficaz para el eritema nodoso, su uso en pacientes con enfermedad inflamatoria intestinal debe limitarse, ya que pueden empeorar el cuadro intestinal, no se ha descrito la utilidad de antidepresivos en este cuadro, por lo que la respuesta nº1 no sería correcta.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-16a8514fc014', '1239c41673f9a7cbf19d7077e48142b0440b2b0e', NULL, NULL, NULL, false, false, 'Dermatología', 'Enfermo de 60 años que refiere hace 10 días la aparición de lesiones ampollosas en dorso de manos después de exposición solar. El cuadro se acompaña de fragilidad cutánea. Histopatológicamente existe una ampolla subepidérmica con depósitos PAS+ en y alrededor de los vasos dérmicos superficiales.', 'El diagnóstico más verosímil es:', '[{"position": 1, "text": "Pénfigo benigno familiar."}, {"position": 2, "text": "Penfigoide."}, {"position": 3, "text": "Porfiria cutánea tarda."}, {"position": 4, "text": "Pénfigo vulgar."}, {"position": 5, "text": "Síndrome de la piel escaldada."}]'::jsonb, 5, 3, 'definitiva', 'El hecho de ser un cuadro fotoinducido, la histología y por la edad hacen más probable el diagnóstico de PCT (3). El resto no cuadran con el cuadro clínico ni con la histología.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-69ad759d908f', '382371454ab3e516db58bdde37fed7d0053ced56', NULL, NULL, NULL, false, false, 'Dermatología', 'Paciente que presenta desde hace 2 semanas una erupción pruriginosa constituida por múltiples pápulas eritemato-violáceas poligonales, de superficie aplanada, localizadas preferentemente en la cara anterior de muñecas, zona pretibial y área lumbar. Además presenta lesiones reticuladas blanquecinas en mucosa yugal,', '¿Cuál es el diagnóstico más probable?', '[{"position": 1, "text": "Pitiriasis versicolor."}, {"position": 2, "text": "Micosis fungoides."}, {"position": 3, "text": "Psoriasis en gotas."}, {"position": 4, "text": "Pitiriasis rosada de Gibert."}, {"position": 5, "text": "Liquen plano."}]'::jsonb, 5, 5, 'definitiva', 'Nos están describiendo sin lugar a dudas las típicas lesiones (tanto en piel como en mucosa oral) de un liquen plano (5).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8ecb766469f4', '4712b0cb6d71104efafdc4f6cf11c350cd4fd94c', NULL, NULL, NULL, false, false, 'Endocrinología', 'Un paciente diabético de 60 años consulta por primera vez respecto al tratamiento de su enfermedad.', '¿Qué objetivo a alcanzar de los siguientes le recomendaría en primer lugar?', '[{"position": 1, "text": "Mantener la tensión arterial por debajo de 110/70 mmHg."}, {"position": 2, "text": "Abandono del hábito tabáquico."}, {"position": 3, "text": "Mantener un índice de masa corporal (IMC) menor de 21."}, {"position": 4, "text": "Realizarse glucemia capilar basal a diario."}, {"position": 5, "text": "Evitar grasas animales en la dieta."}]'::jsonb, 5, 2, 'definitiva', 'El resto no son indicaciones. El objetivo de TA es < 130/85 mmHg.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f19eac758fcd', 'b6dc4d09b6e1ae7c4c486e45e542e2078a1ce51a', NULL, NULL, NULL, false, false, 'Cirugía General', 'Un paciente de 87 años con antecedentes de bronquitis crónica e insuficiencia cardiaca, ha sido diagnosticado de colecistitis aguda litiásica. Tras cuatro días de tratamiento con dieta absoluta, sueroterapia y piperaciliana /tazobactam, el paciente continua con fiebre, dolor abdominal persistente y leucocitosis.', 'La actitud más adecuada en este momento sería:', '[{"position": 1, "text": "Tratamiento quirúrgico (colecistectomía urgente)."}, {"position": 2, "text": "Drenaje biliar mediante colecistostomía percutánea."}, {"position": 3, "text": "Sustituir la piperaciliana /tazobactam por metronidazol+cefotaxima."}, {"position": 4, "text": "Sustituir la piperaciliana /tazobactam por amikacina+clindamicina."}, {"position": 5, "text": "Añadir gentamicina."}]'::jsonb, 5, 2, 'definitiva', 'Creo que la respuesta correcta es la 2 aunque el tratamiento de la colecistitis aguda es la colecistectomía, para esto es necesario que el paciente sea un candidato quirúrgico, en este caso se trata de una paciente anciano, con enfermedades previas que aumentan el riesgo quirúrgico y sería un ASA IV para una intervención urgente. En estos casos la colecistostomía puede curar la colecistitis; y tras la recuperación, valorar la cirugía programada según la situación del paciente.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-770a18d4bbcf', '2db317af35953c21a167b24d5798a345451db318', NULL, NULL, NULL, false, false, 'Genética e Inmunología', 'Una niña de 8 años (caso índice) está diagnosticada clínicamente como afecta de neurofibromatosis tipo 1 (NF1) o enfermedad de Von Recklinghausen con múltiples neurofibromas, manchas café con leche y nódulos de Lisch. Su padre (no diagnosticado de NF1) falleció por accidente de circulación a los 38 años. La madre presenta a la exploración dos manchas café con leche y acude a la consulta de consejo genético con su nueva pareja donde se plantea un diagnóstico genético pre implantación (DGP).', '¿Está indicado en este caso un DGP?', '[{"position": 1, "text": "Sí, al tener la madre 2 manchas café con leche es portadora y el DGP está indicado con estos datos."}, {"position": 2, "text": "Está indicado tras detectar la mutación causante en el caso índice y eventualmente en su madre."}, {"position": 3, "text": "No está indicado pues la NF1 responde a mutaciones en el gen de la neurofibromin (17q11.2), con herencia recesiva."}, {"position": 4, "text": "No, dos manchas café con leche no son diagnósticas y su nueva pareja es muy improbable que sea portador (la NF1 es una enfermedad poco frecuente)."}, {"position": 5, "text": "Está indicado con estos datos un DGP consistente en seleccionar embriones in vitro, para implantar en el útero materno aquellos sin la mutación."}]'::jsonb, 5, 2, 'definitiva', 'Lo primero es detectar la mutación y una vez detectada, si la madre es portadora, proseguir con el DGP.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-40569dd34287', 'b3818ab935c1df0dba78b5135c87f94faeb27700', NULL, NULL, NULL, false, false, 'Hematología', 'Una mujer de 43 años consulta a su médico de Atención Primaria por cansancio, gingivorragia y petequias. Se realiza analítica en la que destaca: anemia de 8 gr/dl, trombopenia de 4000/microlitro y leucopenia de 1200/microlitro con neutropenia absoluta. En estudio de coagulación se observa alargamiento del APTT (43″), actividad de la protrombina disminuida (55%), hipofibrinogenemia (98 mg/dl) y presencia de concentración elevada de D-Dimero y monómeros de fibrina. Se remite para estudio hematológico urgente, realizándose un aspirado de médula ósea en el que se observa infiltración masiva por elementos inmaduros de núcleo hendido y bastones de Auer en el citoplasma.', '¿Cuál es el diagnóstico más probable en este paciente?', '[{"position": 1, "text": "Leucemia mieloide crónica."}, {"position": 2, "text": "Leucemia aguda promielocítica."}, {"position": 3, "text": "Leucemia aguda monoblástica."}, {"position": 4, "text": "Leucemia linfoide crónica."}, {"position": 5, "text": "Leucemia linfoide aguda."}]'::jsonb, 5, 2, 'definitiva', 'Tras leer el enunciado tan largo, quedarse sin aire, repasarlo y agobiarnos, llega el momento de echarle cara y agarrarnos a algo que sea muy característico. Una mujer con pancitopenia. Una médula ósea que muestra infiltración masiva por elementos inmaduros que están proliferando sin parar…¿con bastones de Auer? Leucemia aguda promielocítica. Esos bastones son la fusión de gránulos primarios de los mielocitos en desarrollo. Lo dicen Robin&Cotran en la página 696 de su libro «Patología general» [1]. También lo dicen Carr y Rodak en su libro «Atlas de hematología clínica» en la página 157 [2].', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-954908e56e01', '3c8d7b0685e595b4833338e98628442b24f093d7', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Mujer de 47 años de edad. Natural de Cochabamba (Bolivia), reside en España desde hace 8 años. A mediados de 2009 comienza con palpitaciones, disnea y edemas progresivos en extremidades inferiores. Es diagnosticada de insuficiencia cardiaca secundaria a miocardiopatía por enfermedad de Chagas.', '¿Cual es el agente etiológico de esta enfermedad endémica en varios paises de Latinoamérica?', '[{"position": 1, "text": "Toxoplasma gondii."}, {"position": 2, "text": "Trypanosoma brucei."}, {"position": 3, "text": "Lehismania donovani."}, {"position": 4, "text": "Giardia lamblia."}, {"position": 5, "text": "Trypanosoma cruzi."}]'::jsonb, 5, 5, 'definitiva', 'La respuesta correcta es la quinta. La causa de la enfermedad de Chagas es Trypanosoma cruzi.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-ce9ff0071420', 'd820777a05a75135f192114a9b2f2972bf3c5c91', NULL, NULL, NULL, false, false, 'Cirugía General', 'Niño de de año y medio que acude a urgencias por presentar dolor abdominal e ictericia. En la exploración se palpa una masa abdominal. Al realizar una ecografía se observa la presencia de un quiste de colédoco.', '¿Qué actitud terapéutica adoptaremos?', '[{"position": 1, "text": "Se realizara una punción percutánea para lavado peritoneal para comprobar que el quiste contiene bilis para dejar un drenaje que mejore el dolor abdominal."}, {"position": 2, "text": "Se indicará una resección radical de toda la vía bilair para sustiruirla por un asa de intestino."}, {"position": 3, "text": "Se de indicará una laparotomía exploradora y un drenaje del quiste y cuando remita la dilatación se retirará el drenaje."}, {"position": 4, "text": "Se realizará una colangioresonancia para delimitar el quiste y se indicará una laparotomía para la resección del quiste y anastomsosis de la vía biliar."}, {"position": 5, "text": "Es necesaria la gammagrafía con HIDA para delimitar el quiste y poder realizar el drenaje percutáneo con seguridad."}]'::jsonb, 5, 4, 'definitiva', 'Creo que la respuesta correcta es la 4 el quiste de colédoco es una patología rara pero su tratamiento es quirúrgico y consiste en la resección del quiste y hepaticoyeyunosotmía. La colangioresonancia es necesaria para elegir al técnica adecuada para las cuatro clases de quiste de colédoco existentes (clasificación de Todani).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c1d84f7f6d32', '680b417c3bb97cdec635c989160cf986a1d90a77', NULL, NULL, NULL, false, false, 'Pediatría', 'Un lactante de 7 meses acude a urgencias derivado por su pediatra de zona por sospecha de enfermedad de Kawasaki. Refiere fiebre de hasta 39,5ºC de 5 días de evolución que no cede a pesar del tratamiento con amoxicilina pautado hace 72 horas por sospecha de faringoamigdalitis aguda. Durante las últimas 24 horas asocia exantema eritematoso ni pruriginoso de evolución cefalocaudal y durante los últimos días llama la atención a sus padres la tos y una intensa conjuntivitis. No refieren rinorrea. A la exploración clínica presenta subcrepitantes en ambas bases pulmonares sin taquipnea ni signos de dificultad respiratoria. A la exploración orofaríngea se evidencian manchas blanquecinas en mucosa yugal.', '¿Cuál es el diagnóstico más probable?', '[{"position": 1, "text": "Enfermedad de Kawasaki."}, {"position": 2, "text": "Escarlatina."}, {"position": 3, "text": "Reacción alérgica a la amoxicilina."}, {"position": 4, "text": "Mononucleosis infecciosa."}, {"position": 5, "text": "Sarampión."}]'::jsonb, 5, 5, 'definitiva', 'La respuesta correcta es la 5. La pista está en las lesiones blanquecinas de la mucosa yugal que corresponden a las manchas de Koplik, que son patognomónicas del sarampión, aunque como observación diría que suelen aparecer en la fase prodrómica de la enfermedad y muchas veces ya no se ven cuando aparece el exantema. En este caso está describiendo un sarampión complicado con una neumonía. Muy oportuna esta pregunta en el momento actual.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9f8a5f7034b9', '3dca6ffbb41e59fa668970079e609e39ec08b34e', NULL, NULL, NULL, false, false, 'Urología', 'Un paciente varón de 45 años de edad con antecedentes de litiasis úrica con cólicos nefríticos expulsivos de repetición desde hace 25 años, acude a Urgencias refiriendo palpitaciones y dolor lumbar derecho intenso desde hace 2 horas antes. El análisis de orina muestra un pH de 5,5 y leucocituria sin proteinuria. El ECG confirma una fibrilación auricular no conocidad previamente. En la bioquímica sanguínea destaca una creatinina de 0.9mg/dl, un calcio de 11mg/dl y una LDH de 950 U/l.', '¿Cual es la maniobra diagnóstica mas útil a realizar?', '[{"position": 1, "text": "Radiografía simple de abdomen."}, {"position": 2, "text": "UIV."}, {"position": 3, "text": "TAC con contraste."}, {"position": 4, "text": "ECOgrafía abdominal."}, {"position": 5, "text": "ECOCARDIOGRAFÍA doppler."}]'::jsonb, 5, 3, 'definitiva', 'En esta pregunta tengo mas dudas en cuanto a cual es la respuesta correcta, pues debemos interpretar cual es la prueba mas útil, con cual podemos obtener mas rendimiento. No obstante esta situación depende así mismo de los servicios de radiología de cada centro y de sus preferencias. Me centraré en la parte urológica, dejando de lado el resto de sintomatología. • La Rx de abdomen es el primer estudio de imagen a realizar por ser rápido, sencillo y prácticamente inocuo (salvo en niños y gestantes). El 90% de los cálculos son radiopacos y por lo tanto visibles, pero la sensibilidad de esta prueba, utilizada de manera aislada, disminuye hasta el 45-59%. Es una prueba obligatoria en toda sospecha de dolor cólico. No obstante con menor rendimiento que las otras. Aunque la historia urológica hable de litiasis úrica (radiotrasparente), con un ph ácido que reafirma el diagnóstico de origen úrico, no podemos descartar nunca la litiasis de oxalato cálcico que puede aparecer de forma sincrónica. • La UIV me parece una de las opciones con mayor rendimiento. Nos dará claridad diagnóstica de obstrucción, de su magnitud y de su repercusión renal. Considerada durante mucho tiempo la exploración de elección para el estudio de los pacientes con litiasis renal. Es una prueba con sensibilidad y especificidad elevadas (87-90% y 94-100%, respectivamente), relativamente inocua, y al alcance de todos los hospitales. Nos informa del número, tamaño, forma y situación del cálculo, así como del estado funcional del riñón afecto. • El TAC con contraste me parece la opción con mayor rendimiento. Sirve para descubrir litiasis que otras pruebas no logran encontrar y nos da una imagen global del resto de estructuras. Gran rendimiento pero también mas cara, mas tiempo, mas radiación. Se ha confirmado como una exploración de gran sensibilidad y especificidad, superando a las anteriores pruebas (94-100% y 92-100%, respectivamente, para la detección de cálculo ureteral) y con sus numerosas ventajas se ha convertido en el examen de referencia por lo que se espera que reemplazará a UIV y la ecografía en todo el mundo. Realiza un barrido helicoidal con cortes de 5 mm que permite la detección de cálculos de hasta 2 mm. Con la administración de contraste, permite la evaluación de la función renal. • La Ecografía es una prueba rápida, barata e inocua, pero muy radiólog-dependiente. Da gran información renal sobre repercusión obstructiva, pero menor calidad de cara a encontrar una litiasis. La ecografía sólo detecta cálculos mayores de 4 mm, situados en la unión pielo-ureteral o la unión urétero-vesical, mientras que el uréter lumbar y pelviano es poco accesible debido a la interposición de las asas intestinales. Por ello, la ecografía realizada de manera aislada es poco sensible (20-45%) para la detección de cálculos, pero asociada a la radiografía simple de abdomen aumenta su sensibilidad y especificidad. • La ecocardiografía doppler no tiene uso en el diagnóstico urológico. Mi respuesta sería la TAC con contraste ev y fase excretora (respuesta (c).), en cuanto a rendimiento, sensibilidad y especificidad. Hay servicio de radiología mas hábiles o predispuestos a una u otra. Sin olvidar que la Rx de abdomen siempre debe hacerse en la sospecha de un cólico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-0bfcd1911398', '28554a62010cae60e4dfceb66e47a00e2b7d9f59', NULL, NULL, NULL, false, false, 'Dermatología', 'Hombre de 62 años con antecedentes de hábito enólico importante, portador de virus de hepatitis C, sigue tratamiento con Ibuprofeno por una tendinitis en hombro derecho, acude a su dermatólogo porque despues de pasar dos semanas de vacaciones en la playa observa la aparición de ampollas tensas en dorso de manos. A la exploración ademas de localización y ligera hipertricosis malar.', 'El diagnóstico más probable es:', '[{"position": 1, "text": "Epidermolisis ampollosa adquirida."}, {"position": 2, "text": "Porfiria cutánea tarda."}, {"position": 3, "text": "Reacción fototóxica."}, {"position": 4, "text": "Dermatitis de contácto."}, {"position": 5, "text": "Porfiria aguda intermitente."}]'::jsonb, 5, 2, 'definitiva', 'Porfiria Cutánea Tarda: el 60% de los pacientes con PCT, son varones, muchos de ellos ingieren alcohol en exceso, las mujeres que la desarrollan suelen estar en tratamiento con fármacos que contienen Estrógenos. La mayoria son varones con indicios de sobrecarga de hierro, esta sobrecarga reduce la actividad del enzima uroporfirinógeno descarboxilasa, que lleva a la elevación de uroporfirinas. Se han implicado en la precipitación de la PCT adquirida las infecciones por VHC y VIH. Existe una forma hereditaria con patrón AD. Los pacientes con PCT, presentan ampollas en piel fotoexpuesta, más frecuente en dorso de manos y cuero cabelludo. Además de la fragilidad, pueden desarrollar hipertricosis, hiperpigmentación, alopecia cicatricial e induración esclerodérmica.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-fb01f649b5d3', '306b31edc36d3b8cd01216149404d217c5dede0e', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Paciente varón de 26 años de edad, deportista de competición, es estudiado porque su hermano ha tenido una muerte súbita. Las pruebas complementarias detectan la existencia de una miocardiopatía hipertrófica obstructiva.', 'Señale la opción FALSA respecto a dicha patología:', '[{"position": 1, "text": "El tratamiento con betabloqueantes ayuda a reducir los síntomas."}, {"position": 2, "text": "Se debe recomendar el abandono del deporte de competición."}, {"position": 3, "text": "La digoxina es útil para reducir el gradiente subaórtico."}, {"position": 4, "text": "Los diuréticos se deben evitar o utilizar con gran cuidado."}, {"position": 5, "text": "Dado el carácter hereditario de la patología se debe realizar estudio de despistaje en el resto de familiares directos."}]'::jsonb, 5, 3, 'definitiva', 'Tenemos un miocardio más grueso de lo debido, con predominio en el septo, y que además está tan grueso que llega a obstruir la salida del VI, produciendo una estenosis “funcional” con gradiente de presiones. Nuestro objetivo será, en primer lugar, “relajar” el miocardio: para ello nos conviene un betabloqueante, mientras que la digoxina, como buen inotropo positivo, aumenta el gradiente y está contraindicada. El deporte no es muy recomendable, dado el riesgo aumentado de muerte súbita que tiene esta patología. Y si tenemos un septo gordo, que protruye en la cavidad del VI, no nos conviene hacer una depleción de volumen, pues estaríamos también aumentando el gradiente. En cuanto a la 5, es cierta: es conveniente realizar una exploración cuidadosa y un ECG en los familiares de pacientes con hipertrófica.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-98e44f4df7bb', '183e5cceb98d97f507b49a491db295de9f3b0bca', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'Hombre de 71 años, camarero jubilado, no fumador, que consulta por ronquidos nocturnos. El paciente tiene un índice de masa corporal de 31,5 Kg/m2 y refiere ligera somnolencia diurna postprandial (Escala de Somnolencia de Epworth de 3) sin otros síntomas, signos o antecedentes clínicos relevantes. El índice de apnea­-hipopnea obtenido en la polisomnografía fue de 18.', 'Con estos datos, ¿cuál es la medida a adoptar más adecuada en este paciente?', '[{"position": 1, "text": "Medidas higiénico-dietéticas y control evolutivo."}, {"position": 2, "text": "Uvulopalatofaringoplastia."}, {"position": 3, "text": "CPAP (Presión Positiva Continua en la Vía Aérea) nasal."}, {"position": 4, "text": "Ventilación mecánica no invasiva."}, {"position": 5, "text": "Oxigenoterapia nocturna."}]'::jsonb, 5, 1, 'definitiva', 'Con un Indice de Apneas-Hipopneas de menos de 30, y en ausencia de síntomas llamativos de SAOS y en ausencia de profesiones de riesgo como podría ser conductor profesional, etc, lo correcto es el control de peso y el resto de medidas higiénico-dietéticas, con seguimiento periódico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-1bae610281a7', '304bf92300ae0be0151492c4178c5d94c6d36b41', NULL, NULL, NULL, false, false, 'Endocrinología', 'Un paciente de 74 años con resección intestinal tras una trombosis mesentérica, acude a consulta por cansancio y dolor óseo. Había sufrido una fractura de Colles tres meses antes. Los estudios analíticos ponen de manifiesto una anemia de 9.5 g/dl, microcítica, albúmina 3.5 g/di, calcio 7.5 mg/dl, fosfato 2.0 mg/dl y fosfatasa alcalina 224 UI (normal hasta 120 UI). Las radiografías del fémur muestran unas bandas radiolúcidas perpendiculares a la cortical en el lado interno de su parte superior.', '¿Cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Osteoporosis."}, {"position": 2, "text": "Enfermedad de Paget."}, {"position": 3, "text": "Osteitis fibrosa."}, {"position": 4, "text": "Metástasis de cáncer de próstata."}, {"position": 5, "text": "Osteomalacia."}]'::jsonb, 5, 5, 'definitiva', 'Aunque esta no me la habían asignado, la respondo también ya que trata un tema de endocrinología: la vitamina D. En este caso hay datos importantes como el antecedente de resección intestinal, la hipocalcemia y ha hipofosforemoia; esto nos debe hacer pensar en un déficit de vitamina D por malabsorción y por tanto, en una osteomalacia. El resto de datos: fractura previa, dolores y la radiografía apoyan el diagnóstico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-87d0249711f4', '0fee642c7e405e19080e1c2b99199c462a1914c0', NULL, NULL, NULL, false, false, 'Pediatría', 'Lactante de 1 mes de vida que acude a urgencias del hospital remitido por su pediatra por ictericia. Refiere ésta desde hace 10 días y ha ido en aumento. En la analítica de sangre destaca una bilirrubina total de 7mg/dl siendo la bilirrubina indirecta de 1,5mg/dl.', 'La causa más probable, de entre las siguientes, de esta ictericia es:', '[{"position": 1, "text": "Atresia de vías biliares."}, {"position": 2, "text": "Ictericia por lactancia materna."}, {"position": 3, "text": "Isoinmunización 0-A de aparición tardía."}, {"position": 4, "text": "Enfermedad de Gilbert."}, {"position": 5, "text": "Esferocitosis hereditaria."}]'::jsonb, 5, 1, 'definitiva', 'El aumento de la bilirrubina directa nos descarta de inmediato el resto de las opciones donde el aumento de bilirrubina total sería a expensas de la bilirrubina indirecta. La atresia de vías biliares es la principal indicación de trasplante hepático infantil.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-611d5bcd94a3', 'fa6bc499ed3bb1385dd2f776c3b2050d3cc07bed', NULL, NULL, NULL, false, false, 'Hematología', 'En una mujer de 29 años se hallan en el curso de una analítica rutinaria los siguientes parámetros: Hb 11.5 g/dL, VCM 70 fl, HCM 28 pg, Ferritina 10 ng/mL, leucocitos 5.200/mm3, plaquetas 335.000/mm3. La exploración física es normal.', 'La exploración mas indicada en esta situación es:', '[{"position": 1, "text": "Exploración ginecológica."}, {"position": 2, "text": "Estudio de sangre oculta en heces."}, {"position": 3, "text": "Estudio radiológico del aparato digestivo."}, {"position": 4, "text": "Electroforesis de hemoglobinas."}, {"position": 5, "text": "Test de Cooms."}]'::jsonb, 5, 1, 'definitiva', 'La causa más frecuente en mujer joven de anemia ferropénica microcítica es por pérdidas ginecológicas crónicas.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-234a24b147bd', 'db2e993c0dc8582f89024b2e8190ed2fc0feeaa5', NULL, NULL, NULL, false, false, 'Hematología', 'Hombre de 71 años de edad que presenta analítica con pancitopenia severa sin presencia de células inmaduras y con estudio medular sugestivo de anemia aplásica grave.', '¿Cuál sería el abordaje terapéutico fundamental?', '[{"position": 1, "text": "Tratamiento con metilprednisolona a dosis de 1 g/Kg/día durante 5 días."}, {"position": 2, "text": "Estudio de hermanos y si alguno es HLA compatible, trasplante alogénico de progenitores hematopoyéticos."}, {"position": 3, "text": "Terapia inmunosupresora con ciclosporina e inmunoglobulina antitimocítica."}, {"position": 4, "text": "Soporte hemoterápico."}, {"position": 5, "text": "Quimioterapia y si respuesta trasplante autólogo de progenitores hematopoyéticos."}]'::jsonb, 5, 3, 'definitiva', 'Anemia aplásica grave y no candidato a transplante alogénico por su edad. Antisupresores parece lo más idóneo.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4c526b59493e', 'cf0949d6ab11048810ca752f9cdadd44705ff7e7', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Mujer de 29 años, obesa, sin antecedentes de interés, que consulta por cefalea pulsátil, bilateral, intensa, de un mes de evolución, acompañada de diplopia horizontal y episodios de amaurosis monocular de segundos de duración. La exploración es normal, salvo por la presencia de papiledema bilateral.', '¿Cuál de estas pruebas cree que le va a permitir confirmar plenamente su diagnóstico?', '[{"position": 1, "text": "Ecografía de troncos supraaórticos."}, {"position": 2, "text": "Resonancia magnética de cráneo."}, {"position": 3, "text": "Electroencefalograma."}, {"position": 4, "text": "Punción lumbar."}, {"position": 5, "text": "Potenciales evocados visuales."}]'::jsonb, 5, 4, 'definitiva', 'Nuevamente nos presentan un caso para realizar un diagnóstico y luego, en este caso, realizar una prueba confirmatoria. Ahora el síntoma guía es el papiledema bilateral que es indicativa de hipertensión intracraneal. Aunque no comenta se haya descartado una lesión ocupante de espacio, dado que la exploración neurológica normal y con el resto de síntomas se deduce que se trata de una hipertensión intracraneal idiopática o pseudotumor cerebri. Entre los otros datos sugestivos de esta entidad están: mujer en edad reproductiva, obesidad, y diplopia (por afectación de VI par craneal). Es característica que la cefalea y la borrosidad visual se agraven súbitamente por las mañanas al levantarse o al cambiar de postura produciendocegueras transitorias (Neurología, Zarranz). La punción lumbar presenta, de forma invariable, un incremento de presión de líquido cefalorraquídeo, por lo cual la respuesta correcta es la 4.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-51a385081d20', 'c5d0e37650f77aa3b5b53ac2799b26faa949b044', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Un chico de 17 años, deportista y sin antecedentes de interés, acude al médico por presentar ictericia conjuntival ocasionalmente. Niega ingesta de fármacos y dolor abdominal. En los análisis realizados se observan cifras de ALT, AST, GGT y FA normales, con bilirrubina total de 3,2 mg/dl y bilirrubina directa de 0,4 mg/dl. No tiene anemia y el hígado es ecográficamente normal.', '¿Cuál es su diagnóstico?', '[{"position": 1, "text": "Síndrome de Rotor."}, {"position": 2, "text": "Coledocolitiasis."}, {"position": 3, "text": "Síndrome de Dubin-Johnson."}, {"position": 4, "text": "Hepatitis aguda."}, {"position": 5, "text": "Síndrome de Gilbert."}]'::jsonb, 5, 5, 'definitiva', 'Un aumento de la bilirrubina indirecta menor de 5 (de manera intermitente, bajo situaciones de estrés) en un chico joven sano nos debe hacer pensar en un síndrome de Gilbert. En el síndrome de Rotor, Dubin-Johnson y en la coledocolitiasis hay aumento de la bilirrubina directa. De tratarse de una hepatitis aguda debería haber una elevación de las transaminasas.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4291ec4b5473', '6be0e47fa36be0944942b7fcdcff0dacb8834174', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'En un paciente con enfermedad pulmonar obstructiva crónica (EPOC) leve en fase estable se evidencia poliglobulia e insuficiencia respiratoria. En la radiografía de tórax no se aprecian alteraciones reseñables.', '¿Cuál de los siguientes procedimientos consideraría realizar en primer lugar para descartar la coexistencia de otras enfermedades que puedan justificar los hallazgos descritos?:', '[{"position": 1, "text": "Poligrafía respiratoria."}, {"position": 2, "text": "Ecocardiograma."}, {"position": 3, "text": "Tomografía computarizada torácica."}, {"position": 4, "text": "Gammagrafía pulmonar."}, {"position": 5, "text": "Punción de médula ósea."}]'::jsonb, 5, 1, 'definitiva', 'El planteamiento es dudoso por falta de datos suficientes. Por frecuencia, la respuesta correcta podria ser la la Poligrafia respiratoria, sobre todo en el caso de que se trate de un paciente obeso, dato que desconocemos, pero podria ser correcta tambien la 2 (Ecocardiograma) en el caso de sospecha de cardiopatia asociada, menos frecuente pero tambien posible. La asociacion de EPOC con SAOS es una causa frecuente de deterioro de la EPOC, mayor del que le corresponderia por afectacion funcional.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-755e31d1301a', '8a6e80cea63e778d54321d56979b1cabd37a7fa2', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Un hombre de 52 años sin enfermedades concomitantes, acude a urgencias por melenas de 24 horas de evolución sin repercusión hemodinámica. Niega consumo de antiinflamatorios no esteroideos. El hematocrito es de 33% y el resto de la analítica es normal. La endoscopia digestiva alta realizada de forma urgente a las 6 horas del ingreso muestra un estómago normal, sin sangre ni restos hemáticos y una úlcera excavada de 8 mm de diámetro en cara anterior del bulbo duodenal con «vaso visible» en su base y sin sangrado activo.', '¿Cuál de las siguientes afirmaciones es cierta?', '[{"position": 1, "text": "En la endoscopia inicial está indicado aplicar una terapéutica endoscópica y posteriormente instaurar tratamiento endovenoso con dosis altas de un inhibidor de la bomba de protones. Esta estrategia ha demostrado reducir el riesgo de recidiva hemorrágica y la mortalidad."}, {"position": 2, "text": "En la endoscopia inicial, dada la ausencia de sangrado activo, no está indicado aplicar una terapéutica endoscópica. Posteriormente, para reducir el riesgo de recidiva hemorrágica, se deberá instaurar tratamiento endovenoso con dosis altas de un inhibidor de la bomba de protones."}, {"position": 3, "text": "n la endoscopia inicial está indicado aplicar una terapéutica endoscópica. No se ha podido demostrar que instaurar posteriormente tratamiento con dosis altas de un inhibidor de la bomba de protones aporte beneficio adicional alguno."}, {"position": 4, "text": "Dado que se trata de una úlcera complicada (hemorragia) la mejor opción terapéutica, una vez resuelto el episodio hemorrágico, es una vagotomía y piloroplastia."}]'::jsonb, 4, 1, 'definitiva', 'Se trata de una úlcera de grado IIa (clasificación de Forrest), con alto riesgo de recidiva. Por eso, se indica claramente el tratamiento endoscópico y la hospitalización con tratamiento endovenoso con IBPs (en nuestro medio es habitualmente el omeprazol) durante al menos 72 horas. La cirugía está indicada en hemorragias masivas o refractarias al tratamiento médico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-001b723409be', '6d900fa75f8448f45ac3b93349adf0d42b1aeea4', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Un hombre de 47 años, fumador activo, con historia de abuso de drogas por vía parenteral acude a Urgencias por un cuadro de 2 horas de evolución de dolor costal izquierdo pleurítico de inicio agudo y disnea progresiva hasta hacerse de reposo. En las 2 semanas previas había presentado febrícula, malestar general y tos seca. A la exploración el paciente impresiona de gravedad, está taquipneico a 36 rpm, con tiraje supraclavicular, saturación de oxígeno por pulsioximetría de 81%, cianosis, sudoración, taquicardia a 135 latidos por minuto y PA de 75/47 mm Hg. La tráquea está desviada hacia el lado derecho y la auscultación demuestra ausencia completa de murmullo vesicular en hemitórax izquierdo. Se realiza una serología VIH que resulta positiva y presenta un recuento de linfocitos CDA de 176 células/ml.', '¿Cuál es el diagnóstico más probable?', '[{"position": 1, "text": "Rotura de bulla enfisematosa subpleural."}, {"position": 2, "text": "FNeumonía bacteriana necrotizante adquirida en la comunidad."}, {"position": 3, "text": "Tuberculosis pulmonar."}, {"position": 4, "text": "Neumonía por Pneumocystis jiroveci."}]'::jsonb, 4, 4, 'definitiva', 'Paciente con factor de riesgo para adquisición de VIH, que acude a urgencias por un cuadro de inicio subagudo de 2 semanas de evolución (febrícula, malestar general y tos seca) que se agrava de forma brusca (dolor pleurítico) y progresiva (disnea). El examen físico sugiere un neumotórax (taquipnea, tiraje, baja saturación, cianosis, diaforesis, taquicardia, tráquea desviada y ausencia de murmullo vesicular). Tiene una serología de para VIH positiva y un CD4 menos de 200 cel./mL. La radiografía muestra hiperclaridad en el campo pulmonar izquierdo con ausencia de vasos entre el límite del pulmón y la pared torácica del lado izquierdo, desplazamiento del mediastino y de la tráquea al lado derecho, además se observa un muñón en el hilio pulmonar izquierdo que correspondería al pulmón colapsado. La sospecha de VIH es alta y aunque está pendiente de confirmación, en la urgencia es válido asumir esta opción. Dicho esto, busco patologías que se asocien a este cuadro, la rotura de una bulla si bien se relaciona con la aparición de síntomas bruscos no va de la mano con los otros síntomas (hay que buscar algo que explique todo o casi todo), la neumonía si bien es cierto puede estar relacionada con buena parte de los síntomas no se correlaciona con la imagen, la TB pulmonar podría estar manifestarse con todo lo antes dicho y provocar un neumotórax, pero aquí ante un cuadro respiratorio con más de 7 días de evolución que se complica de forma brusca, en un paciente con una alta sospecha de infección por VIH la opción más clara va por la neumonía por P. jirovecii. En los pacientes con Pneumocystis, el 10%, aparecen neumatoceles que en ocasiones pueden abrirse al espacio pleural produciendo un neumotórax espontáneo. Recordando, los gérmenes más frecuentes en la afectación pulmonar en pacientes con infección por VIH/SIDA son P. jiroveci (solo o asociado a tuberculosis u otras micobacterias), S. pneumoniae, H. influenzae, S. aureus, citomegalovirus, Legionella, estafilococos y bacilos gramnegativos (Pseudomonas). Los pacientes con neumonía por P. jirovecii presentan, en el 90% de casos, un recuento de CD4< 250 cel./mL. Otros agentes que pueden provocar afección pulmonar con menor frecuencia son Rhodococcus equi, Nocardia, Aspergillus, Cryptococcus, Toxoplasma yLeishmania. Aunque la frecuencia de las diferentes infecciones oportunistas ha variado como consecuencia de la administración de los tratamientos antirretrovirales de alta eficacia, nuestro paciente estaría en un escenario donde aún no recibió TARGA.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-fbef65800fdf', '473caa6b3a7a2df724bc683636acdd79061d8924', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Hombre de 46 años usuario de drogas por vía parenteral que acude a urgencias presentando fiebre con escalofríos, confusión mental, mialgias difusas y dolor intenso en mano izquierda de 24 horas de evolución sin claros signos flogóticos locales. No refiere ningún antecedente traumático. A la exploración destaca: temperatura 38,9“C, 120 latidos por minuto, frecuencia respiratoria 30/min, presión arterial 90/54 mm Hg. En la analítica destaca una leucocitosis con desviación izquierda (25.000 leucocitos/mm3, 80% neutrófilos); aumento de las cifras de creatinina (1,6 mg/dL) y de CK (138 U/L).', 'De entre los siguientes, ¿cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Fascitis necrotizante estreptocócica."}, {"position": 2, "text": "Gangrena por Clostridium spp."}, {"position": 3, "text": "Celulitis por micobacterias."}, {"position": 4, "text": "Erisipela."}]'::jsonb, 4, 1, 'definitiva', 'Tengo mis dudas entre la 1 y la 2; excepcionalmente C. botulinum puede infectar heridas traumáticas o por punción en UDVP que utilizan heroína marrón o causar sinusitis en cocainómanos. Por otra parte, el caso se puede referir a una sepsis grave con pobre manifestación inicial a primera vista, con rabdomiolisis incipiente y dolor muscular, en este caso puede tratarse de una fascitis necrotizante, donde el germen más frecuentemente implicado es el S. pyogenes.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-ca3cf606201f', '00c5a2ad2f0e3c32d65496a0b4c16f6a76b86beb', NULL, NULL, NULL, false, false, 'Reumatología', 'Hombre de 40 años, sin antecedentes de interés,que presenta artritis aguda de rodilla derecha de 5 días de evolución así como febrícula de hasta 37,7°C. No refiere antecedente traumático. Presenta derrame articular, calor a la palpación y limitación funcional por el dolor. Se practica artrocentesis diagnóstica en la que se evidencian 30000 cels/mícroL con predominio de neutrófilos. En el examen con luz polarizada se descubren cristales romboidales y cilíndricos con birrefringencia débilmente positiva. En la radiografía simple de rodillas se descubren depósitos radiodensos en el menisco externo de la rodilla.', 'Señale la respuesta FALSA:', '[{"position": 1, "text": "El tratamiento inicial consistirá en antiinflamatorios no esteroideos, así como la aspiración del líquido sinovial."}, {"position": 2, "text": "Es conveniente la realización de cultivo del líquido sinovial para descartar sinovitis infecciosa."}, {"position": 3, "text": "Una vez pasado el brote agudo habrá que instaurar tratamiento con alopurinol para disminuir la incidencia de nuevos brotes de artritis en el futuro."}, {"position": 4, "text": "El diagnóstico más probable es una artritis aguda por depósito de cristales de pirofosfato cálcico (pseudogota)."}]'::jsonb, 4, 3, 'definitiva', 'Es una condrocalcinosis. No existe tratamiento para esta enfermedad, únicamente tratamiento para los brotes (colchicina, AINEs o corticoides) aunque en ocasiones si los brotes son habituales se deja la colchicina mantenida. El alopurinol no ha demostrado ninguna eficacia en esta artropatía por microcristales, sí en la gota.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e734390cdd1b', '54fc22a43b3ba24aa782d623aa5798d47861965a', NULL, NULL, NULL, false, false, 'Medicina Intensiva y Urgencias', 'Hombre de 35 años de edad sufre una quemadura eléctrica de alto voltaje (3000 voltios) por contacto directo con cable con su mano izquierda.', 'Al ingreso presenta contractura en flexión de la mano, palidez de los dedos y ausencia de pulso radial y cubital a la palpación ¿Cuál es la medida invasiva de urgencia a realizar?', '[{"position": 1, "text": "Bloqueo axilar con catéter."}, {"position": 2, "text": "Escarotomía descompresiva."}, {"position": 3, "text": "Monitorización de presión intracompartimental."}, {"position": 4, "text": "Escarectomía."}]'::jsonb, 4, 3, 'definitiva', 'La 3. Ante la sospecha de síndrome compartimental la medida invasiva de urgencia a realizar sería medir la presión intracompartimental y, según el resultado, proceder al tratamiento.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-76b61a259542', 'af570bd874b3d5b25a0549b0c3bf8fe8c0852686', NULL, NULL, NULL, false, false, 'Endocrinología', 'Una mujer de 35 años consulta por un nódulo tiroideo derecho detectado incidentalmente una mañana al observarse en el espejo un bulto en la cara anterior del cuello. Tras los estudios pertinentes se decide intervenir quirúrgicamente a la paciente realizándose una tiroidectomia total con vaciamiento del componente ganglionar central. Siendo el informe del patólogo de nódulo tiroideo de 2,3 cm ocupado en su totalidad por un carcinoma papilar de tiroides, variante células altas, sin infiltración vascular pero sí capsular. Las concentraciones de tiroglobulina 24 h después de la tiroidectomia son de 14 ng/mL.', '¿Cuál sería el siguiente paso que usted daría en esta paciente?', '[{"position": 1, "text": "Remitir de nuevo a la paciente al cirujano para que realice un vaciamiento ganglionar laterocervical derecho."}, {"position": 2, "text": "Iniciar tratamiento con una dosis de levotiroxina supresora de TSH y citarla a revisión 6 meses después con una nueva determinación analítica de tiroglobulina y una ecografía cervical."}, {"position": 3, "text": "Solicitar un PET-TAC para ver si hay afectación ganglionar."}, {"position": 4, "text": "Demorar el inicio del tratamiento sustitutivo-supresor de TSH con levotiroxina y remitir la paciente al servicio de Medicina Nuclear para la administración de una dosis ablativa de 100 mCi de I131."}]'::jsonb, 4, 4, 'definitiva', 'La comprobación de la presencia de tiroglobulina en sangre y el desarrollo de técnicas mediante las cuales es posible determinarla, han permitido contar con un nuevo procedimiento para el control de pacientes con carcinoma papilar o folicular del tiroides. La tiroglobulina es sintetizada en las células foliculares y luego secretada a la circulación, por lo tanto, después de la tiroidectomía total debe desaparecer, si eso no ocurre hay que pensar en la existencia de restos de tejido de metástasis.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9fb32b23078a', 'c1f12c3805321a2832a2e7d233f2cb470f90f80a', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'Mujer de 38 años, no fumadora, diagnosticada previamente de rinitis atópica que acude por cuadro de dos meses consistente en tos y sibilantes intermitentes de predominio nocturno. Rx de tórax normal. Espirometría dentro de la normalidad con prueba broncodilatadora negativa.', '¿Cuál de las siguientes pruebas solicitaría a continuación?', '[{"position": 1, "text": "Rx de senos paranasales."}, {"position": 2, "text": "TAC torácico."}, {"position": 3, "text": "Test de metacolina."}, {"position": 4, "text": "Prick-test."}]'::jsonb, 4, 3, 'definitiva', 'Una espirometria normal y un test broncodilatador negativo puntualmente no excluye asma, y la clínica de la paciente es altamente sugestiva de asma, por lo que un test de metacolina permitiría confirmar el diagnostico, al menos de hiperreactividad bronquial.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8435a22379db', '2b43cbd86b2b0f7793aa50046bcbf5336ecba8d0', NULL, NULL, NULL, false, false, 'Psiquiatría', 'Un hombre de 80 años es llevado a Urgencias por la policía a encontrarle por la noche, en la calle, a varios bloques de su domicilio, algo perdido. Dice al médico de Urgencias «me encuentro bien, estaba paseando y me he perdido». La revisión, por sistemas, es anodina. Al preguntarle por su medicación, no recuerda. En su historial constan glipizida, atenolol y acenocumarol. Ha estado en Urgencias 3 veces en los últimos tres meses por «mareo», dolor lumbar y un INR de 5. Refiere independencia en actividades básicas e instrumentales de la vida diaria. No hay evidencia de familiares o amigos cercanos. Varias referencias del trabajo social del área indican que rechaza ayudas o visitas médicas o de enfermería. En la exploración física, únicamente destaca temperatura de 37.7, IMC de 16, PA de 160/90, FC de 90 y SO2 de 99%. Tiene pérdida global de masa muscular. Está vestido con la bata de casa y huele a orina. Rechaza contestar a las preguntas del Minimental. En las pruebas de laboratorio destacan 13.000 leucos, Glucemia 300, hemoglobina glicosilada 11%, INR 0.9, en orina más de 50 leucocitos/campo, nitritos+ y urocultivo > 100.000 bacilos Gram negativos. Es ingresado en el hospital, recibe antibióticos, insulina y se reinicia acenocumarol con buena evolución. Está estable y quiere irse a su domicilio. La enfermera de planta dice que es incapaz de autoadministrarse la insulina.', '¿Cuál de los siguientes es el próximo paso para determinar la seguridad del paciente en su domicilio?', '[{"position": 1, "text": "Referir a Atención Primaria y trabajo social del área para determinar la seguridad en el domicilio."}, {"position": 2, "text": "Evaluación formal de la capacidad para tomar decisiones concernientes a su salud."}, {"position": 3, "text": "Evaluación para descartar demencia."}, {"position": 4, "text": "Evaluación para descartar depresión."}]'::jsonb, 4, 2, 'definitiva', 'Evaluar la capacidad no tiene que ver con quitar la autonomía al paciente, sino asegurarnos de que el paciente comprende y es consciente de las consecuencias de sus decisiones. De hecho es una medida de protección de los pacientes más frágiles para asegurar los mejores cuidados. Esto no lo hace un psiquiatra, sino el médico a cargo. Hay varios tests o entrevistas semiestructuradas para valorar la capacidad de los pacientes, y todos los médicos deberían conocer estos instrumentos. Es importante que sea el médico a cargo el que realiza esta valoración, porque es el que previamente informa al paciente (consentimiento informado) del plan terapéutico y es el que está mejor capacitado para evaluar si el paciente ha entendido todo: cuál es el problema médico, qué tratamiento se le propone, las alternativas si las hubiera, tener opción de aceptar alguna o rechazarlas y por qué, consecuencias de tomar esas decisiones (también las de no querer tratamiento), incluso valorar psicopatología susceptible de un PIC a Psiquiatría.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8e0a58761493', 'a22b2727eeac9864f8d808d22052f37bd696c2d9', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Luis es un joven de 25 años que sufrió esplenectomía tras accidente de bicicleta hace 1 año. Tiene un perro que Ie mordió hace 24 horas y le ha producido una pequeña herida en la mano derecha. Acude a su centro de salud (situada a 3 horas del hospital más cercano) por fiebre de 39ºC, dolor en la herida y malestar general. A la exploración PA 100/60 mm Hg, FC 110 latidos por minuto, ligera inflamación en la herida sin pus.', '¿Cual de las siguientes actuaciones está más indicada en este momento?', '[{"position": 1, "text": "Enviar al hospital para vacunar de rabia y tétanos y mantener en observación."}, {"position": 2, "text": "Limpiar la herida y administrar gamaglobulina inespecífica intramuscular."}, {"position": 3, "text": "Dar 400 mg de moxifloxacino oral y enviar al hospital."}, {"position": 4, "text": "Dar clindamicina 600 mg oral cada 8 horas y observación."}]'::jsonb, 4, 3, 'definitiva', 'Esta pregunta nos ha resultado complicada. La pregunta no tiene toda la información necesaria, pero usando lo que tenemos podemos intentar responder. El perro es doméstico, conocido y puede ser sometido a vigilancia, por lo tanto habría que esperar a que pase el periodo de observación y no se recomienda profilaxis. En este punto solo tendremos que preocuparnos por la posible bacteriemia que puede estar ocurriendo en un paciente con posibilidad de alto riesgo por asplenia. El tratamiento de elección en mordedura de perro es amoxicilina/clavulánico pero no está, así que podemos usar otro como clindamicina más una cefalosporina o clindamicina + moxifloxacino pero de igual forma no está contemplado entre las alternativas. En un primer intento contestamos la 4, pero la respuesta correcta es la 3, por la segunda parte de la pregunta; es un paciente de alto riesgo con signos incipiente de sepsis por lo que debe de enviarse al hospital, aquí la clave más que en el antibiótico está en la postura a tomar, en la segunda parte de cada respuesta.. Se podría impugnar ya que no dicen en cual comunidad ocurrió la mordedura (si fuera en Ceuta o Melilla el protocolo puede variar).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos')
